];

// Dropdown tabs (not simple links) — should show chevron and open on click
const DROPDOWN_TABS = [
  'Customers',
  'Suppliers',
  'Items',
  'Banking',
  'Accounts',
  'VAT',
  "Accountant's Area",
  'Reports',
];

// Tab → route → expected active tab mapping for route resolver
