    --ff-bg-primary: #0f172a;
    --ff-bg-secondary: #1e293b;
    --ff-bg-tertiary: #334155;
    --ff-bg-hover: #334155;

    --ff-surface-primary: #1e293b;
    --ff-surface-secondary: #334155;
    --ff-surface-elevated: #1e293b;

    --ff-text-primary: #f1f5f9;
    --ff-text-secondary: #e2e8f0;
