/**
 * Customers API
 * GET  /api/accounting/customers         - List customers (optional ?q= search)
 * POST /api/accounting/customers         - Create a new customer
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  // ─── GET: List customers ────────────────────────────────────────────────────
  if (req.method === 'GET') {
    try {
      const { q } = req.query;
      const searchTerm = typeof q === 'string' && q.trim() ? `%${q.trim()}%` : null;

      let rows: Row[];

      if (searchTerm) {
        rows = (await sql`
          SELECT
            id, name, email, phone, contact_person,
            payment_terms, credit_limit, is_active,
            vat_number, registration_number,
            created_at
          FROM customers
          WHERE
            name ILIKE ${searchTerm}
            OR email ILIKE ${searchTerm}
            OR vat_number ILIKE ${searchTerm}
            OR contact_person ILIKE ${searchTerm}
          ORDER BY name ASC
          LIMIT 200
        `) as Row[];
      } else {
        rows = (await sql`
          SELECT
            id, name, email, phone, contact_person,
            payment_terms, credit_limit, is_active,
            vat_number, registration_number,
            created_at
          FROM customers
          ORDER BY name ASC
          LIMIT 200
        `) as Row[];
      }

      return apiResponse.success(res, rows);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      // Return empty list if table does not yet exist
      if (message.includes('does not exist')) {
        return apiResponse.success(res, []);
      }
      log.error('customers GET failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to fetch customers');
    }
  }

  // ─── POST: Create customer ──────────────────────────────────────────────────
  if (req.method === 'POST') {
    try {
      const {
        name,
        email,
        phone,
        vat_number,
        registration_number,
        billing_address,
        shipping_address,
        contact_person,
        payment_terms,
        credit_limit,
        is_active,
        notes,
      } = req.body as {
        name?: string;
        email?: string;
        phone?: string;
        vat_number?: string;
        registration_number?: string;
        billing_address?: string;
        shipping_address?: string;
        contact_person?: string;
        payment_terms?: number;
        credit_limit?: number | null;
        is_active?: boolean;
        notes?: string;
      };

      if (!name?.trim()) {
        return apiResponse.badRequest(res, 'Customer name is required');
      }

      const rows = (await sql`
        INSERT INTO customers (
          name, email, phone, vat_number, registration_number,
          billing_address, shipping_address, contact_person,
          payment_terms, credit_limit, is_active, notes
        ) VALUES (
          ${name.trim()},
          ${email?.trim() || null},
          ${phone?.trim() || null},
          ${vat_number?.trim() || null},
          ${registration_number?.trim() || null},
          ${billing_address?.trim() || null},
          ${shipping_address?.trim() || null},
          ${contact_person?.trim() || null},
          ${payment_terms ?? 30},
          ${credit_limit ?? null},
          ${is_active ?? true},
          ${notes?.trim() || null}
        )
        RETURNING
          id, name, email, phone, vat_number, registration_number,
          billing_address, shipping_address, contact_person,
          payment_terms, credit_limit, is_active, notes,
          created_at
      `) as Row[];

      log.info('Customer created', { id: rows[0]?.id, name: rows[0]?.name, module: 'accounting' });
      return apiResponse.success(res, rows[0]);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('customers POST failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to create customer');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST']);
});

/**
 * Journal Entries API
 * GET  /api/accounting/journal-entries - List entries (with filters)
 * POST /api/accounting/journal-entries - Create draft entry with lines
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getJournalEntries,
  createJournalEntry,
} from '@/modules/accounting/services/journalEntryService';
import type { GLEntryStatus, GLEntrySource } from '@/modules/accounting/types/gl.types';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { status, source, fiscal_period_id, limit, offset } = req.query;
      const result = await getJournalEntries({
        status: status as GLEntryStatus | undefined,
        source: source as GLEntrySource | undefined,
        fiscalPeriodId: fiscal_period_id as string | undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get journal entries', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get journal entries');
    }
  }

  if (req.method === 'POST') {
    try {
      const { entryDate, description, source, sourceDocumentId, fiscalPeriodId, lines } = req.body;

      if (!entryDate || !lines || !Array.isArray(lines) || lines.length === 0) {
        return apiResponse.badRequest(res, 'entryDate and lines (non-empty array) are required');
      }

      // User identity comes from JWT (req.user), never from client request body
      const userId = req.user.id;

      const entry = await createJournalEntry({
        entryDate,
        description,
        source,
        sourceDocumentId,
        fiscalPeriodId,
        lines,
      }, userId);

      return apiResponse.success(res, entry);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create journal entry';
      log.error('Failed to create journal entry', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

