/**
 * Customer Statement PDF Generator
 * Produces a portrait A4 PDF statement for a single customer
 * using jsPDF + jspdf-autotable (same pattern as reconReportPdf.ts)
 *
 * jsPDF and jspdf-autotable are loaded dynamically to keep them out of the
 * initial page bundle — they are only needed when the user clicks "Download PDF".
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export interface StatementTransaction {
  date: string;
  type: 'invoice' | 'payment' | 'credit_note';
  reference: string;
  description: string;
  debit: number;
  credit: number;
  balance: number;
}

export interface StatementData {
  clientName: string;
  clientEmail?: string;
  clientPhone?: string;
  asAtDate: string;
  totalInvoiced: number;
  totalPaid: number;
  totalCredits: number;
  balanceOutstanding: number;
  transactions: StatementTransaction[];
}

// ─── Private helpers (no jsPDF type reference — avoids static import) ─────────

const fmtZAR = (amount: number): string =>
  new Intl.NumberFormat('en-ZA', {
    style: 'currency',
    currency: 'ZAR',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);

const fmtDate = (d: string): string => {
  if (!d) return '—';
  const parts = d.split('T')[0]?.split('-') ?? [];
  if (parts.length === 3) return `${parts[2]}/${parts[1]}/${parts[0]}`;
  return d;
};

// ─── Main Export Function ─────────────────────────────────────────────────────

/**
 * Generate a portrait A4 PDF customer statement and return it as a Blob.
 * Call `URL.createObjectURL(blob)` to download in the browser.
 *
 * This function is async because it dynamically imports jsPDF and
 * jspdf-autotable to avoid including them in the initial page bundle.
 */
// 🟢 WORKING: generateStatementPdf
export async function generateStatementPdf(data: StatementData): Promise<Blob> {
  const [{ jsPDF }, { default: autoTable }] = await Promise.all([
    import('jspdf'),
    import('jspdf-autotable'),
  ]);

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const PAGE_W = doc.internal.pageSize.getWidth();

  // ── Header ──────────────────────────────────────────────────────────────────
  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(30, 30, 30);
  doc.text('STATEMENT', 14, 18);

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(80, 80, 80);
  doc.text('Velocity Fibre (Pty) Ltd', 14, 26);
  doc.text('VAT No: 4070313040', 14, 31);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(30, 30, 30);
  doc.text(data.clientName, PAGE_W - 14, 18, { align: 'right' });

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.setTextColor(80, 80, 80);
  if (data.clientEmail) doc.text(data.clientEmail, PAGE_W - 14, 24, { align: 'right' });
  if (data.clientPhone) doc.text(data.clientPhone, PAGE_W - 14, 29, { align: 'right' });

  doc.text(`Statement Date: ${fmtDate(data.asAtDate)}`, PAGE_W - 14, 35, { align: 'right' });
  doc.text(`Generated: ${new Date().toLocaleString('en-ZA')}`, PAGE_W - 14, 40, { align: 'right' });

  doc.setDrawColor(200, 200, 200);
  doc.line(14, 44, PAGE_W - 14, 44);

  // ── Summary box ─────────────────────────────────────────────────────────────
  const BOX_H = 28;
  const COL = (PAGE_W - 28) / 4;
  let cursor = 48;

  doc.setFillColor(245, 247, 250);
  doc.setDrawColor(210, 215, 225);
  doc.roundedRect(14, cursor, PAGE_W - 28, BOX_H, 2, 2, 'FD');

  const labelY = cursor + 9;
  const valueY = cursor + 20;
  const summaryCols = [
    { label: 'Total Invoiced', value: data.totalInvoiced },
    { label: 'Total Paid', value: data.totalPaid },
    { label: 'Credits Applied', value: data.totalCredits },
    { label: 'Balance Due', value: data.balanceOutstanding },
  ];

  summaryCols.forEach((col, i) => {
    const x = 14 + COL * i + COL / 2;
    doc.setFontSize(7.5);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(100, 100, 100);
    doc.text(col.label, x, labelY, { align: 'center' });

    doc.setFontSize(10);
    doc.setFont('helvetica', 'bold');
    const isBalance = i === 3;
    if (isBalance && col.value > 0) {
      doc.setTextColor(180, 50, 50);
    } else if (isBalance) {
      doc.setTextColor(22, 163, 74);
    } else {
      doc.setTextColor(30, 30, 30);
    }
    doc.text(fmtZAR(col.value), x, valueY, { align: 'center' });
  });

  cursor += BOX_H + 6;

  // ── Transactions table ───────────────────────────────────────────────────────
  const typeLabels: Record<string, string> = {
    invoice: 'Invoice',
    payment: 'Payment',
    credit_note: 'Credit Note',
  };

  const rows = data.transactions.map(t => [
    fmtDate(t.date),
    typeLabels[t.type] || t.type,
    t.reference,
    t.description?.substring(0, 40) || '—',
    t.debit > 0 ? fmtZAR(t.debit) : '',
    t.credit > 0 ? fmtZAR(t.credit) : '',
    fmtZAR(t.balance),
  ]);

  autoTable(doc, {
    startY: cursor,
    head: [['Date', 'Type', 'Reference', 'Description', 'Debit', 'Credit', 'Balance']],
    body: rows,
    styles: { fontSize: 7.5, cellPadding: 2 },
    headStyles: { fillColor: [41, 82, 140], textColor: 255, fontStyle: 'bold', fontSize: 8 },
    alternateRowStyles: { fillColor: [248, 250, 252] },
    columnStyles: {
      4: { halign: 'right', font: 'courier' },
      5: { halign: 'right', font: 'courier' },
      6: { halign: 'right', font: 'courier', fontStyle: 'bold' },
    },
    tableWidth: PAGE_W - 28,
    margin: { left: 14, right: 14 },
  });

  // ── Page footers ─────────────────────────────────────────────────────────────
  const PAGE_H = doc.internal.pageSize.getHeight();
  const totalPages = (doc as typeof doc & { internal: { getNumberOfPages: () => number } })
    .internal.getNumberOfPages();

  for (let i = 1; i <= totalPages; i++) {
    doc.setPage(i);
    doc.setFontSize(7);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(150, 150, 150);
    doc.line(14, PAGE_H - 10, PAGE_W - 14, PAGE_H - 10);
    doc.text(`Page ${i} of ${totalPages}`, PAGE_W - 14, PAGE_H - 5, { align: 'right' });
    doc.text('FibreFlow Customer Statement — Confidential', 14, PAGE_H - 5);
  }

  return doc.output('blob');
}

/**
 * Neon Database Client
 * Standalone serverless PostgreSQL connection for the Accounting app
 * Uses @neondatabase/serverless with retry logic and proper config
 */

import { neon, neonConfig } from '@neondatabase/serverless';
import { log } from '@/lib/logger';

// Enable connection caching for better performance
neonConfig.fetchConnectionCache = true;

// Configure transport for Node.js environments (not in browser/edge)
declare const EdgeRuntime: unknown;

const isNodeEnv =
  typeof window === 'undefined' &&
  typeof EdgeRuntime === 'undefined';

if (isNodeEnv) {
  const useHttpTransport = process.env.NEON_USE_HTTP === 'true';

  if (!useHttpTransport) {
    // WebSocket transport - faster for Node.js
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const ws = require('ws');
      neonConfig.webSocketConstructor = ws;
      log.info('Using WebSocket transport', {}, 'Neon');
    } catch {
      log.info('WebSocket not available, falling back to HTTP', {}, 'Neon');
    }
  } else {
    log.info('Using HTTP transport (NEON_USE_HTTP=true)', {}, 'Neon');
  }

  // Configure WebSocket proxy (Neon v2 protocol)
  neonConfig.wsProxy = (host: string, port: number | string) => `${host}:${port}/v2`;

  // Use secure WebSocket connections
  neonConfig.useSecureWebSocket = true;

  // Pipeline authentication for faster connections
  neonConfig.pipelineConnect = 'password';

  // Enable automatic retries on transient errors
  neonConfig.fetchFunction = async (...args: Parameters<typeof fetch>) => {
    const maxRetries = 3;
    let lastError: unknown;

    for (let i = 0; i < maxRetries; i++) {
      try {
        const response = await fetch(...args);
        if (!response.ok && response.status >= 500 && i < maxRetries - 1) {
          // Retry on server errors with exponential backoff
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
        return response;
      } catch (error) {
        lastError = error;
        if (i < maxRetries - 1) {
          // Exponential backoff: 100ms, 200ms, 400ms
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
      }
    }
    throw lastError || new Error('Request failed after retries');
  };
}

/**
 * Get the DATABASE_URL, throwing a clear error if not set
 */
function getDatabaseUrl(): string {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error('DATABASE_URL is not set. Please configure it in your environment.');
  }
  return url;
}

/**
 * Serverless SQL client for use in API routes and edge functions.
 * Use tagged template literals: sql`SELECT * FROM table WHERE id = ${id}`
 */
export const sql = neon(getDatabaseUrl());

/**
 * Execute multiple queries in a transaction using the serverless client.
 *
 * @param callback - Async function receiving the sql client
 * @returns The result of the callback
 *
 * @example
 * const result = await transaction(async (tx) => {
 *   await tx`INSERT INTO accounts ...`;
 *   await tx`UPDATE balances ...`;
 *   return { success: true };
 * });
 */
export async function transaction<T>(
  callback: (client: typeof sql) => Promise<T>
): Promise<T> {
  try {
    await sql`BEGIN`;
    const result = await callback(sql);
    await sql`COMMIT`;
    return result;
  } catch (error) {
    await sql`ROLLBACK`;
    log.error(
      'Transaction rolled back',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  }
}

export default sql;

