 * Each pays 1% of remuneration, capped at R177.12/month.
 */
export function calculateUIF(monthlyRemuneration: number): {
  employee: number;
  employer: number;
} {
  const cappedRemuneration = Math.min(monthlyRemuneration, UIF_MONTHLY_CEILING);
