          {/* Tab Navigation */}
          <div className="px-6 border-t border-[var(--ff-border-light)]">
            <nav className="flex gap-0 -mb-px overflow-x-auto" aria-label="Accounting tabs">
              {TABS.map(tab => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.id;
                return (
                  <button
