/**
 * Item Pricing API
 * GET — list active stock items with prices
 * PUT — bulk update selling prices
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const rows = await sql`
        SELECT id, item_code, name, category, uom, list_price, standard_cost, qty_available
        FROM stock_items WHERE is_active = true ORDER BY name
      `;
      return apiResponse.success(res, rows);
    } catch (err) {
      log.error('Failed to fetch item pricing', { error: err });
      return apiResponse.badRequest(res, 'Failed to fetch item pricing');
    }
  }

  if (req.method === 'PUT') {
    try {
      const { updates } = req.body as {
        updates?: { itemId: string; sellingPrice: number }[];
      };

      if (!updates || !Array.isArray(updates) || updates.length === 0) {
        return apiResponse.badRequest(res, 'updates array is required');
      }

      for (const u of updates) {
        if (!u.itemId || u.sellingPrice == null || Number(u.sellingPrice) < 0) {
          return apiResponse.badRequest(res, 'Each entry needs itemId and non-negative sellingPrice');
        }
      }

      for (const u of updates) {
        await sql`UPDATE stock_items SET list_price = ${Number(u.sellingPrice)} WHERE id = ${u.itemId}`;
      }

      log.info('Selling prices updated', { count: updates.length });
      return apiResponse.success(res, { updated: updates.length });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update prices';
      log.error('Item pricing update failed', { error: err });
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT']);
}

export default withAuth(handler);

/**
 * Fiscal Period Actions API
 * POST /api/accounting/fiscal-periods-action - Close, lock, or reopen a period
 * Body: { id, action: 'close' | 'lock' | 'reopen', userId? }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  closePeriod,
  lockPeriod,
  reopenPeriod,
} from '@/modules/accounting/services/fiscalPeriodService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { id, action, userId } = req.body;
    if (!id || !action) {
      return apiResponse.badRequest(res, 'id and action are required');
    }

    let result;
    switch (action) {
      case 'close':
        if (!userId) return apiResponse.badRequest(res, 'userId required for close action');
        result = await closePeriod(id, userId);
        break;
      case 'lock':
        result = await lockPeriod(id);
        break;
      case 'reopen':
        result = await reopenPeriod(id);
        break;
      default:
        return apiResponse.badRequest(res, `Invalid action: ${action}. Use close, lock, or reopen`);
    }

    return apiResponse.success(res, result);
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to perform period action';
    log.error('Failed to perform period action', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * Payroll Service
 * Handles employee management, payroll runs, payslip generation,
 * and GL journal posting for SA payroll.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  calculateMonthlyPAYE,
  calculateUIF,
  calculateSDL,
  calculateAgeFromIdNumber,
} from './taxTables';
import type {
  Employee,
  EmployeeWithPay,
  PayStructure,
  PayrollRun,
  PayrollRunWithPayslips,
  Payslip,
  CreateEmployeeInput,
  UpdateEmployeeInput,
  CustomDeduction,
} from './types';
import {
  createJournalEntry,
  postJournalEntry,
} from '@/modules/accounting/services/journalEntryService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

// ── Employee Functions ──────────────────────────────────────────────────────

export async function listEmployees(
  search?: string,
  statusFilter?: string
): Promise<EmployeeWithPay[]> {
  try {
    const searchTerm = search ? `%${search}%` : null;
    let rows: Row[];

    if (searchTerm && statusFilter) {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        WHERE e.status = ${statusFilter}
          AND (
            e.first_name ILIKE ${searchTerm}
            OR e.last_name ILIKE ${searchTerm}
            OR e.employee_number ILIKE ${searchTerm}
            OR e.department ILIKE ${searchTerm}
          )
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    } else if (searchTerm) {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        WHERE
          e.first_name ILIKE ${searchTerm}
          OR e.last_name ILIKE ${searchTerm}
          OR e.employee_number ILIKE ${searchTerm}
          OR e.department ILIKE ${searchTerm}
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    } else if (statusFilter) {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        WHERE e.status = ${statusFilter}
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    }

    return rows.map(mapEmployeeWithPay);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    if (message.includes('does not exist')) return [];
    log.error('listEmployees failed', { error: message }, 'payroll');
    throw err;
  }
}

export async function getEmployee(id: string): Promise<EmployeeWithPay | null> {
  try {
    const rows = (await sql`
      SELECT e.*,
        ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
        ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
        ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
        ps.custom_deductions, ps.effective_from, ps.effective_to
      FROM employees e
      LEFT JOIN LATERAL (
        SELECT * FROM pay_structures p
        WHERE p.employee_id = e.id
          AND p.effective_from <= CURRENT_DATE
          AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
        ORDER BY p.effective_from DESC
        LIMIT 1
      ) ps ON TRUE
      WHERE e.id = ${id}
    `) as Row[];

    if (rows.length === 0) return null;
    return mapEmployeeWithPay(rows[0]!);
  } catch (err) {
    log.error('getEmployee failed', { id, error: err }, 'payroll');
    throw err;
  }
}

