/**
 * Item Quantities Report API
 * GET: Current on-hand quantities per item with min stock alerts
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const format = req.query.format as string;
    const lowStockOnly = req.query.low_stock === 'true';

    const rows = await sql`
      SELECT id, item_code, name, category, uom, qty_available,
        COALESCE(min_stock_level, 0) AS min_stock_level
      FROM stock_items
      WHERE is_active = true
      ORDER BY name
    `;

    let data = rows.map(r => ({
      id: r.id,
      itemCode: r.item_code || '',
      name: r.name,
      category: r.category || 'uncategorized',
      uom: r.uom || '',
      qtyOnHand: Number(r.qty_available || 0),
      minLevel: Number(r.min_stock_level || 0),
      lowStock: Number(r.min_stock_level || 0) > 0 && Number(r.qty_available || 0) <= Number(r.min_stock_level || 0),
    }));

    if (lowStockOnly) {
      data = data.filter(r => r.lowStock);
    }

    if (format === 'csv') {
      const header = 'Item Code,Name,Category,UOM,Qty On Hand,Min Level,Low Stock';
      const csvRows = data.map(r =>
        `"${r.itemCode}","${r.name}","${r.category}","${r.uom}",${r.qtyOnHand},${r.minLevel},${r.lowStock ? 'Yes' : 'No'}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', 'attachment; filename="item-quantities.csv"');
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Item quantities report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate report');
  }
});

/**
 * Payroll Service
 * Handles employee management, payroll runs, payslip generation,
 * and GL journal posting for SA payroll.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  calculateMonthlyPAYE,
  calculateUIF,
  calculateSDL,
  calculateAgeFromIdNumber,
} from './taxTables';
import type {
  Employee,
  EmployeeWithPay,
  PayStructure,
  PayrollRun,
  PayrollRunWithPayslips,
  Payslip,
  CreateEmployeeInput,
  UpdateEmployeeInput,
  CustomDeduction,
} from './types';
import {
  createJournalEntry,
  postJournalEntry,
} from '@/modules/accounting/services/journalEntryService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

// ── Employee Functions ──────────────────────────────────────────────────────

export async function listEmployees(
  search?: string,
  statusFilter?: string
): Promise<EmployeeWithPay[]> {
  try {
    const searchTerm = search ? `%${search}%` : null;
    let rows: Row[];

    if (searchTerm && statusFilter) {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        WHERE e.status = ${statusFilter}
          AND (
            e.first_name ILIKE ${searchTerm}
            OR e.last_name ILIKE ${searchTerm}
            OR e.employee_number ILIKE ${searchTerm}
            OR e.department ILIKE ${searchTerm}
          )
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    } else if (searchTerm) {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        WHERE
          e.first_name ILIKE ${searchTerm}
          OR e.last_name ILIKE ${searchTerm}
          OR e.employee_number ILIKE ${searchTerm}
          OR e.department ILIKE ${searchTerm}
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    } else if (statusFilter) {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        WHERE e.status = ${statusFilter}
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    }

    return rows.map(mapEmployeeWithPay);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    if (message.includes('does not exist')) return [];
    log.error('listEmployees failed', { error: message }, 'payroll');
    throw err;
  }
}

