tool_response.originalFile:
/**
 * SARS eFiling Integration Service
 * Generates VAT201 and EMP201 form data from accounting records.
 * Manages tax periods and compliance calendar for South African tax obligations.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const SA_VAT_RATE = 0.15;

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface VAT201Data {
  periodStart: string;
  periodEnd: string;
  field1_standardRatedSupplies: number;
  field2_zeroRatedSupplies: number;
  field3_exemptSupplies: number;
  field4_totalImports: number;
  field5_outputVAT: number;
  field6_capitalGoods: number;
  field7_otherGoods: number;
  field8_services: number;
  field9_imports: number;
  field10_totalInputVAT: number;
  field11_vatPayableOrRefundable: number;
  outputInvoices: VAT201Invoice[];
  inputInvoices: VAT201Invoice[];
}

export interface VAT201Invoice {
  id: string;
  invoiceNumber: string;
  counterpartyName: string;
  invoiceDate: string;
  totalExclVat: number;
  vatAmount: number;
  vatType: string;
}

export interface EMP201Data {
  periodStart: string;
  periodEnd: string;
  totalPAYE: number;
  totalUIF_employee: number;
  totalUIF_employer: number;
  totalUIF: number;
  totalSDL: number;
  employeeCount: number;
  totalTaxableRemuneration: number;
  totalDeductions: number;
  payrollRuns: EMP201PayrollRun[];
}

export interface EMP201PayrollRun {
  id: string;
  runDate: string;
  employeeCount: number;
  grossPay: number;
  paye: number;
  uif: number;
  sdl: number;
}

export interface TaxPeriod {
  type: 'VAT' | 'PAYE';
  periodStart: string;
  periodEnd: string;
  dueDate: string;
  label: string;
}

export interface ComplianceEvent {
  id?: string;
  eventType: string;
  dueDate: string;
  description: string;
  status: 'pending' | 'completed' | 'overdue';
  submissionId?: string;
}

export interface SARSSubmission {
  id: string;
  formType: string;
  periodStart: string;
  periodEnd: string;
  status: string;
  formData: Record<string, unknown>;
  submissionReference: string | null;
  submittedAt: string | null;
  submittedBy: string | null;
  notes: string | null;
  createdAt: string;
  updatedAt: string;
}

// ---------------------------------------------------------------------------
// VAT201 Generation
// ---------------------------------------------------------------------------

/**
 * Generate a VAT201 return from customer and supplier invoices for the period.
 * Output VAT comes from customer_invoices; input VAT from supplier_invoices.
 * GL account codes 2120 (Output VAT) and 1140 (Input VAT) are cross-referenced.
 */
export async function generateVAT201(
  periodStart: string,
  periodEnd: string
): Promise<VAT201Data> {
  log.info('Generating VAT201', { periodStart, periodEnd }, 'sarsService');

  // -- Output VAT: customer invoices in period --
  let customerInvoices: Row[] = [];
  try {
    customerInvoices = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.invoice_date,
        ci.subtotal,
        ci.vat_amount,
        ci.total,
        ci.vat_type,
        c.name AS customer_name
      FROM customer_invoices ci
      LEFT JOIN customers c ON c.id = ci.customer_id
      WHERE ci.invoice_date >= ${periodStart}
        AND ci.invoice_date <= ${periodEnd}
        AND ci.status != 'cancelled'
      ORDER BY ci.invoice_date
    `) as Row[];
  } catch (err) {
    log.warn('Could not query customer_invoices for VAT201', { error: err }, 'sarsService');
  }

  // -- Input VAT: supplier invoices in period --
  let supplierInvoices: Row[] = [];
  try {
    supplierInvoices = (await sql`
      SELECT
        si.id,
        si.invoice_number,
        si.invoice_date,
        si.subtotal,
        si.vat_amount,
        si.total,
        si.vat_type,
        s.name AS supplier_name
      FROM supplier_invoices si
      LEFT JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.invoice_date >= ${periodStart}
        AND si.invoice_date <= ${periodEnd}
        AND si.status != 'cancelled'
      ORDER BY si.invoice_date
    `) as Row[];
  } catch (err) {
    log.warn('Could not query supplier_invoices for VAT201', { error: err }, 'sarsService');
  }

  // Categorise customer invoices (output side)
  let field1_standardRated = 0;
  let field2_zeroRated = 0;
  let field3_exempt = 0;

  const outputInvoices: VAT201Invoice[] = customerInvoices.map((inv: Row) => {
    const subtotal = Number(inv.subtotal) || 0;
    const vatAmt = Number(inv.vat_amount) || 0;
    const vatType = String(inv.vat_type || 'standard').toLowerCase();

    if (vatType === 'zero_rated' || vatType === 'zero-rated' || vatType === 'zero') {
      field2_zeroRated += subtotal;
    } else if (vatType === 'exempt') {
      field3_exempt += subtotal;
    } else {
      field1_standardRated += subtotal;
    }

    return {
      id: String(inv.id),
      invoiceNumber: String(inv.invoice_number || ''),
      counterpartyName: String(inv.customer_name || 'Unknown'),
      invoiceDate: String(inv.invoice_date || ''),
      totalExclVat: subtotal,
      vatAmount: vatAmt,
      vatType,
    };
  });

  // Field 5: Output VAT = standard-rated supplies x 15%
  const field5_outputVAT = roundCents(field1_standardRated * SA_VAT_RATE);

  // Categorise supplier invoices (input side)
  let field6_capitalGoods = 0;
  let field7_otherGoods = 0;
  let field8_services = 0;
  let field9_imports = 0;

  const inputInvoices: VAT201Invoice[] = supplierInvoices.map((inv: Row) => {
    const vatAmt = Number(inv.vat_amount) || 0;
    const subtotal = Number(inv.subtotal) || 0;
    const vatType = String(inv.vat_type || 'standard').toLowerCase();

    // Categorise into input VAT fields based on vat_type metadata
    if (vatType === 'capital' || vatType === 'capital_goods') {
      field6_capitalGoods += vatAmt;
    } else if (vatType === 'import' || vatType === 'imports') {
      field9_imports += vatAmt;
    } else if (vatType === 'services' || vatType === 'service') {
      field8_services += vatAmt;
    } else {
      // Default: other goods and services
      field7_otherGoods += vatAmt;
    }

    return {
      id: String(inv.id),
      invoiceNumber: String(inv.invoice_number || ''),
      counterpartyName: String(inv.supplier_name || 'Unknown'),
      invoiceDate: String(inv.invoice_date || ''),
      totalExclVat: subtotal,
      vatAmount: vatAmt,
      vatType,
    };
  });

  const field10_totalInputVAT = roundCents(
    field6_capitalGoods + field7_otherGoods + field8_services + field9_imports
  );

  const field11_vatPayable = roundCents(field5_outputVAT - field10_totalInputVAT);

  return {
    periodStart,
    periodEnd,
    field1_standardRatedSupplies: roundCents(field1_standardRated),
    field2_zeroRatedSupplies: roundCents(field2_zeroRated),
    field3_exemptSupplies: roundCents(field3_exempt),
    field4_totalImports: roundCents(field9_imports > 0 ? field9_imports / SA_VAT_RATE : 0),
    field5_outputVAT,
    field6_capitalGoods: roundCents(field6_capitalGoods),
    field7_otherGoods: roundCents(field7_otherGoods),
    field8_services: roundCents(field8_services),
    field9_imports: roundCents(field9_imports),
    field10_totalInputVAT,
    field11_vatPayableOrRefundable: field11_vatPayable,
    outputInvoices,
    inputInvoices,
  };
}

// ---------------------------------------------------------------------------
// EMP201 Generation
// ---------------------------------------------------------------------------

/**
 * Generate EMP201 (monthly PAYE/UIF/SDL) data from payroll tables.
 * Handles missing payroll tables gracefully by returning zero-filled data.
 */
export async function generateEMP201(
  periodStart: string,
  periodEnd: string
): Promise<EMP201Data> {
  log.info('Generating EMP201', { periodStart, periodEnd }, 'sarsService');

  const emptyResult: EMP201Data = {
    periodStart,
    periodEnd,
    totalPAYE: 0,
    totalUIF_employee: 0,
    totalUIF_employer: 0,
    totalUIF: 0,
    totalSDL: 0,
    employeeCount: 0,
    totalTaxableRemuneration: 0,
    totalDeductions: 0,
    payrollRuns: [],
  };

  // Check if payroll tables exist
  let hasPayrollTables = false;
  try {
    const tables = (await sql`
      SELECT table_name FROM information_schema.tables
      WHERE table_schema = 'public'
        AND table_name IN ('payroll_runs', 'payslips')
    `) as Row[];
    hasPayrollTables = tables.length >= 2;
  } catch (err) {
    log.warn('Could not check payroll tables', { error: err }, 'sarsService');
  }

  if (!hasPayrollTables) {
    log.info('Payroll tables not found, returning empty EMP201', {}, 'sarsService');
    return emptyResult;
  }

  try {
    // Get payroll runs in the period
    const runs = (await sql`
      SELECT
        pr.id,
        pr.run_date,
        COUNT(DISTINCT ps.employee_id) AS employee_count,
        COALESCE(SUM(ps.gross_pay), 0) AS gross_pay,
        COALESCE(SUM(ps.paye), 0) AS paye,
        COALESCE(SUM(ps.uif_employee), 0) AS uif_employee,
        COALESCE(SUM(ps.uif_employer), 0) AS uif_employer,
        COALESCE(SUM(ps.sdl), 0) AS sdl
      FROM payroll_runs pr
      LEFT JOIN payslips ps ON ps.payroll_run_id = pr.id
      WHERE pr.run_date >= ${periodStart}
        AND pr.run_date <= ${periodEnd}
        AND pr.status != 'cancelled'
      GROUP BY pr.id, pr.run_date
      ORDER BY pr.run_date
    `) as Row[];

    if (runs.length === 0) {
      return emptyResult;
    }

    let totalPAYE = 0;
    let totalUIFEmployee = 0;
    let totalUIFEmployer = 0;
    let totalSDL = 0;
    let totalGross = 0;
    const employeeIds = new Set<string>();

    const payrollRuns: EMP201PayrollRun[] = runs.map((r: Row) => {
      const paye = Number(r.paye) || 0;
      const uifEmp = Number(r.uif_employee) || 0;
      const uifEr = Number(r.uif_employer) || 0;
      const sdl = Number(r.sdl) || 0;
      const gross = Number(r.gross_pay) || 0;

      totalPAYE += paye;
      totalUIFEmployee += uifEmp;
      totalUIFEmployer += uifEr;
      totalSDL += sdl;
      totalGross += gross;

      return {
        id: String(r.id),
        runDate: String(r.run_date),
        employeeCount: Number(r.employee_count) || 0,
        grossPay: roundCents(gross),
        paye: roundCents(paye),
        uif: roundCents(uifEmp + uifEr),
        sdl: roundCents(sdl),
      };
    });

    // Get distinct employee count for the period
    try {
      const empCount = (await sql`
        SELECT COUNT(DISTINCT ps.employee_id) AS cnt
        FROM payslips ps
        JOIN payroll_runs pr ON pr.id = ps.payroll_run_id
        WHERE pr.run_date >= ${periodStart}
          AND pr.run_date <= ${periodEnd}
          AND pr.status != 'cancelled'
      `) as Row[];
      if (empCount[0]?.cnt) {
        // Use the distinct count from DB
      }
    } catch {
      // Fallback: sum from runs
    }

    const totalUIF = roundCents(totalUIFEmployee + totalUIFEmployer);
    const totalDeductions = roundCents(totalPAYE + totalUIF + totalSDL);

    return {
      periodStart,
      periodEnd,
      totalPAYE: roundCents(totalPAYE),
      totalUIF_employee: roundCents(totalUIFEmployee),
      totalUIF_employer: roundCents(totalUIFEmployer),
      totalUIF,
      totalSDL: roundCents(totalSDL),
      employeeCount: payrollRuns.reduce((max, r) => Math.max(max, r.employeeCount), 0),
      totalTaxableRemuneration: roundCents(totalGross),
      totalDeductions,
      payrollRuns,
    };
  } catch (err) {
    log.warn('Error generating EMP201 from payroll data', { error: err }, 'sarsService');
    return emptyResult;
  }
}

// ---------------------------------------------------------------------------
// Submissions CRUD
// ---------------------------------------------------------------------------

/** Save a SARS submission as draft */
export async function saveDraftSubmission(
  formType: string,
  periodStart: string,
  periodEnd: string,
  formData: Record<string, unknown>,
  userId: string
): Promise<SARSSubmission> {
  log.info('Saving draft submission', { formType, periodStart, periodEnd }, 'sarsService');

  const rows = (await sql`
    INSERT INTO sars_submissions (form_type, period_start, period_end, status, form_data, submitted_by)
    VALUES (${formType}, ${periodStart}, ${periodEnd}, 'draft', ${JSON.stringify(formData)}::jsonb, ${userId})
    RETURNING *
  `) as Row[];

  return mapSubmissionRow(rows[0]);
}

/** List all submissions, most recent first */
export async function listSubmissions(
  formType?: string
): Promise<SARSSubmission[]> {
  let rows: Row[];
  if (formType) {
    rows = (await sql`
      SELECT * FROM sars_submissions
      WHERE form_type = ${formType}
      ORDER BY created_at DESC
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM sars_submissions
      ORDER BY created_at DESC
    `) as Row[];
  }

  return rows.map(mapSubmissionRow);
}

/** Get a single submission by ID */
export async function getSubmission(id: string): Promise<SARSSubmission | null> {
  const rows = (await sql`
    SELECT * FROM sars_submissions WHERE id = ${id}
  `) as Row[];

  if (rows.length === 0) return null;
  return mapSubmissionRow(rows[0]);
}

/** Mark a submission as submitted with a SARS reference */
export async function markSubmitted(
  id: string,
  reference: string
): Promise<SARSSubmission> {
  log.info('Marking submission as submitted', { id, reference }, 'sarsService');

  const rows = (await sql`
    UPDATE sars_submissions
    SET status = 'submitted',
        submission_reference = ${reference},
        submitted_at = NOW(),
        updated_at = NOW()
    WHERE id = ${id}
    RETURNING *
  `) as Row[];

  if (rows.length === 0) {
    throw new Error(`Submission ${id} not found`);
  }

  return mapSubmissionRow(rows[0]);
}

// ---------------------------------------------------------------------------
// Tax Periods
// ---------------------------------------------------------------------------

/**
 * Return SA tax periods for the current tax year.
 * VAT: Bi-monthly periods (Cat A) — Jan/Feb, Mar/Apr, May/Jun, Jul/Aug, Sep/Oct, Nov/Dec
 * PAYE: Monthly periods
 */
export function getTaxPeriods(year?: number): TaxPeriod[] {
  const y = year || new Date().getFullYear();
  const periods: TaxPeriod[] = [];

  // VAT bi-monthly periods (Category A — most common)
  const vatPeriods: Array<{ start: string; end: string; label: string }> = [
    { start: `${y}-01-01`, end: `${y}-02-28`, label: `Jan–Feb ${y}` },
    { start: `${y}-03-01`, end: `${y}-04-30`, label: `Mar–Apr ${y}` },
    { start: `${y}-05-01`, end: `${y}-06-30`, label: `May–Jun ${y}` },
    { start: `${y}-07-01`, end: `${y}-08-31`, label: `Jul–Aug ${y}` },
    { start: `${y}-09-01`, end: `${y}-10-31`, label: `Sep–Oct ${y}` },
    { start: `${y}-11-01`, end: `${y}-12-31`, label: `Nov–Dec ${y}` },
  ];

  // Handle leap year for Feb
  if (isLeapYear(y)) {
    vatPeriods[0].end = `${y}-02-29`;
  }

  for (const vp of vatPeriods) {
    const endDate = new Date(vp.end);
    // VAT201 due by 25th of month following end of period
    const dueMonth = endDate.getMonth() + 2; // +1 for next month, +1 because getMonth is 0-indexed
    const dueYear = dueMonth > 12 ? y + 1 : y;
    const dueM = dueMonth > 12 ? dueMonth - 12 : dueMonth;
    const dueDate = `${dueYear}-${pad(dueM)}-25`;

    periods.push({
      type: 'VAT',
      periodStart: vp.start,
      periodEnd: vp.end,
      dueDate,
      label: `VAT201 — ${vp.label}`,
    });
  }

  // PAYE monthly periods
  const monthNames = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];

  for (let m = 1; m <= 12; m++) {
    const lastDay = new Date(y, m, 0).getDate();
    const periodStart = `${y}-${pad(m)}-01`;
    const periodEnd = `${y}-${pad(m)}-${pad(lastDay)}`;

    // EMP201 due by 7th of following month
    const dueMonth = m + 1;
    const dueYear = dueMonth > 12 ? y + 1 : y;
    const dueM = dueMonth > 12 ? 1 : dueMonth;
    const dueDate = `${dueYear}-${pad(dueM)}-07`;

    periods.push({
      type: 'PAYE',
      periodStart,
      periodEnd,
      dueDate,
      label: `EMP201 — ${monthNames[m - 1]} ${y}`,
    });
  }

  return periods;
}

// ---------------------------------------------------------------------------
// Compliance Calendar
// ---------------------------------------------------------------------------

/**
 * Build a compliance calendar with upcoming SARS deadlines.
 * Includes VAT201, EMP201, EMP501, IRP5/IT3(a), and Provisional Tax (IRP6).
 */
export function getComplianceCalendar(year?: number): ComplianceEvent[] {
  const y = year || new Date().getFullYear();
  const events: ComplianceEvent[] = [];

  // VAT201 deadlines — due 25th of month following bi-monthly period end
  const vatEndMonths = [2, 4, 6, 8, 10, 12];
  const vatLabels = ['Jan–Feb', 'Mar–Apr', 'May–Jun', 'Jul–Aug', 'Sep–Oct', 'Nov–Dec'];

  for (let i = 0; i < vatEndMonths.length; i++) {
    const endMonth = vatEndMonths[i];
    const dueMonth = endMonth + 1;
    const dueYear = dueMonth > 12 ? y + 1 : y;
    const dueM = dueMonth > 12 ? 1 : dueMonth;

    events.push({
      eventType: 'VAT201_DUE',
      dueDate: `${dueYear}-${pad(dueM)}-25`,
      description: `VAT201 return for ${vatLabels[i]} ${y}`,
      status: getDeadlineStatus(`${dueYear}-${pad(dueM)}-25`),
    });
  }

  // EMP201 deadlines — due 7th of each following month
  const monthNames = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];

  for (let m = 1; m <= 12; m++) {
    const dueMonth = m + 1;
    const dueYear = dueMonth > 12 ? y + 1 : y;
    const dueM = dueMonth > 12 ? 1 : dueMonth;

    events.push({
      eventType: 'EMP201_DUE',
      dueDate: `${dueYear}-${pad(dueM)}-07`,
      description: `EMP201 (PAYE/UIF/SDL) for ${monthNames[m - 1]} ${y}`,
      status: getDeadlineStatus(`${dueYear}-${pad(dueM)}-07`),
    });
  }

  // EMP501 — Interim (end of May) and Annual (end of October)
  events.push({
    eventType: 'EMP501_DUE',
    dueDate: `${y}-05-31`,
    description: `EMP501 Interim Reconciliation — Tax Year ending Feb ${y}`,
    status: getDeadlineStatus(`${y}-05-31`),
  });
  events.push({
    eventType: 'EMP501_DUE',
    dueDate: `${y}-10-31`,
    description: `EMP501 Annual Reconciliation — Tax Year ending Feb ${y}`,
    status: getDeadlineStatus(`${y}-10-31`),
  });

  // Provisional Tax (IRP6) — End of August and end of February
  events.push({
    eventType: 'PROVISIONAL_TAX',
    dueDate: `${y}-08-31`,
    description: `IRP6 First Provisional Tax Payment — Tax Year ending Feb ${y + 1}`,
    status: getDeadlineStatus(`${y}-08-31`),
  });
  events.push({
    eventType: 'PROVISIONAL_TAX',
    dueDate: `${y + 1}-02-28`,
    description: `IRP6 Second Provisional Tax Payment — Tax Year ending Feb ${y + 1}`,
    status: getDeadlineStatus(`${y + 1}-02-28`),
  });

  // Sort by due date
  events.sort((a, b) => a.dueDate.localeCompare(b.dueDate));

  return events;
}

/**
 * Load compliance events from the database (if any exist), merged with
 * the static calendar. DB events can override status (e.g. marked completed).
 */
export async function getComplianceCalendarWithDB(year?: number): Promise<ComplianceEvent[]> {
  const staticEvents = getComplianceCalendar(year);

  try {
    const y = year || new Date().getFullYear();
    const dbEvents = (await sql`
      SELECT
        ce.id, ce.event_type, ce.due_date, ce.description,
        ce.status, ce.submission_id
      FROM sars_compliance_events ce
      WHERE EXTRACT(YEAR FROM ce.due_date) = ${y}
         OR EXTRACT(YEAR FROM ce.due_date) = ${y + 1}
      ORDER BY ce.due_date
    `) as Row[];

    // Merge: if a DB event matches a static event by type + due_date, use DB status
    const dbMap = new Map<string, Row>();
    for (const dbe of dbEvents) {
      const key = `${dbe.event_type}_${String(dbe.due_date).slice(0, 10)}`;
      dbMap.set(key, dbe);
    }

    return staticEvents.map((se) => {
      const key = `${se.eventType}_${se.dueDate}`;
      const dbMatch = dbMap.get(key);
      if (dbMatch) {
        return {
          ...se,
          id: String(dbMatch.id),
          status: dbMatch.status as ComplianceEvent['status'],
          submissionId: dbMatch.submission_id ? String(dbMatch.submission_id) : undefined,
        };
      }
      return se;
    });
  } catch (err) {
    log.warn('Could not load compliance events from DB, using static calendar', { error: err }, 'sarsService');
    return staticEvents;
  }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function roundCents(n: number): number {
  return Math.round(n * 100) / 100;
}

function pad(n: number): string {
  return String(n).padStart(2, '0');
}

function isLeapYear(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function getDeadlineStatus(dueDate: string): ComplianceEvent['status'] {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const due = new Date(dueDate);
  due.setHours(0, 0, 0, 0);

  if (due < today) return 'overdue';
  return 'pending';
}

function mapSubmissionRow(row: Row): SARSSubmission {
  return {
    id: String(row.id),
    formType: String(row.form_type),
    periodStart: String(row.period_start).slice(0, 10),
    periodEnd: String(row.period_end).slice(0, 10),
    status: String(row.status),
    formData: row.form_data || {},
    submissionReference: row.submission_reference ? String(row.submission_reference) : null,
    submittedAt: row.submitted_at ? String(row.submitted_at) : null,
    submittedBy: row.submitted_by ? String(row.submitted_by) : null,
    notes: row.notes ? String(row.notes) : null,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Income Statement (P&L) Report Page
 * PRD-060 Phase 5: Revenue, Cost of Sales, Operating Expenses
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, BarChart3, Loader2, AlertCircle, ChevronDown, ChevronRight, Download } from 'lucide-react';
import type { IncomeStatementReport, IncomeStatementLineItem } from '@/modules/accounting/types/gl.types';
import { AccountDrillDown } from '@/components/accounting/AccountDrillDown';

interface CostCentre { id: string; code: string; name: string }

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(amount);
}

function getDefaultDates(): { periodStart: string; periodEnd: string } {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  return {
    periodStart: start.toISOString().split('T')[0] ?? '',
    periodEnd: now.toISOString().split('T')[0] ?? '',
  };
}

export default function IncomeStatementPage() {
  const defaults = getDefaultDates();
  const [periodStart, setPeriodStart] = useState(defaults.periodStart);
  const [periodEnd, setPeriodEnd] = useState(defaults.periodEnd);
  const [report, setReport] = useState<IncomeStatementReport | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [expandedAccount, setExpandedAccount] = useState<string | null>(null);
  const [costCentres, setCostCentres] = useState<CostCentre[]>([]);
  const [costCentreId, setCostCentreId] = useState('');
  const [showComparative, setShowComparative] = useState(false);

  useEffect(() => {
    fetch('/api/accounting/cost-centres?active_only=true', { credentials: 'include' })
      .then(r => r.json())
      .then(json => setCostCentres(json.data?.items || json.data || []))
      .catch(() => {});
  }, []);

  function handleExport() {
    const params = new URLSearchParams({ period_start: periodStart, period_end: periodEnd });
    if (costCentreId) params.set('cost_centre_id', costCentreId);
    window.open(`/api/accounting/income-statement-export?${params}`, '_blank');
  }

  function toggleAccount(code: string) {
    setExpandedAccount(prev => (prev === code ? null : code));
  }

  const loadReport = useCallback(async () => {
    if (!periodStart || !periodEnd) return;
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ period_start: periodStart, period_end: periodEnd });
      if (costCentreId) params.set('cost_centre_id', costCentreId);
      if (showComparative) {
        const start = new Date(periodStart);
        const end = new Date(periodEnd);
        const durationMs = end.getTime() - start.getTime();
        const priorEnd = new Date(start.getTime() - 1);
        const priorStart = new Date(priorEnd.getTime() - durationMs);
        params.set('compare_start', priorStart.toISOString().split('T')[0] ?? '');
        params.set('compare_end', priorEnd.toISOString().split('T')[0] ?? '');
      }
      const res = await fetch(`/api/accounting/reports-income-statement?${params}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load');
      setReport(json.data || json);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load income statement');
    } finally {
      setIsLoading(false);
    }
  }, [periodStart, periodEnd, costCentreId, showComparative]);

  useEffect(() => { loadReport(); }, [loadReport]);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <Link href="/accounting?tab=reports" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2">
              <ArrowLeft className="h-4 w-4" /> Back to Reports
            </Link>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-teal-500/10">
                  <BarChart3 className="h-6 w-6 text-teal-500" />
                </div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Income Statement</h1>
              </div>
              <button onClick={handleExport} disabled={!report}
                className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 text-sm font-medium disabled:opacity-50">
                <Download className="h-4 w-4" /> Export CSV
              </button>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-4xl space-y-6">
          {/* Date Range + Filters */}
          <div className="flex flex-wrap items-end gap-4">
            <div>
              <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">From</label>
              <input type="date" value={periodStart} onChange={e => setPeriodStart(e.target.value)} className="ff-input text-sm" />
            </div>
            <div>
              <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">To</label>
              <input type="date" value={periodEnd} onChange={e => setPeriodEnd(e.target.value)} className="ff-input text-sm" />
            </div>
            <div>
              <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Cost Centre</label>
              <select value={costCentreId} onChange={e => setCostCentreId(e.target.value)}
                className="ff-input text-sm min-w-[160px]">
                <option value="">All Cost Centres</option>
                {costCentres.map(cc => (
                  <option key={cc.id} value={cc.id}>{cc.code} — {cc.name}</option>
                ))}
              </select>
            </div>
            <label className="flex items-center gap-2 text-sm text-[var(--ff-text-secondary)] cursor-pointer select-none pb-1">
              <input type="checkbox" checked={showComparative} onChange={e => setShowComparative(e.target.checked)}
                className="rounded border-[var(--ff-border-light)]" />
              Compare prior period
            </label>
          </div>

          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
              <AlertCircle className="h-4 w-4" /> {error}
            </div>
          )}

          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-6 w-6 animate-spin text-teal-500" />
            </div>
          ) : report ? (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
              <div className="px-6 py-4 border-b border-[var(--ff-border-light)]">
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                  Profit &amp; Loss — {periodStart} to {periodEnd}
                </h2>
              </div>

              <div className="divide-y divide-[var(--ff-border-light)]">
                {/* Revenue */}
                <Section label="Revenue" items={report.revenue} total={report.totalRevenue} color="teal"
                  periodStart={periodStart} periodEnd={periodEnd} expandedAccount={expandedAccount}
                  onToggleAccount={toggleAccount} showComparative={showComparative} />

                {/* Cost of Sales */}
                {report.costOfSales.length > 0 && (
                  <Section label="Cost of Sales" items={report.costOfSales} total={report.totalCostOfSales} color="orange"
                    periodStart={periodStart} periodEnd={periodEnd} expandedAccount={expandedAccount}
                    onToggleAccount={toggleAccount} showComparative={showComparative} />
                )}

                {/* Gross Profit */}
                <div className="px-6 py-3 flex justify-between bg-teal-500/5">
                  <span className="font-semibold text-[var(--ff-text-primary)]">Gross Profit</span>
                  <span className={`font-bold font-mono ${report.grossProfit >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                    {formatCurrency(report.grossProfit)}
                    {showComparative && report.priorGrossProfit !== undefined && (
                      <span className="text-xs text-[var(--ff-text-tertiary)] ml-2">
                        (prior: {formatCurrency(report.priorGrossProfit)})
                      </span>
                    )}
                  </span>
                </div>

                {/* Operating Expenses */}
                <Section label="Operating Expenses" items={report.operatingExpenses} total={report.totalOperatingExpenses} color="red"
                  periodStart={periodStart} periodEnd={periodEnd} expandedAccount={expandedAccount}
                  onToggleAccount={toggleAccount} showComparative={showComparative} />

                {/* Net Profit */}
                <div className="px-6 py-4 flex justify-between bg-[var(--ff-bg-primary)]">
                  <span className="text-lg font-bold text-[var(--ff-text-primary)]">Net Profit / (Loss)</span>
                  <span className={`text-xl font-bold font-mono ${report.netProfit >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                    {formatCurrency(report.netProfit)}
                    {showComparative && report.priorNetProfit !== undefined && (
                      <span className="text-xs text-[var(--ff-text-tertiary)] ml-2">
                        (prior: {formatCurrency(report.priorNetProfit)})
                      </span>
                    )}
                  </span>
                </div>
              </div>
            </div>
          ) : null}
        </div>
      </div>
    </AppLayout>
  );
}

function Section({ label, items, total, color, periodStart, periodEnd, expandedAccount, onToggleAccount, showComparative }: {
  label: string;
  items: IncomeStatementLineItem[];
  total: number;
  color: string;
  periodStart: string;
  periodEnd: string;
  expandedAccount: string | null;
  onToggleAccount: (code: string) => void;
  showComparative: boolean;
}) {
  return (
    <div>
      <div className={`px-6 py-2 bg-${color}-500/5 flex items-center`}>
        <span className={`text-sm font-semibold text-${color}-400`}>{label}</span>
        {showComparative ? (
          <span className="flex items-center gap-4 text-xs text-[var(--ff-text-tertiary)] ml-auto">
            <span className="w-28 text-right">Prior</span>
            <span className="w-28 text-right">Current</span>
            <span className="w-20 text-right">Variance</span>
          </span>
        ) : (
          <span className="text-xs text-[var(--ff-text-tertiary)] ml-auto">Click account to expand</span>
        )}
      </div>
      {items.map(item => {
        const isExpanded = expandedAccount === item.accountCode;
        return (
          <div key={item.accountCode}>
            <button
              type="button"
              onClick={() => onToggleAccount(item.accountCode)}
              className="w-full px-6 py-2 flex justify-between items-center text-sm hover:bg-[var(--ff-bg-tertiary)] cursor-pointer text-left"
            >
              <span className="flex items-center gap-1 text-[var(--ff-text-secondary)] flex-1">
                {isExpanded
                  ? <ChevronDown className="h-3 w-3 shrink-0 text-[var(--ff-text-tertiary)]" />
                  : <ChevronRight className="h-3 w-3 shrink-0 text-[var(--ff-text-tertiary)]" />}
                <span className="font-mono text-xs mr-1">{item.accountCode}</span>
                {item.accountName}
              </span>
              {showComparative && item.priorAmount !== undefined ? (
                <span className="flex items-center gap-4">
                  <span className="font-mono text-[var(--ff-text-tertiary)] w-28 text-right text-xs">{formatCurrency(item.priorAmount)}</span>
                  <span className="font-mono text-[var(--ff-text-primary)] w-28 text-right">{formatCurrency(item.amount)}</span>
                  <span className={`font-mono w-20 text-right text-xs ${(item.variance ?? 0) >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                    {(item.variance ?? 0) >= 0 ? '+' : ''}{formatCurrency(item.variance ?? 0)}
                  </span>
                </span>
              ) : (
                <span className="font-mono text-[var(--ff-text-primary)]">{formatCurrency(item.amount)}</span>
              )}
            </button>
            {isExpanded && (
              <div className="px-6 pb-3">
                <AccountDrillDown accountCode={item.accountCode} periodStart={periodStart} periodEnd={periodEnd} />
              </div>
            )}
          </div>
        );
      })}
      {items.length === 0 && (
        <div className="px-6 py-2 text-sm text-[var(--ff-text-tertiary)]">No entries</div>
      )}
      <div className="px-6 py-2 flex justify-between border-t border-[var(--ff-border-light)]">
        <span className="text-sm font-medium text-[var(--ff-text-primary)]">Total {label}</span>
        <span className="font-mono font-medium text-[var(--ff-text-primary)]">{formatCurrency(total)}</span>
      </div>
    </div>
  );
}

