export async function transaction<T = unknown>(
  queries: Array<(client: typeof sql) => Promise<T>>
): Promise<T[]> {
  try {
    const txSql = neon(getDatabaseUrl(), { isolationLevel: 'ReadCommitted' });
    // @ts-expect-error — neon transaction API accepts query-producing callbacks
    const results = await txSql.transaction(
      queries.map(q => (txClient: typeof sql) => q(txClient))
    );
    return results as T[];
  } catch (error) {
    log.error(
      'Transaction failed',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  }
}

