/**
 * SARS Submission History Page
 * Table of all past submissions with type, period, status, reference, and details.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  FileText, Loader2, ChevronLeft,
  CheckCircle2, Clock, XCircle, AlertTriangle,
  Eye, X,
} from 'lucide-react';

interface Submission {
  id: string;
  formType: string;
  periodStart: string;
  periodEnd: string;
  status: string;
  formData: Record<string, unknown>;
  submissionReference: string | null;
  submittedAt: string | null;
  submittedBy: string | null;
  notes: string | null;
  createdAt: string;
  updatedAt: string;
}

import { formatDate } from '@/utils/formatters';

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const formatDateTime = (d: string) => {
  if (!d) return '—';
  return new Date(d).toLocaleString('en-ZA', {
    day: '2-digit', month: 'short', year: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
};

const statusBadge = (status: string) => {
  const configs: Record<string, { icon: typeof CheckCircle2; className: string }> = {
    submitted: { icon: CheckCircle2, className: 'bg-emerald-500/10 text-emerald-400' },
    accepted: { icon: CheckCircle2, className: 'bg-emerald-500/10 text-emerald-400' },
    draft: { icon: Clock, className: 'bg-amber-500/10 text-amber-400' },
    generated: { icon: Clock, className: 'bg-blue-500/10 text-blue-400' },
    rejected: { icon: XCircle, className: 'bg-red-500/10 text-red-400' },
  };
  const cfg = configs[status] || { icon: AlertTriangle, className: 'bg-gray-500/10 text-gray-400' };
  const Icon = cfg.icon;

  return (
    <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${cfg.className}`}>
      <Icon className="h-3 w-3" /> {status}
    </span>
  );
};

export default function SubmissionsPage() {
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState<string>('all');
  const [detail, setDetail] = useState<Submission | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const typeParam = filter !== 'all' ? `?type=${filter}` : '';
      const res = await fetch(
        `/api/accounting/sars/sars-submissions${typeParam}`,
        { credentials: 'include' }
      );
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || json.message || 'Failed');
      setSubmissions(json.data?.items || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load submissions');
    } finally {
      setLoading(false);
    }
  }, [filter]);

  useEffect(() => { load(); }, [load]);

  const viewDetail = async (id: string) => {
    try {
      const res = await fetch('/api/accounting/sars/sars-submissions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ id, action: 'get' }),
      });
      const json = await res.json();
      if (json.data) {
        setDetail(json.data);
      }
    } catch {
      // Fallback to local data
      const sub = submissions.find((s) => s.id === id);
      if (sub) setDetail(sub);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center gap-3">
            <Link
              href="/accounting/sars"
              className="p-2 rounded-lg hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-secondary)]"
            >
              <ChevronLeft className="h-5 w-5" />
            </Link>
            <div className="p-2 rounded-lg bg-purple-500/10">
              <FileText className="h-6 w-6 text-purple-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Submission History</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                All SARS eFiling submissions and their statuses
              </p>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {error && <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>}

          {/* Filter Tabs */}
          <div className="flex gap-1 bg-[var(--ff-bg-secondary)] rounded-lg p-1 w-fit border border-[var(--ff-border-light)]">
            {['all', 'VAT201', 'EMP201', 'EMP501', 'IRP5'].map((f) => (
              <button
                key={f}
                onClick={() => setFilter(f)}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
                  filter === f
                    ? 'bg-teal-600 text-white'
                    : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
                }`}
              >
                {f === 'all' ? 'All' : f}
              </button>
            ))}
          </div>

          {/* Submissions Table */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-[var(--ff-border-light)] text-left text-[var(--ff-text-secondary)]">
                  <th className="px-4 py-3">Type</th>
                  <th className="px-4 py-3">Period</th>
                  <th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3">SARS Reference</th>
                  <th className="px-4 py-3">Submitted</th>
                  <th className="px-4 py-3">Created</th>
                  <th className="px-4 py-3">Actions</th>
                </tr>
              </thead>
              <tbody>
                {loading && (
                  <tr>
                    <td colSpan={7} className="px-4 py-8 text-center text-[var(--ff-text-tertiary)]">
                      <Loader2 className="h-5 w-5 animate-spin inline mr-2" />
                      Loading submissions...
                    </td>
                  </tr>
                )}
                {!loading && submissions.length === 0 && (
                  <tr>
                    <td colSpan={7} className="px-4 py-8 text-center text-[var(--ff-text-tertiary)]">
                      No submissions found. Generate a VAT201 or EMP201 to create your first submission.
                    </td>
                  </tr>
                )}
                {submissions.map((sub) => (
                  <tr
                    key={sub.id}
                    className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)]/50"
                  >
                    <td className="px-4 py-3">
                      <span className="inline-flex px-2 py-0.5 rounded text-xs font-medium bg-teal-500/10 text-teal-400">
                        {sub.formType}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-[var(--ff-text-primary)]">
                      {formatDate(sub.periodStart)} — {formatDate(sub.periodEnd)}
                    </td>
                    <td className="px-4 py-3">{statusBadge(sub.status)}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)] font-mono text-xs">
                      {sub.submissionReference || '—'}
                    </td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                      {sub.submittedAt ? formatDateTime(sub.submittedAt) : '—'}
                    </td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                      {formatDate(sub.createdAt)}
                    </td>
                    <td className="px-4 py-3">
                      <button
                        onClick={() => viewDetail(sub.id)}
                        className="inline-flex items-center gap-1 px-2 py-1 rounded text-xs text-teal-500 hover:text-teal-400 hover:bg-teal-500/10"
                      >
                        <Eye className="h-3 w-3" /> View
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Detail Modal */}
        {detail && (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] w-full max-w-2xl mx-4 max-h-[80vh] overflow-auto">
              <div className="px-6 py-4 border-b border-[var(--ff-border-light)] flex items-center justify-between sticky top-0 bg-[var(--ff-bg-secondary)]">
                <h3 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                  {detail.formType} — {formatDate(detail.periodStart)} to {formatDate(detail.periodEnd)}
                </h3>
                <button
                  onClick={() => setDetail(null)}
                  className="p-1 rounded hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-secondary)]"
                >
                  <X className="h-5 w-5" />
                </button>
              </div>

              <div className="p-6 space-y-4">
                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <p className="text-[var(--ff-text-tertiary)] text-xs mb-1">Status</p>
                    {statusBadge(detail.status)}
                  </div>
                  <div>
                    <p className="text-[var(--ff-text-tertiary)] text-xs mb-1">SARS Reference</p>
                    <p className="text-[var(--ff-text-primary)] font-mono">
                      {detail.submissionReference || '—'}
                    </p>
                  </div>
                  <div>
                    <p className="text-[var(--ff-text-tertiary)] text-xs mb-1">Submitted</p>
                    <p className="text-[var(--ff-text-secondary)]">
                      {detail.submittedAt ? formatDateTime(detail.submittedAt) : '—'}
                    </p>
                  </div>
                  <div>
                    <p className="text-[var(--ff-text-tertiary)] text-xs mb-1">Created</p>
                    <p className="text-[var(--ff-text-secondary)]">
                      {formatDateTime(detail.createdAt)}
                    </p>
                  </div>
                </div>

                {detail.notes && (
                  <div>
                    <p className="text-[var(--ff-text-tertiary)] text-xs mb-1">Notes</p>
                    <p className="text-[var(--ff-text-secondary)] text-sm">{detail.notes}</p>
                  </div>
                )}

                {/* Form Data */}
                <div>
                  <p className="text-[var(--ff-text-tertiary)] text-xs mb-2">Form Data</p>
                  <div className="bg-[var(--ff-bg-primary)] rounded-lg p-4 border border-[var(--ff-border-light)]">
                    {detail.formType === 'VAT201' && <VAT201Detail data={detail.formData} />}
                    {detail.formType === 'EMP201' && <EMP201Detail data={detail.formData} />}
                    {detail.formType !== 'VAT201' && detail.formType !== 'EMP201' && (
                      <pre className="text-xs text-[var(--ff-text-secondary)] overflow-auto">
                        {JSON.stringify(detail.formData, null, 2)}
                      </pre>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </AppLayout>
  );
}

function VAT201Detail({ data }: { data: Record<string, unknown> }) {
  const fields = [
    { key: 'field1_standardRatedSupplies', label: '1. Standard-rated supplies' },
    { key: 'field2_zeroRatedSupplies', label: '2. Zero-rated supplies' },
    { key: 'field3_exemptSupplies', label: '3. Exempt supplies' },
    { key: 'field4_totalImports', label: '4. Total imports' },
    { key: 'field5_outputVAT', label: '5. Output VAT' },
    { key: 'field6_capitalGoods', label: '6. Input VAT — Capital goods' },
    { key: 'field7_otherGoods', label: '7. Input VAT — Other goods' },
    { key: 'field8_services', label: '8. Input VAT — Services' },
    { key: 'field9_imports', label: '9. Input VAT — Imports' },
    { key: 'field10_totalInputVAT', label: '10. Total input VAT' },
    { key: 'field11_vatPayableOrRefundable', label: '11. VAT payable/(refundable)' },
  ];

  return (
    <div className="space-y-1 text-sm">
      {fields.map((f) => (
        <div key={f.key} className="flex justify-between py-1">
          <span className="text-[var(--ff-text-secondary)]">{f.label}</span>
          <span className="text-[var(--ff-text-primary)] font-medium">
            {fmt(Number(data[f.key]) || 0)}
          </span>
        </div>
      ))}
    </div>
  );
}

function EMP201Detail({ data }: { data: Record<string, unknown> }) {
  const fields = [
    { key: 'employeeCount', label: 'Employees', isCurrency: false },
    { key: 'totalTaxableRemuneration', label: 'Total remuneration', isCurrency: true },
    { key: 'totalPAYE', label: 'PAYE', isCurrency: true },
    { key: 'totalUIF', label: 'Total UIF', isCurrency: true },
    { key: 'totalSDL', label: 'SDL', isCurrency: true },
    { key: 'totalDeductions', label: 'Total payable', isCurrency: true },
  ];

  return (
    <div className="space-y-1 text-sm">
      {fields.map((f) => (
        <div key={f.key} className="flex justify-between py-1">
          <span className="text-[var(--ff-text-secondary)]">{f.label}</span>
          <span className="text-[var(--ff-text-primary)] font-medium">
            {f.isCurrency ? fmt(Number(data[f.key]) || 0) : String(data[f.key] || 0)}
          </span>
        </div>
      ))}
    </div>
  );
}

/**
 * OCR Service — Pattern-based document data extraction
 * Extracts vendor, date, amounts, VAT, reference numbers from PDF text.
 * Optimised for South African invoices and receipts.
 */

import { log } from '@/lib/logger';
import type { ExtractedDocument, ExtractedLineItem } from '@/modules/accounting/types/documentCapture.types';

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Extract structured data from a PDF buffer.
 * Uses pdf-parse to get the text layer, then runs pattern extraction.
 */
export async function extractFromPdf(buffer: Buffer): Promise<ExtractedDocument> {
  let rawText = '';
  const warnings: string[] = [];

  try {
    // Dynamic import — pdf-parse is a CJS module
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const pdfParse = require('pdf-parse');
    const data = await pdfParse(buffer);
    rawText = data.text || '';
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('PDF text extraction failed', { error: msg }, 'ocr-service');
    warnings.push(`PDF parsing failed: ${msg}`);
  }

  if (!rawText.trim()) {
    warnings.push('No text found in PDF — the document may be image-based. Manual entry recommended.');
    return emptyResult(rawText, warnings);
  }

  return extractFromText(rawText, warnings);
}

/**
 * Extract structured data from raw text (e.g. pasted or OCR output).
 */
export async function extractFromText(
  rawText: string,
  existingWarnings: string[] = [],
): Promise<ExtractedDocument> {
  const warnings = [...existingWarnings];
  const lines = rawText.split(/\n/).map(l => l.trim()).filter(Boolean);

  if (lines.length === 0) {
    warnings.push('Empty text provided');
    return emptyResult(rawText, warnings);
  }

  const documentType = detectDocumentType(rawText);
  const vendorName = extractVendorName(lines);
  const vendorVatNumber = extractVatRegistration(rawText);
  const date = extractDate(rawText);
  const referenceNumber = extractReferenceNumber(rawText);
  const amounts = extractAmounts(rawText);
  const lineItems = extractLineItems(lines);

  // Calculate confidence based on how many fields we found
  const confidence = computeConfidence({
    vendorName,
    date,
    referenceNumber,
    totalAmount: amounts.totalAmount,
    vatAmount: amounts.vatAmount,
    lineItems,
  });

  if (confidence < 0.3) {
    warnings.push('Low extraction confidence — please review all fields carefully.');
  }

  return {
    documentType,
    vendorName,
    vendorVatNumber,
    date,
    referenceNumber,
    subtotal: amounts.subtotal,
    vatAmount: amounts.vatAmount,
    totalAmount: amounts.totalAmount,
    lineItems,
    rawText,
    confidence,
    warnings,
  };
}

// ---------------------------------------------------------------------------
// Document type detection
// ---------------------------------------------------------------------------

function detectDocumentType(text: string): ExtractedDocument['documentType'] {
  const upper = text.toUpperCase();

  if (/CREDIT\s*NOTE/i.test(upper)) return 'credit_note';
  if (/TAX\s*INVOICE/i.test(upper)) return 'invoice';
  if (/INVOICE/i.test(upper)) return 'invoice';
  if (/STATEMENT/i.test(upper)) return 'statement';
  if (/RECEIPT/i.test(upper) || /PROOF\s*OF\s*PAYMENT/i.test(upper)) return 'receipt';

  return 'unknown';
}

// ---------------------------------------------------------------------------
// Vendor name extraction
// ---------------------------------------------------------------------------

function extractVendorName(lines: string[]): string | null {
  // Strategy: First few non-empty lines often contain the vendor/company name.
  // Skip lines that look like document type headers or dates.
  const skipPatterns = [
    /^(TAX\s*)?INVOICE$/i,
    /^CREDIT\s*NOTE$/i,
    /^STATEMENT$/i,
    /^RECEIPT$/i,
    /^(page|date|ref|invoice|tel|fax|email|vat|tax|reg)/i,
    /^\d{1,2}[/-]\d{1,2}[/-]\d{2,4}$/,
    /^P\.?O\.?\s*BOX/i,
    /^\d+\s+(street|road|avenue|drive|lane|crescent)/i,
  ];

  for (let i = 0; i < Math.min(lines.length, 8); i++) {
    const line = lines[i];
    if (!line || line.length < 3 || line.length > 80) continue;
    if (skipPatterns.some(p => p.test(line))) continue;
    // Skip lines that are purely numeric
    if (/^\d+$/.test(line)) continue;
    // Skip lines that look like addresses with postal codes
    if (/\b\d{4}\b.*\b(South Africa|SA|RSA)\b/i.test(line)) continue;

    return line;
  }

  // Fallback: look for "From:" or "Supplier:" patterns
  const fromMatch = lines.join('\n').match(/(?:From|Supplier|Vendor|Company)\s*[:-]\s*(.+)/i);
  if (fromMatch && fromMatch[1]) return fromMatch[1].trim();

  return null;
}

// ---------------------------------------------------------------------------
// VAT registration number
// ---------------------------------------------------------------------------

function extractVatRegistration(text: string): string | null {
  // SA VAT numbers are typically 10 digits
  const patterns = [
    /VAT\s*(?:Reg(?:istration)?\.?\s*)?(?:No\.?|Number|#)\s*[:-]?\s*(\d{10})/i,
    /VAT\s*[:-]?\s*(\d{10})/i,
    /(?:Reg(?:istration)?\.?\s*)?(?:No\.?|Number)\s*[:-]?\s*(\d{10})/i,
  ];

  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match && match[1]) return match[1];
  }

  return null;
}

// ---------------------------------------------------------------------------
// Date extraction
// ---------------------------------------------------------------------------

function extractDate(text: string): string | null {
  const months: Record<string, string> = {
    jan: '01', january: '01',
    feb: '02', february: '02',
    mar: '03', march: '03',
    apr: '04', april: '04',
    may: '05',
    jun: '06', june: '06',
    jul: '07', july: '07',
    aug: '08', august: '08',
    sep: '09', september: '09',
    oct: '10', october: '10',
    nov: '11', november: '11',
    dec: '12', december: '12',
  };

  // Priority: look for labelled dates first
  const labelledPatterns = [
    /(?:Invoice|Document|Tax Invoice|Statement)\s*Date\s*[:-]?\s*(.+)/i,
    /Date\s*[:-]\s*(.+)/i,
    /Dated?\s*[:-]\s*(.+)/i,
  ];

  for (const pattern of labelledPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      const parsed = parseDateString(match[1].trim(), months);
      if (parsed) return parsed;
    }
  }

  // Fallback: find date patterns anywhere in text
  // DD/MM/YYYY or DD-MM-YYYY
  const slashDate = text.match(/\b(\d{1,2})[/-](\d{1,2})[/-](\d{4})\b/);
  if (slashDate) {
    const [, d, m, y] = slashDate;
    const day = d!.padStart(2, '0');
    const month = m!.padStart(2, '0');
    if (parseInt(month) >= 1 && parseInt(month) <= 12) {
      return `${y}-${month}-${day}`;
    }
  }

  // YYYY-MM-DD (ISO)
  const isoDate = text.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
  if (isoDate) {
    return `${isoDate[1]}-${isoDate[2]}-${isoDate[3]}`;
  }

  // DD Month YYYY
  const longDate = text.match(/\b(\d{1,2})\s+(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{4})\b/i);
  if (longDate) {
    const day = longDate[1]!.padStart(2, '0');
    const monthNum = months[longDate[2]!.toLowerCase()];
    if (monthNum) return `${longDate[3]}-${monthNum}-${day}`;
  }

  return null;
}

function parseDateString(str: string, months: Record<string, string>): string | null {
  // DD/MM/YYYY or DD-MM-YYYY
  const slashMatch = str.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})/);
  if (slashMatch) {
    const day = slashMatch[1]!.padStart(2, '0');
    const month = slashMatch[2]!.padStart(2, '0');
    if (parseInt(month) >= 1 && parseInt(month) <= 12) {
      return `${slashMatch[3]}-${month}-${day}`;
    }
  }

  // YYYY-MM-DD
  const isoMatch = str.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;

  // DD Month YYYY or DD Mon YYYY
  const longMatch = str.match(/^(\d{1,2})\s+(\w+)\s+(\d{4})/);
  if (longMatch) {
    const monthKey = longMatch[2]!.toLowerCase();
    const monthNum = months[monthKey];
    if (monthNum) {
      const day = longMatch[1]!.padStart(2, '0');
      return `${longMatch[3]}-${monthNum}-${day}`;
    }
  }

  return null;
}

// ---------------------------------------------------------------------------
// Reference / invoice number extraction
// ---------------------------------------------------------------------------

function extractReferenceNumber(text: string): string | null {
  const patterns = [
    /Invoice\s*(?:No\.?|Number|#)\s*[:-]?\s*([A-Za-z0-9/\-]+)/i,
    /Ref(?:erence)?\s*(?:No\.?|Number|#)\s*[:-]?\s*([A-Za-z0-9/\-]+)/i,
    /(?:INV|REF|CN|CR)\s*[-#]?\s*(\d{3,})/i,
    /Document\s*(?:No\.?|Number)\s*[:-]?\s*([A-Za-z0-9/\-]+)/i,
    /Order\s*(?:No\.?|Number)\s*[:-]?\s*([A-Za-z0-9/\-]+)/i,
    /Receipt\s*(?:No\.?|Number|#)\s*[:-]?\s*([A-Za-z0-9/\-]+)/i,
  ];

  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match && match[1] && match[1].length >= 3) {
      return match[1].trim();
    }
  }

  return null;
}

// ---------------------------------------------------------------------------
// Amount extraction (Total, VAT, Subtotal)
// ---------------------------------------------------------------------------

interface ExtractedAmounts {
  subtotal: number | null;
  vatAmount: number | null;
  totalAmount: number | null;
}

function extractAmounts(text: string): ExtractedAmounts {
  const result: ExtractedAmounts = {
    subtotal: null,
    vatAmount: null,
    totalAmount: null,
  };

  // Currency pattern: optional R or ZAR, then number with optional decimals and thousand separators
  const amountPattern = /R?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/;

  // Total amount — look for "Total", "Amount Due", "Balance Due", "Grand Total"
  const totalPatterns = [
    /(?:Grand\s*)?Total\s*(?:Due|Amount|Payable)?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /(?:Amount|Balance)\s*(?:Due|Owing|Payable)\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Total\s*(?:Incl(?:uding)?\.?\s*(?:VAT|Tax))?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
  ];

  for (const pattern of totalPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      result.totalAmount = parseAmount(match[1]);
      break;
    }
  }

  // VAT amount
  const vatPatterns = [
    /VAT\s*(?:@\s*\d+%?)?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Tax\s*(?:Amount)?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /VAT\s*\(\s*15\s*%\s*\)\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
  ];

  for (const pattern of vatPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      result.vatAmount = parseAmount(match[1]);
      break;
    }
  }

  // Subtotal
  const subtotalPatterns = [
    /Sub\s*[-\s]?Total\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Total\s*(?:Excl(?:uding)?\.?\s*(?:VAT|Tax))\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Nett?\s*(?:Amount|Total)\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
  ];

  for (const pattern of subtotalPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      result.subtotal = parseAmount(match[1]);
      break;
    }
  }

  // If we have total and VAT but no subtotal, calculate it
  if (result.totalAmount !== null && result.vatAmount !== null && result.subtotal === null) {
    result.subtotal = Math.round((result.totalAmount - result.vatAmount) * 100) / 100;
  }

  // If we have subtotal and VAT but no total, calculate it
  if (result.subtotal !== null && result.vatAmount !== null && result.totalAmount === null) {
    result.totalAmount = Math.round((result.subtotal + result.vatAmount) * 100) / 100;
  }

  return result;
}

function parseAmount(str: string): number {
  // Remove spaces and commas used as thousand separators
  const cleaned = str.replace(/[\s,]/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? 0 : Math.round(num * 100) / 100;
}

// ---------------------------------------------------------------------------
// Line item extraction
// ---------------------------------------------------------------------------

function extractLineItems(lines: string[]): ExtractedLineItem[] {
  const items: ExtractedLineItem[] = [];

  // Look for lines that have a description followed by numbers (qty, price, total)
  // Common patterns:
  //   Description    Qty    Unit Price    Amount
  //   Some item      2      100.00        200.00

  const lineItemPattern = /^(.+?)\s+(\d+(?:\.\d+)?)\s+(?:R?\s*)?(\d[\d,]*(?:\.\d{2})?)\s+(?:R?\s*)?(\d[\d,]*(?:\.\d{2})?)$/;
  const simpleLinePattern = /^(.{3,}?)\s{2,}(?:R?\s*)?(\d[\d,]*(?:\.\d{2})?)$/;

  // Find the header line to know where items start
  let itemsStarted = false;
  const headerPattern = /(?:description|item|product|service)\s.*(?:qty|quantity|amount|price|total)/i;

  for (const line of lines) {
    if (headerPattern.test(line)) {
      itemsStarted = true;
      continue;
    }

    if (!itemsStarted && items.length === 0) {
      // Also start if we see line item patterns even without header
      const match = lineItemPattern.exec(line);
      if (match) itemsStarted = true;
    }

    if (!itemsStarted) continue;

    // Stop at totals section
    if (/^(Sub\s*[-\s]?Total|Total|VAT|Tax|Amount\s*Due|Balance\s*Due|Grand\s*Total)/i.test(line)) {
      break;
    }

    // Try full pattern: description, qty, unit price, line total
    const fullMatch = lineItemPattern.exec(line);
    if (fullMatch) {
      items.push({
        description: fullMatch[1]!.trim(),
        quantity: parseFloat(fullMatch[2]!),
        unitPrice: parseAmount(fullMatch[3]!),
        total: parseAmount(fullMatch[4]!),
      });
      continue;
    }

    // Try simple pattern: description + amount
    const simpleMatch = simpleLinePattern.exec(line);
    if (simpleMatch) {
      items.push({
        description: simpleMatch[1]!.trim(),
        quantity: null,
        unitPrice: null,
        total: parseAmount(simpleMatch[2]!),
      });
    }
  }

  return items;
}

// ---------------------------------------------------------------------------
// Confidence scoring
// ---------------------------------------------------------------------------

function computeConfidence(fields: {
  vendorName: string | null;
  date: string | null;
  referenceNumber: string | null;
  totalAmount: number | null;
  vatAmount: number | null;
  lineItems: ExtractedLineItem[];
}): number {
  let score = 0;
  const weights = {
    vendorName: 0.2,
    date: 0.2,
    referenceNumber: 0.15,
    totalAmount: 0.25,
    vatAmount: 0.1,
    lineItems: 0.1,
  };

  if (fields.vendorName) score += weights.vendorName;
  if (fields.date) score += weights.date;
  if (fields.referenceNumber) score += weights.referenceNumber;
  if (fields.totalAmount !== null && fields.totalAmount > 0) score += weights.totalAmount;
  if (fields.vatAmount !== null && fields.vatAmount > 0) score += weights.vatAmount;
  if (fields.lineItems.length > 0) score += weights.lineItems;

  return Math.round(score * 100) / 100;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function emptyResult(rawText: string, warnings: string[]): ExtractedDocument {
  return {
    documentType: 'unknown',
    vendorName: null,
    vendorVatNumber: null,
    date: null,
    referenceNumber: null,
    subtotal: null,
    vatAmount: null,
    totalAmount: null,
    lineItems: [],
    rawText,
    confidence: 0,
    warnings,
  };
}

