/**
 * Document Capture Detail Page
 * View extracted data, edit fields, take actions on a captured document.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  ScanLine, ArrowLeft, Loader2, AlertCircle, FileText,
  CheckCircle2, XCircle, Link2, Save, ChevronDown, ChevronUp,
} from 'lucide-react';
import { toast } from 'react-hot-toast';
import type { CapturedDocument, ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';
import { formatCurrency, formatDate } from '@/utils/formatters';

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    pending: 'bg-amber-500/20 text-amber-400',
    reviewed: 'bg-blue-500/20 text-blue-400',
    matched: 'bg-teal-500/20 text-teal-400',
    rejected: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

function ConfidenceBadge({ confidence }: { confidence: number }) {
  let color = 'text-red-400';
  let label = 'Low';
  if (confidence >= 0.7) { color = 'text-teal-400'; label = 'High'; }
  else if (confidence >= 0.4) { color = 'text-amber-400'; label = 'Medium'; }
  return (
    <span className={`text-xs font-medium ${color}`}>
      {label} ({Math.round(confidence * 100)}%)
    </span>
  );
}

export default function DocumentCaptureDetailPage() {
  const router = useRouter();
  const { docId } = router.query;

  const [doc, setDoc] = useState<CapturedDocument | null>(null);
  const [extracted, setExtracted] = useState<ExtractedDocument | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showRawText, setShowRawText] = useState(false);

  // Editable fields
  const [vendorName, setVendorName] = useState('');
  const [documentDate, setDocumentDate] = useState('');
  const [referenceNumber, setReferenceNumber] = useState('');
  const [totalAmount, setTotalAmount] = useState('');
  const [vatAmount, setVatAmount] = useState('');
  const [documentType, setDocumentType] = useState('');
  const [notes, setNotes] = useState('');

  // Bank TX match
  const [bankTxId, setBankTxId] = useState('');
  const [isMatching, setIsMatching] = useState(false);

  const loadDocument = useCallback(async () => {
    if (!docId) return;
    setIsLoading(true);
    setError('');

    try {
      const res = await fetch(`/api/accounting/document-capture?status=`);
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Failed to load');

      const found = (json.data || []).find((d: CapturedDocument) => d.id === docId);
      if (!found) throw new Error('Document not found');

      setDoc(found);

      const ext = found.extractedData as ExtractedDocument | null;
      setExtracted(ext);

      // Populate form
      setVendorName(found.vendorName || ext?.vendorName || '');
      setDocumentDate(found.documentDate || ext?.date || '');
      setReferenceNumber(found.referenceNumber || ext?.referenceNumber || '');
      setTotalAmount(found.totalAmount !== null ? String(found.totalAmount) : (ext?.totalAmount !== null ? String(ext?.totalAmount) : ''));
      setVatAmount(found.vatAmount !== null ? String(found.vatAmount) : (ext?.vatAmount !== null ? String(ext?.vatAmount) : ''));
      setDocumentType(found.documentType || ext?.documentType || 'unknown');
      setNotes(found.notes || '');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load document');
    } finally {
      setIsLoading(false);
    }
  }, [docId]);

  useEffect(() => { loadDocument(); }, [loadDocument]);

  async function handleConfirm() {
    if (!doc) return;
    setIsSaving(true);
    try {
      const res = await fetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: doc.id,
          action: 'confirm',
          data: {
            vendorName: vendorName || null,
            documentDate: documentDate || null,
            referenceNumber: referenceNumber || null,
            totalAmount: totalAmount ? parseFloat(totalAmount) : null,
            vatAmount: vatAmount ? parseFloat(vatAmount) : null,
            documentType: documentType || null,
            notes: notes || null,
          },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Confirm failed');
      toast.success('Document confirmed');
      loadDocument();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Confirm failed');
    } finally {
      setIsSaving(false);
    }
  }

  async function handleReject() {
    if (!doc) return;
    setIsSaving(true);
    try {
      const res = await fetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: doc.id,
          action: 'reject',
          data: { notes: notes || 'Rejected' },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Reject failed');
      toast.success('Document rejected');
      loadDocument();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Reject failed');
    } finally {
      setIsSaving(false);
    }
  }

  async function handleMatchBankTx() {
    if (!doc || !bankTxId.trim()) {
      toast.error('Enter a bank transaction ID');
      return;
    }
    setIsMatching(true);
    try {
      const res = await fetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: doc.id,
          action: 'match_bank_tx',
          data: { bankTxId: bankTxId.trim() },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Match failed');
      toast.success('Matched to bank transaction');
      setBankTxId('');
      loadDocument();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Match failed');
    } finally {
      setIsMatching(false);
    }
  }

  if (isLoading) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <Loader2 className="h-8 w-8 text-teal-500 animate-spin" />
        </div>
      </AppLayout>
    );
  }

  if (error || !doc) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex flex-col items-center justify-center gap-4">
          <AlertCircle className="h-8 w-8 text-red-400" />
          <p className="text-red-400 text-sm">{error || 'Document not found'}</p>
          <Link href="/accounting/document-capture" className="text-teal-500 hover:text-teal-400 text-sm">
            Back to Document Capture
          </Link>
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link
                href="/accounting/document-capture"
                className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
              >
                <ArrowLeft className="h-5 w-5 text-[var(--ff-text-secondary)]" />
              </Link>
              <div className="p-2 rounded-lg bg-teal-500/10">
                <ScanLine className="h-5 w-5 text-teal-500" />
              </div>
              <div>
                <div className="flex items-center gap-3">
                  <h1 className="text-xl font-bold text-[var(--ff-text-primary)]">
                    {doc.fileName}
                  </h1>
                  <StatusBadge status={doc.status} />
                </div>
                <p className="text-xs text-[var(--ff-text-tertiary)]">
                  Uploaded {formatDate(doc.createdAt)}
                  {doc.fileSize ? ` - ${(doc.fileSize / 1024).toFixed(1)} KB` : ''}
                </p>
              </div>
            </div>
            {extracted && <ConfidenceBadge confidence={extracted.confidence} />}
          </div>
        </div>

        <div className="p-6 space-y-6 max-w-4xl mx-auto">
          {/* Warnings */}
          {extracted && extracted.warnings.length > 0 && (
            <div className="bg-amber-500/5 border border-amber-500/20 rounded-lg p-4">
              {extracted.warnings.map((w, i) => (
                <div key={i} className="flex items-start gap-2 text-sm text-amber-400">
                  <AlertCircle className="h-4 w-4 mt-0.5 shrink-0" />
                  <span>{w}</span>
                </div>
              ))}
            </div>
          )}

          {/* Edit Form */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)]">
            <div className="px-6 py-4 border-b border-[var(--ff-border-light)]">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Document Details</h2>
              <p className="text-xs text-[var(--ff-text-tertiary)]">Review and correct the extracted fields</p>
            </div>
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Document Type</label>
                <select
                  value={documentType}
                  onChange={(e) => setDocumentType(e.target.value)}
                  className="ff-select w-full text-sm"
                  disabled={doc.status === 'rejected'}
                >
                  <option value="invoice">Invoice</option>
                  <option value="credit_note">Credit Note</option>
                  <option value="receipt">Receipt</option>
                  <option value="statement">Statement</option>
                  <option value="unknown">Unknown</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Vendor Name</label>
                <input
                  type="text"
                  value={vendorName}
                  onChange={(e) => setVendorName(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="Enter vendor name"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Date</label>
                <input
                  type="date"
                  value={documentDate}
                  onChange={(e) => setDocumentDate(e.target.value)}
                  className="ff-input w-full text-sm"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Reference / Invoice No.</label>
                <input
                  type="text"
                  value={referenceNumber}
                  onChange={(e) => setReferenceNumber(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="e.g. INV-001"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Total Amount (ZAR)</label>
                <input
                  type="number"
                  step="0.01"
                  value={totalAmount}
                  onChange={(e) => setTotalAmount(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="0.00"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">VAT Amount (ZAR)</label>
                <input
                  type="number"
                  step="0.01"
                  value={vatAmount}
                  onChange={(e) => setVatAmount(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="0.00"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              {extracted?.vendorVatNumber && (
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Vendor VAT Number</label>
                  <input
                    type="text"
                    value={extracted.vendorVatNumber}
                    className="ff-input w-full text-sm bg-[var(--ff-bg-tertiary)]"
                    readOnly
                  />
                </div>
              )}
              {extracted?.subtotal !== null && extracted?.subtotal !== undefined && (
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Subtotal (extracted)</label>
                  <input
                    type="text"
                    value={formatCurrency(extracted.subtotal)}
                    className="ff-input w-full text-sm bg-[var(--ff-bg-tertiary)]"
                    readOnly
                  />
                </div>
              )}
              <div className="md:col-span-2">
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Notes</label>
                <textarea
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  className="ff-input w-full text-sm"
                  rows={2}
                  placeholder="Optional notes..."
                  disabled={doc.status === 'rejected'}
                />
              </div>
            </div>

            {/* Line Items */}
            {extracted && extracted.lineItems.length > 0 && (
              <div className="px-6 pb-4">
                <h3 className="text-xs font-medium text-[var(--ff-text-secondary)] mb-2">Extracted Line Items</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                        <th className="px-3 py-2 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Description</th>
                        <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Qty</th>
                        <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Unit Price</th>
                        <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Total</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--ff-border-light)]">
                      {extracted.lineItems.map((item, i) => (
                        <tr key={i}>
                          <td className="px-3 py-2 text-[var(--ff-text-primary)]">{item.description}</td>
                          <td className="px-3 py-2 text-right text-[var(--ff-text-secondary)]">{item.quantity ?? '-'}</td>
                          <td className="px-3 py-2 text-right font-mono text-[var(--ff-text-secondary)]">{item.unitPrice !== null ? formatCurrency(item.unitPrice) : '-'}</td>
                          <td className="px-3 py-2 text-right font-mono text-[var(--ff-text-primary)]">{item.total !== null ? formatCurrency(item.total) : '-'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Action Buttons */}
            {doc.status !== 'rejected' && (
              <div className="px-6 py-4 border-t border-[var(--ff-border-light)] flex items-center gap-3 flex-wrap">
                <button
                  onClick={handleConfirm}
                  disabled={isSaving}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium disabled:opacity-50"
                >
                  {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}
                  {doc.status === 'reviewed' ? 'Update' : 'Confirm & Save'}
                </button>
                <button
                  onClick={handleReject}
                  disabled={isSaving}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-red-600/20 text-red-400 rounded-lg hover:bg-red-600/30 transition-colors text-sm font-medium disabled:opacity-50"
                >
                  <XCircle className="h-4 w-4" />
                  Reject
                </button>
              </div>
            )}
          </div>

          {/* Match to Bank Transaction */}
          {doc.status !== 'rejected' && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)]">
              <div className="px-6 py-4 border-b border-[var(--ff-border-light)]">
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Match to Bank Transaction</h2>
                <p className="text-xs text-[var(--ff-text-tertiary)]">Link this document to a bank transaction for reconciliation</p>
              </div>
              <div className="p-6">
                {doc.matchedBankTxId ? (
                  <div className="flex items-center gap-2 text-sm text-teal-400">
                    <Link2 className="h-4 w-4" />
                    Matched to bank transaction: <span className="font-mono text-xs">{doc.matchedBankTxId}</span>
                  </div>
                ) : (
                  <div className="flex items-center gap-3">
                    <input
                      type="text"
                      value={bankTxId}
                      onChange={(e) => setBankTxId(e.target.value)}
                      className="ff-input flex-1 text-sm"
                      placeholder="Enter bank transaction ID..."
                    />
                    <button
                      onClick={handleMatchBankTx}
                      disabled={isMatching || !bankTxId.trim()}
                      className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium disabled:opacity-50"
                    >
                      {isMatching ? <Loader2 className="h-4 w-4 animate-spin" /> : <Link2 className="h-4 w-4" />}
                      Match
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Raw Text Preview */}
          {extracted?.rawText && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)]">
              <button
                onClick={() => setShowRawText(!showRawText)}
                className="w-full px-6 py-4 flex items-center justify-between text-left"
              >
                <div>
                  <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Raw Extracted Text</h2>
                  <p className="text-xs text-[var(--ff-text-tertiary)]">The full text extracted from the PDF</p>
                </div>
                {showRawText ? (
                  <ChevronUp className="h-5 w-5 text-[var(--ff-text-tertiary)]" />
                ) : (
                  <ChevronDown className="h-5 w-5 text-[var(--ff-text-tertiary)]" />
                )}
              </button>
              {showRawText && (
                <div className="px-6 pb-6">
                  <pre className="bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg p-4 text-xs text-[var(--ff-text-secondary)] whitespace-pre-wrap font-mono max-h-96 overflow-y-auto">
                    {extracted.rawText}
                  </pre>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Document Capture Hub
 * Upload PDFs, extract invoice/receipt data via OCR, review and act on results.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  ScanLine, Upload, Loader2, AlertCircle, FileText, CheckCircle2,
  XCircle, Eye, RefreshCw, ChevronRight,
} from 'lucide-react';
import { toast } from 'react-hot-toast';
import type { CapturedDocument, ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';
import { formatCurrency, formatDate } from '@/utils/formatters';

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    pending: 'bg-amber-500/20 text-amber-400',
    reviewed: 'bg-blue-500/20 text-blue-400',
    matched: 'bg-teal-500/20 text-teal-400',
    rejected: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

function ConfidenceBadge({ confidence }: { confidence: number }) {
  let color = 'text-red-400';
  let label = 'Low';
  if (confidence >= 0.7) { color = 'text-teal-400'; label = 'High'; }
  else if (confidence >= 0.4) { color = 'text-amber-400'; label = 'Medium'; }
  return (
    <span className={`text-xs font-medium ${color}`}>
      {label} ({Math.round(confidence * 100)}%)
    </span>
  );
}

export default function DocumentCapturePage() {
  const [documents, setDocuments] = useState<CapturedDocument[]>([]);
  const [total, setTotal] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [statusFilter, setStatusFilter] = useState('');

  // Upload state
  const [isUploading, setIsUploading] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [uploadResult, setUploadResult] = useState<{ document: CapturedDocument; extracted: ExtractedDocument } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Review form state (after upload)
  const [reviewVendor, setReviewVendor] = useState('');
  const [reviewDate, setReviewDate] = useState('');
  const [reviewRef, setReviewRef] = useState('');
  const [reviewTotal, setReviewTotal] = useState('');
  const [reviewVat, setReviewVat] = useState('');
  const [reviewDocType, setReviewDocType] = useState('');
  const [reviewNotes, setReviewNotes] = useState('');

  const loadDocuments = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (statusFilter) params.set('status', statusFilter);
      const res = await fetch(`/api/accounting/document-capture?${params}`);
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Failed to load');
      setDocuments(json.data || []);
      setTotal(json.pagination?.total || 0);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load documents');
    } finally {
      setIsLoading(false);
    }
  }, [statusFilter]);

  useEffect(() => { loadDocuments(); }, [loadDocuments]);

  // Populate review form when upload completes
  useEffect(() => {
    if (uploadResult) {
      const ex = uploadResult.extracted;
      setReviewVendor(ex.vendorName || '');
      setReviewDate(ex.date || '');
      setReviewRef(ex.referenceNumber || '');
      setReviewTotal(ex.totalAmount !== null ? String(ex.totalAmount) : '');
      setReviewVat(ex.vatAmount !== null ? String(ex.vatAmount) : '');
      setReviewDocType(ex.documentType || 'unknown');
      setReviewNotes('');
    }
  }, [uploadResult]);

  async function handleUpload(file: File) {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      toast.error('Only PDF files are supported');
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      toast.error('File too large. Maximum size is 10MB.');
      return;
    }

    setIsUploading(true);
    setUploadResult(null);
    setError('');

    try {
      const formData = new FormData();
      formData.append('file', file);

      const res = await fetch('/api/accounting/document-capture', {
        method: 'POST',
        body: formData,
      });

      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Upload failed');

      setUploadResult(json.data);
      toast.success('Document uploaded and processed');
      loadDocuments();
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Upload failed';
      toast.error(msg);
      setError(msg);
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  }

  function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    if (file) handleUpload(file);
  }

  function handleDragOver(e: React.DragEvent) {
    e.preventDefault();
    setIsDragging(true);
  }

  function handleDragLeave(e: React.DragEvent) {
    e.preventDefault();
    setIsDragging(false);
  }

  async function handleConfirm() {
    if (!uploadResult) return;
    try {
      const res = await fetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: uploadResult.document.id,
          action: 'confirm',
          data: {
            vendorName: reviewVendor || null,
            documentDate: reviewDate || null,
            referenceNumber: reviewRef || null,
            totalAmount: reviewTotal ? parseFloat(reviewTotal) : null,
            vatAmount: reviewVat ? parseFloat(reviewVat) : null,
            documentType: reviewDocType || null,
            notes: reviewNotes || null,
          },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Confirm failed');
      toast.success('Document confirmed');
      setUploadResult(null);
      loadDocuments();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Confirm failed');
    }
  }

  async function handleReject() {
    if (!uploadResult) return;
    try {
      const res = await fetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: uploadResult.document.id,
          action: 'reject',
          data: { notes: reviewNotes || 'Rejected during review' },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Reject failed');
      toast.success('Document rejected');
      setUploadResult(null);
      loadDocuments();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Reject failed');
    }
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <ScanLine className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Document Capture</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Upload invoices and receipts for automated data extraction
                </p>
              </div>
            </div>
            <button
              onClick={() => loadDocuments()}
              className="inline-flex items-center gap-2 px-3 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              <RefreshCw className="h-4 w-4" />
              Refresh
            </button>
          </div>
        </div>

        <div className="p-6 space-y-6">
          {/* Upload Zone */}
          <div
            onDrop={handleDrop}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            className={`relative border-2 border-dashed rounded-xl p-8 text-center transition-all cursor-pointer ${
              isDragging
                ? 'border-teal-500 bg-teal-500/5'
                : 'border-[var(--ff-border-light)] hover:border-teal-500/50 hover:bg-[var(--ff-bg-secondary)]'
            }`}
            onClick={() => fileInputRef.current?.click()}
          >
            <input
              ref={fileInputRef}
              type="file"
              accept=".pdf,application/pdf"
              className="hidden"
              onChange={(e) => {
                const file = e.target.files?.[0];
                if (file) handleUpload(file);
              }}
            />
            {isUploading ? (
              <div className="flex flex-col items-center gap-3">
                <Loader2 className="h-10 w-10 text-teal-500 animate-spin" />
                <p className="text-sm text-[var(--ff-text-secondary)]">Processing document...</p>
              </div>
            ) : (
              <div className="flex flex-col items-center gap-3">
                <Upload className="h-10 w-10 text-[var(--ff-text-tertiary)]" />
                <div>
                  <p className="text-sm font-medium text-[var(--ff-text-primary)]">
                    Drop a PDF here or click to browse
                  </p>
                  <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
                    Invoices, receipts, credit notes — PDF up to 10MB
                  </p>
                </div>
              </div>
            )}
          </div>

          {/* Extraction Review Panel */}
          {uploadResult && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)] overflow-hidden">
              <div className="px-6 py-4 border-b border-[var(--ff-border-light)] flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <FileText className="h-5 w-5 text-teal-500" />
                  <div>
                    <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                      Extraction Results
                    </h2>
                    <p className="text-xs text-[var(--ff-text-secondary)]">
                      {uploadResult.document.fileName}
                    </p>
                  </div>
                </div>
                <ConfidenceBadge confidence={uploadResult.extracted.confidence} />
              </div>

              {/* Warnings */}
              {uploadResult.extracted.warnings.length > 0 && (
                <div className="px-6 py-3 bg-amber-500/5 border-b border-[var(--ff-border-light)]">
                  {uploadResult.extracted.warnings.map((w, i) => (
                    <div key={i} className="flex items-start gap-2 text-xs text-amber-400">
                      <AlertCircle className="h-3.5 w-3.5 mt-0.5 shrink-0" />
                      <span>{w}</span>
                    </div>
                  ))}
                </div>
              )}

              <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Document Type</label>
                  <select
                    value={reviewDocType}
                    onChange={(e) => setReviewDocType(e.target.value)}
                    className="ff-select w-full text-sm"
                  >
                    <option value="invoice">Invoice</option>
                    <option value="credit_note">Credit Note</option>
                    <option value="receipt">Receipt</option>
                    <option value="statement">Statement</option>
                    <option value="unknown">Unknown</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Vendor Name</label>
                  <input
                    type="text"
                    value={reviewVendor}
                    onChange={(e) => setReviewVendor(e.target.value)}
                    className="ff-input w-full text-sm"
                    placeholder="Enter vendor name"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Date</label>
                  <input
                    type="date"
                    value={reviewDate}
                    onChange={(e) => setReviewDate(e.target.value)}
                    className="ff-input w-full text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Reference / Invoice No.</label>
                  <input
                    type="text"
                    value={reviewRef}
                    onChange={(e) => setReviewRef(e.target.value)}
                    className="ff-input w-full text-sm"
                    placeholder="e.g. INV-001"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Total Amount (ZAR)</label>
                  <input
                    type="number"
                    step="0.01"
                    value={reviewTotal}
                    onChange={(e) => setReviewTotal(e.target.value)}
                    className="ff-input w-full text-sm"
                    placeholder="0.00"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">VAT Amount (ZAR)</label>
                  <input
                    type="number"
                    step="0.01"
                    value={reviewVat}
                    onChange={(e) => setReviewVat(e.target.value)}
                    className="ff-input w-full text-sm"
                    placeholder="0.00"
                  />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Notes</label>
                  <textarea
                    value={reviewNotes}
                    onChange={(e) => setReviewNotes(e.target.value)}
                    className="ff-input w-full text-sm"
                    rows={2}
                    placeholder="Optional notes..."
                  />
                </div>
              </div>

              {/* Line Items (read-only display) */}
              {uploadResult.extracted.lineItems.length > 0 && (
                <div className="px-6 pb-4">
                  <h3 className="text-xs font-medium text-[var(--ff-text-secondary)] mb-2">Extracted Line Items</h3>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                          <th className="px-3 py-2 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Description</th>
                          <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Qty</th>
                          <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Unit Price</th>
                          <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Total</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-[var(--ff-border-light)]">
                        {uploadResult.extracted.lineItems.map((item, i) => (
                          <tr key={i}>
                            <td className="px-3 py-2 text-[var(--ff-text-primary)]">{item.description}</td>
                            <td className="px-3 py-2 text-right text-[var(--ff-text-secondary)]">{item.quantity ?? '-'}</td>
                            <td className="px-3 py-2 text-right font-mono text-[var(--ff-text-secondary)]">{item.unitPrice !== null ? formatCurrency(item.unitPrice) : '-'}</td>
                            <td className="px-3 py-2 text-right font-mono text-[var(--ff-text-primary)]">{item.total !== null ? formatCurrency(item.total) : '-'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              {/* Action Buttons */}
              <div className="px-6 py-4 border-t border-[var(--ff-border-light)] flex items-center gap-3 flex-wrap">
                <button
                  onClick={handleConfirm}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium"
                >
                  <CheckCircle2 className="h-4 w-4" />
                  Confirm & Save
                </button>
                <button
                  onClick={handleReject}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-red-600/20 text-red-400 rounded-lg hover:bg-red-600/30 transition-colors text-sm font-medium"
                >
                  <XCircle className="h-4 w-4" />
                  Reject
                </button>
                <button
                  onClick={() => setUploadResult(null)}
                  className="inline-flex items-center gap-2 px-4 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors text-sm"
                >
                  Save & Review Later
                </button>
              </div>
            </div>
          )}

          {/* Document List */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)] overflow-hidden">
            <div className="px-6 py-4 border-b border-[var(--ff-border-light)] flex items-center justify-between">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                Captured Documents
                {total > 0 && <span className="text-sm font-normal text-[var(--ff-text-tertiary)] ml-2">({total})</span>}
              </h2>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="ff-select text-sm"
              >
                <option value="">All Statuses</option>
                <option value="pending">Pending</option>
                <option value="reviewed">Reviewed</option>
                <option value="matched">Matched</option>
                <option value="rejected">Rejected</option>
              </select>
            </div>

            {isLoading ? (
              <div className="flex items-center justify-center py-12">
                <Loader2 className="h-6 w-6 text-teal-500 animate-spin" />
              </div>
            ) : error ? (
              <div className="flex items-center gap-2 justify-center py-12 text-red-400 text-sm">
                <AlertCircle className="h-4 w-4" />
                {error}
              </div>
            ) : documents.length === 0 ? (
              <div className="text-center py-12 text-[var(--ff-text-tertiary)] text-sm">
                No documents captured yet. Upload a PDF above to get started.
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">File</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Type</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Vendor</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Date</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Reference</th>
                      <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Total</th>
                      <th className="px-4 py-3 text-center text-xs font-medium text-[var(--ff-text-secondary)]">Status</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Uploaded</th>
                      <th className="px-4 py-3"></th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--ff-border-light)]">
                    {documents.map((doc) => (
                      <tr key={doc.id} className="hover:bg-[var(--ff-bg-tertiary)] transition-colors">
                        <td className="px-4 py-3">
                          <div className="flex items-center gap-2">
                            <FileText className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                            <span className="text-[var(--ff-text-primary)] font-medium truncate max-w-[200px]">
                              {doc.fileName}
                            </span>
                          </div>
                        </td>
                        <td className="px-4 py-3 text-[var(--ff-text-secondary)] capitalize">{doc.documentType || '-'}</td>
                        <td className="px-4 py-3 text-[var(--ff-text-primary)]">{doc.vendorName || '-'}</td>
                        <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{formatDate(doc.documentDate)}</td>
                        <td className="px-4 py-3 text-[var(--ff-text-secondary)] font-mono text-xs">{doc.referenceNumber || '-'}</td>
                        <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">{formatCurrency(doc.totalAmount)}</td>
                        <td className="px-4 py-3 text-center"><StatusBadge status={doc.status} /></td>
                        <td className="px-4 py-3 text-[var(--ff-text-tertiary)] text-xs">{formatDate(doc.createdAt)}</td>
                        <td className="px-4 py-3">
                          <Link
                            href={`/accounting/document-capture/${doc.id}`}
                            className="inline-flex items-center gap-1 text-teal-500 hover:text-teal-400 text-xs"
                          >
                            <Eye className="h-3.5 w-3.5" />
                            View
                            <ChevronRight className="h-3 w-3" />
                          </Link>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Supplier Returns / Debit Notes
 * Sage equivalent: Suppliers > Returns
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { TrendingDown, Loader2, AlertCircle, Plus, X } from 'lucide-react';
import toast from 'react-hot-toast';
import { formatCurrency } from '@/utils/formatters';

interface SupplierReturn {
  id: string; return_number: string; supplier_name: string;
  original_invoice_number?: string; amount: number;
  status: string; return_date: string; reason: string;
}
interface Supplier { id: number; name: string; }
interface Form { supplierId: string; originalInvoiceNumber: string; amount: string; reason: string; }

const EMPTY: Form = { supplierId: '', originalInvoiceNumber: '', amount: '', reason: '' };

export default function SupplierReturnsPage() {
  const [returns, setReturns] = useState<SupplierReturn[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState<Form>(EMPTY);
  const [submitting, setSubmitting] = useState(false);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);

  const loadReturns = useCallback(async () => {
    setIsLoading(true); setError('');
    try {
      const res = await fetch('/api/accounting/supplier-returns');
      const json = await res.json();
      setReturns((json.data || json).returns || []);
    } catch { setError('Failed to load supplier returns'); }
    finally { setIsLoading(false); }
  }, []);

  useEffect(() => { loadReturns(); }, [loadReturns]);

  useEffect(() => {
    fetch('/api/procurement/suppliers').then(r => r.json()).then(json => {
      const data = json.data || json;
      setSuppliers((data.suppliers || []).map((s: Record<string, unknown>) => ({
        id: s.id as number,
        name: (s.company_name || s.name) as string,
      })));
    }).catch(() => { /* non-critical */ });
  }, []);

  function set(field: keyof Form, value: string) {
    setForm(f => ({ ...f, [field]: value }));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!form.supplierId) { toast.error('Please select a supplier'); return; }
    if (!form.amount || Number(form.amount) <= 0) { toast.error('Please enter a valid amount'); return; }
    setSubmitting(true);
    try {
      const res = await fetch('/api/accounting/supplier-returns', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          supplierId: Number(form.supplierId),
          originalInvoiceNumber: form.originalInvoiceNumber || undefined,
          amount: Number(form.amount),
          reason: form.reason || undefined,
        }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to create return');
      toast.success('Supplier return created');
      setShowForm(false); setForm(EMPTY);
      await loadReturns();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to create return');
    } finally { setSubmitting(false); }
  }

  const inp = 'w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-teal-500';
  const lbl = 'block text-xs font-medium text-[var(--ff-text-secondary)] mb-1';

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-red-500/10">
                <TrendingDown className="h-6 w-6 text-red-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Supplier Returns</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Debit notes and returns to suppliers</p>
              </div>
            </div>
            <button onClick={() => { setForm(EMPTY); setShowForm(true); }}
              className="px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg flex items-center gap-2 text-sm">
              <Plus className="h-4 w-4" /> New Return
            </button>
          </div>
        </div>

        {/* Create form panel */}
        {showForm && (
          <div className="px-6 pt-6">
            <div className="rounded-xl border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] p-6 mb-4">
              <div className="flex items-center justify-between mb-5">
                <h2 className="text-base font-semibold text-[var(--ff-text-primary)]">New Supplier Return</h2>
                <button onClick={() => { setShowForm(false); setForm(EMPTY); }}
                  className="text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]">
                  <X className="h-5 w-5" />
                </button>
              </div>
              <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-4">
                  <div>
                    <label className={lbl}>Supplier <span className="text-red-400">*</span></label>
                    <select className={inp} value={form.supplierId}
                      onChange={e => set('supplierId', e.target.value)} required>
                      <option value="">Select supplier…</option>
                      {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className={lbl}>Original Invoice #</label>
                    <input type="text" className={inp} placeholder="e.g. INV-00123"
                      value={form.originalInvoiceNumber}
                      onChange={e => set('originalInvoiceNumber', e.target.value)} />
                  </div>
                  <div>
                    <label className={lbl}>Amount <span className="text-red-400">*</span></label>
                    <div className="relative">
                      <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--ff-text-secondary)] text-sm">R</span>
                      <input type="number" min="0.01" step="0.01" className={`${inp} pl-7`}
                        placeholder="0.00" value={form.amount}
                        onChange={e => set('amount', e.target.value)} required />
                    </div>
                  </div>
                  <div>
                    <label className={lbl}>Reason</label>
                    <textarea className={`${inp} resize-none h-[42px]`} placeholder="Reason for return…"
                      value={form.reason} onChange={e => set('reason', e.target.value)} />
                  </div>
                </div>
                <div className="flex justify-end gap-3">
                  <button type="button"
                    onClick={() => { setShowForm(false); setForm(EMPTY); }}
                    className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg">
                    Cancel
                  </button>
                  <button type="submit" disabled={submitting}
                    className="px-4 py-2 text-sm bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white rounded-lg flex items-center gap-2">
                    {submitting && <Loader2 className="h-4 w-4 animate-spin" />}
                    Create Return
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* List */}
        <div className="p-6">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-red-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" /><span>{error}</span>
            </div>
          ) : returns.length === 0 ? (
            <div className="text-center py-12">
              <TrendingDown className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)]">No supplier returns found</p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">Create a debit note to process a return to a supplier</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--ff-border-light)]">
                    {['Return #', 'Supplier', 'Original Invoice', 'Date', 'Amount', 'Reason', 'Status'].map(h => (
                      <th key={h} className={`py-3 px-4 text-[var(--ff-text-secondary)] font-medium ${h === 'Amount' ? 'text-right' : 'text-left'}`}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {returns.map(r => (
                    <tr key={r.id} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)]">
                      <td className="py-3 px-4 text-[var(--ff-text-primary)] font-mono">{r.return_number}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-primary)]">{r.supplier_name}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{r.original_invoice_number || '-'}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{r.return_date?.split('T')[0]}</td>
                      <td className="py-3 px-4 text-right text-red-400">{formatCurrency(r.amount)}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{r.reason}</td>
                      <td className="py-3 px-4">
                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${r.status === 'processed' ? 'bg-teal-500/10 text-teal-400' : 'bg-yellow-500/10 text-yellow-400'}`}>
                          {r.status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Bank Accounts Management
 * Sage equivalent: Banking > Bank Accounts
 * View and manage bank accounts linked to GL
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Landmark, Loader2, AlertCircle, Plus, ArrowUpRight, ArrowDownRight, X, Pencil } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { formatCurrency } from '@/utils/formatters';

/** Mask account number for display: show last 4 digits only */
function maskAccountNumber(num: string): string {
  if (num.length <= 4) return num;
  return '****' + num.slice(-4);
}

interface BankAccount {
  id: string;
  accountCode: string;
  accountName: string;
  description?: string;
  bankAccountNumber?: string | null;
  isActive: boolean;
  txnCount: number;
  totalDebits: number;
  totalCredits: number;
  balance: number;
  firstDate?: string;
  lastDate?: string;
}

interface EditForm {
  accountName: string;
  description: string;
  bankAccountNumber: string;
}

export default function BankAccountsPage() {
  const [accounts, setAccounts] = useState<BankAccount[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [showAddModal, setShowAddModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({ accountCode: '', accountName: '', description: '', bankAccountNumber: '' });

  const [editingAccount, setEditingAccount] = useState<BankAccount | null>(null);
  const [editForm, setEditForm] = useState<EditForm>({ accountName: '', description: '', bankAccountNumber: '' });

  const loadAccounts = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const res = await fetch('/api/accounting/bank-accounts');
      const json = await res.json();
      const data = json.data || json;
      setAccounts(Array.isArray(data) ? data : []);
    } catch {
      setError('Failed to load bank accounts');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => { loadAccounts(); }, [loadAccounts]);

  const handleAdd = async () => {
    if (!form.accountCode || !form.accountName) {
      toast.error('Account code and name are required');
      return;
    }
    setSaving(true);
    try {
      const res = await fetch('/api/accounting/chart-of-accounts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          accountCode: form.accountCode,
          accountName: form.accountName,
          accountType: 'asset',
          accountSubtype: 'bank',
          parentAccountId: 'bf801b3b-de70-4c10-8d8f-689de8b8a9ad',
          description: form.description || form.accountName,
          normalBalance: 'debit',
        }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) {
        toast.error(json.message || json.error || 'Failed to create account');
        return;
      }
      // If bank account number provided, save it separately
      if (form.bankAccountNumber.trim()) {
        const created = json.data || json;
        await fetch('/api/accounting/bank-accounts', {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ id: created.id, bankAccountNumber: form.bankAccountNumber.trim() }),
        });
      }
      toast.success('Bank account created');
      setShowAddModal(false);
      setForm({ accountCode: '', accountName: '', description: '', bankAccountNumber: '' });
      loadAccounts();
    } catch {
      toast.error('Failed to create bank account');
    } finally {
      setSaving(false);
    }
  };

  const handleEdit = (acct: BankAccount) => {
    setEditingAccount(acct);
    setEditForm({
      accountName: acct.accountName,
      description: acct.description || '',
      bankAccountNumber: acct.bankAccountNumber || '',
    });
  };

  const handleSaveEdit = async () => {
    if (!editingAccount) return;
    if (!editForm.accountName.trim()) {
      toast.error('Account name is required');
      return;
    }
    setSaving(true);
    try {
      // Update name & description via chart-of-accounts
      const coaRes = await fetch('/api/accounting/chart-of-accounts', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          id: editingAccount.id,
          accountName: editForm.accountName.trim(),
          description: editForm.description.trim() || null,
        }),
      });
      if (!coaRes.ok) {
        const json = await coaRes.json();
        toast.error(json.message || 'Failed to update account');
        return;
      }
      // Update bank account number
      await fetch('/api/accounting/bank-accounts', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          id: editingAccount.id,
          bankAccountNumber: editForm.bankAccountNumber.trim() || null,
        }),
      });
      toast.success('Bank account updated');
      setEditingAccount(null);
      loadAccounts();
    } catch {
      toast.error('Failed to update bank account');
    } finally {
      setSaving(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-cyan-500/10">
                  <Landmark className="h-6 w-6 text-cyan-500" />
                </div>
                <div>
                  <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Bank Accounts</h1>
                  <p className="text-sm text-[var(--ff-text-secondary)]">
                    Manage bank accounts and view balances
                  </p>
                </div>
              </div>
              <button
                onClick={() => setShowAddModal(true)}
                className="px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg flex items-center gap-2 text-sm"
              >
                <Plus className="h-4 w-4" />
                Add Bank Account
              </button>
            </div>
          </div>
        </div>

        <div className="p-6">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-cyan-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" />
              <span>{error}</span>
            </div>
          ) : accounts.length === 0 ? (
            <div className="text-center py-12">
              <Landmark className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)]">No bank accounts configured</p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">
                Bank accounts are GL accounts with subtype &quot;bank&quot;
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {accounts.map((acct) => (
                <div key={acct.id} className="p-5 rounded-xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] hover:border-cyan-500/30 transition-colors relative group">
                  <button
                    onClick={() => handleEdit(acct)}
                    className="absolute top-3 right-12 p-1.5 rounded-lg opacity-0 group-hover:opacity-100 hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)] hover:text-cyan-400 transition-all"
                    title="Edit account"
                  >
                    <Pencil className="h-3.5 w-3.5" />
                  </button>
                  <div className="flex items-center justify-between mb-3">
                    <span className="text-xs font-mono text-[var(--ff-text-tertiary)]">{acct.accountCode}</span>
                    <span className={`px-2 py-0.5 rounded-full text-xs ${acct.isActive ? 'bg-teal-500/10 text-teal-400' : 'bg-red-500/10 text-red-400'}`}>
                      {acct.isActive ? 'Active' : 'Inactive'}
                    </span>
                  </div>
                  <h3 className="text-lg font-semibold text-[var(--ff-text-primary)]">{acct.accountName}</h3>
                  {acct.bankAccountNumber && (
                    <p className="text-xs font-mono text-[var(--ff-text-tertiary)] mt-0.5">
                      Acc: {maskAccountNumber(acct.bankAccountNumber)}
                    </p>
                  )}
                  {acct.description && (
                    <p className="text-sm text-[var(--ff-text-secondary)] mt-1">{acct.description}</p>
                  )}

                  <div className="mt-4 pt-3 border-t border-[var(--ff-border-light)]">
                    <p className="text-sm text-[var(--ff-text-secondary)]">Net Balance</p>
                    <p className={`text-2xl font-bold ${acct.balance >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                      {formatCurrency(acct.balance)}
                    </p>
                  </div>

                  <div className="mt-3 flex gap-4 text-sm">
                    <div className="flex items-center gap-1 text-teal-400">
                      <ArrowDownRight className="h-3.5 w-3.5" />
                      <span>{formatCurrency(acct.totalCredits)}</span>
                    </div>
                    <div className="flex items-center gap-1 text-red-400">
                      <ArrowUpRight className="h-3.5 w-3.5" />
                      <span>{formatCurrency(acct.totalDebits)}</span>
                    </div>
                  </div>

                  <div className="mt-3 flex items-center justify-between text-xs text-[var(--ff-text-tertiary)]">
                    <span>{acct.txnCount.toLocaleString()} transactions</span>
                    {acct.firstDate && acct.lastDate && (
                      <span>{acct.firstDate} &rarr; {acct.lastDate}</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Add Bank Account Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)] w-full max-w-md mx-4 p-6">
            <div className="flex items-center justify-between mb-5">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Add Bank Account</h2>
              <button onClick={() => setShowAddModal(false)} className="text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]">
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                  Account Code *
                </label>
                <input
                  type="text"
                  placeholder="e.g. 1114"
                  value={form.accountCode}
                  onChange={e => setForm(f => ({ ...f, accountCode: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-cyan-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                  Account Name *
                </label>
                <input
                  type="text"
                  placeholder="e.g. Bank - FNB Current"
                  value={form.accountName}
                  onChange={e => setForm(f => ({ ...f, accountName: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-cyan-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                  Bank Account Number
                </label>
                <input
                  type="text"
                  placeholder="e.g. 4078012345"
                  value={form.bankAccountNumber}
                  onChange={e => setForm(f => ({ ...f, bankAccountNumber: e.target.value }))}
                  maxLength={50}
                  className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-cyan-500"
                />
                <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">Displayed masked (last 4 digits only) for security</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                  Description
                </label>
                <input
                  type="text"
                  placeholder="Optional description"
                  value={form.description}
                  onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-cyan-500"
                />
              </div>

              <p className="text-xs text-[var(--ff-text-tertiary)]">
                Creates a GL account under Current Assets (1100) with subtype &quot;bank&quot;.
              </p>
            </div>

            <div className="flex justify-end gap-3 mt-6">
              <button
                onClick={() => setShowAddModal(false)}
                className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]"
              >
                Cancel
              </button>
              <button
                onClick={handleAdd}
                disabled={saving}
                className="px-4 py-2 bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white rounded-lg text-sm flex items-center gap-2"
              >
                {saving && <Loader2 className="h-4 w-4 animate-spin" />}
                Create Account
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Edit Bank Account Modal */}
      {editingAccount && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50" onClick={() => setEditingAccount(null)}>
          <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)] w-full max-w-md mx-4 p-6" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-5">
              <div>
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Edit Bank Account</h2>
                <p className="text-xs font-mono text-[var(--ff-text-tertiary)]">GL Code: {editingAccount.accountCode}</p>
              </div>
              <button onClick={() => setEditingAccount(null)} className="text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]">
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                  Account Name *
                </label>
                <input
                  type="text"
                  value={editForm.accountName}
                  onChange={e => setEditForm(f => ({ ...f, accountName: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-cyan-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                  Bank Account Number
                </label>
                <input
                  type="text"
                  placeholder="e.g. 4078012345"
                  value={editForm.bankAccountNumber}
                  onChange={e => setEditForm(f => ({ ...f, bankAccountNumber: e.target.value }))}
                  maxLength={50}
                  className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-cyan-500"
                />
                <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">Displayed masked (last 4 digits only) for security</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                  Description
                </label>
                <input
                  type="text"
                  placeholder="Optional description"
                  value={editForm.description}
                  onChange={e => setEditForm(f => ({ ...f, description: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-cyan-500"
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 mt-6">
              <button
                onClick={() => setEditingAccount(null)}
                className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]"
              >
                Cancel
              </button>
              <button
                onClick={handleSaveEdit}
                disabled={saving}
                className="px-4 py-2 bg-cyan-600 hover:bg-cyan-700 disabled:opacity-50 text-white rounded-lg text-sm flex items-center gap-2"
              >
                {saving && <Loader2 className="h-4 w-4 animate-spin" />}
                Save Changes
              </button>
            </div>
          </div>
        </div>
      )}
    </AppLayout>
  );
}

/**
 * Customer Payment Detail Page
 * View payment details, allocations, and perform actions (confirm/cancel)
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Wallet, Loader2, AlertCircle, Check, X } from 'lucide-react';
import { AccountingDocumentPanel } from '@/modules/accounting/documents';
import toast from 'react-hot-toast';
import { formatCurrency, formatDate } from '@/utils/formatters';

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    draft: 'bg-gray-500/20 text-gray-400',
    confirmed: 'bg-teal-500/20 text-teal-400',
    reconciled: 'bg-blue-500/20 text-blue-400',
    cancelled: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

interface Allocation {
  id: string;
  invoiceId: string;
  amountAllocated: number;
  invoiceNumber?: string;
}

interface Payment {
  id: string;
  paymentNumber: string;
  clientId: string;
  clientName?: string;
  paymentDate: string;
  totalAmount: number;
  paymentMethod: string;
  bankReference?: string;
  description?: string;
  status: string;
  glJournalEntryId?: string;
  allocations: Allocation[];
}

export default function CustomerPaymentDetailPage() {
  const router = useRouter();
  const paymentId = router.query.paymentId as string;

  const [payment, setPayment] = useState<Payment | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [acting, setActing] = useState(false);

  const loadPayment = useCallback(async () => {
    if (!paymentId) return;
    setIsLoading(true);
    setError('');
    try {
      const res = await fetch(`/api/accounting/customer-payments?id=${paymentId}`);
      const json = await res.json();
      const data = json.data || json;
      setPayment(data);
    } catch {
      setError('Failed to load payment');
    } finally {
      setIsLoading(false);
    }
  }, [paymentId]);

  useEffect(() => { loadPayment(); }, [loadPayment]);

  async function handleAction(action: 'confirm' | 'cancel') {
    if (!payment) return;

    if (action === 'cancel') {
      const reason = prompt('Reason for cancellation:');
      if (reason === null) return;
      setActing(true);
      try {
        const res = await fetch('/api/accounting/customer-payments-action', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ action: 'cancel', paymentId: payment.id, reason }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.error || 'Cancel failed');
        toast.success('Payment cancelled');
        loadPayment();
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to cancel');
      } finally {
        setActing(false);
      }
    } else {
      setActing(true);
      try {
        const res = await fetch('/api/accounting/customer-payments-action', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ action: 'confirm', paymentId: payment.id }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.error || 'Confirm failed');
        toast.success('Payment confirmed and GL posted');
        loadPayment();
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to confirm');
      } finally {
        setActing(false);
      }
    }
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link href="/accounting/customer-payments" className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)]">
                <ArrowLeft className="h-5 w-5 text-[var(--ff-text-secondary)]" />
              </Link>
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Wallet className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <div className="flex items-center gap-3">
                  <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                    {payment?.paymentNumber || 'Payment'}
                  </h1>
                  {payment && <StatusBadge status={payment.status} />}
                </div>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  {payment?.clientName || 'Loading...'}
                </p>
              </div>
            </div>
            {payment && (
              <div className="flex gap-2">
                {payment.status === 'draft' && (
                  <button onClick={() => handleAction('confirm')} disabled={acting}
                    className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-500 text-white rounded-lg text-sm disabled:opacity-50">
                    <Check className="h-4 w-4" /> Confirm & Post GL
                  </button>
                )}
                {payment.status === 'confirmed' && (
                  <button onClick={() => handleAction('cancel')} disabled={acting}
                    className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-500 text-white rounded-lg text-sm disabled:opacity-50">
                    <X className="h-4 w-4" /> Cancel Payment
                  </button>
                )}
              </div>
            )}
          </div>
        </div>

        <div className="p-6 space-y-6">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" /><span>{error}</span>
            </div>
          ) : payment ? (
            <>
              {/* Payment Info */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {[
                  { label: 'Amount', value: formatCurrency(payment.totalAmount) },
                  { label: 'Date', value: formatDate(payment.paymentDate) },
                  { label: 'Method', value: payment.paymentMethod.toUpperCase() },
                  { label: 'Bank Reference', value: payment.bankReference || '-' },
                ].map(item => (
                  <div key={item.label} className="p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                    <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">{item.label}</p>
                    <p className="text-sm font-medium text-[var(--ff-text-primary)]">{item.value}</p>
                  </div>
                ))}
              </div>

              {payment.description && (
                <div className="p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                  <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">Description</p>
                  <p className="text-sm text-[var(--ff-text-primary)]">{payment.description}</p>
                </div>
              )}

              {payment.glJournalEntryId && (
                <div className="p-3 rounded-lg bg-blue-500/10 border border-blue-500/20">
                  <Link href={`/accounting/journal-entries/${payment.glJournalEntryId}`}
                    className="text-sm text-blue-400 hover:text-blue-300">
                    View GL Journal Entry
                  </Link>
                </div>
              )}

              {/* Allocations */}
              <div>
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-3">Invoice Allocations</h2>
                <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-light)]">
                        <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Invoice #</th>
                        <th className="text-right px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Amount Allocated</th>
                      </tr>
                    </thead>
                    <tbody>
                      {payment.allocations.map(alloc => (
                        <tr key={alloc.id} className="border-b border-[var(--ff-border-light)]">
                          <td className="px-4 py-3">
                            <Link href={`/accounting/customer-invoices/${alloc.invoiceId}`}
                              className="text-blue-400 hover:text-blue-300 font-mono">
                              {alloc.invoiceNumber || alloc.invoiceId}
                            </Link>
                          </td>
                          <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">
                            {formatCurrency(alloc.amountAllocated)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Documents */}
              <AccountingDocumentPanel
                entityType="customer_payment"
                entityId={paymentId}
                allowedTypes={[
                  { value: 'proof_of_payment', label: 'Proof of Payment' },
                  { value: 'bank_statement', label: 'Bank Statement' },
                  { value: 'receipt', label: 'Receipt' },
                  { value: 'other', label: 'Other' },
                ]}
              />
            </>
          ) : null}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Payroll Run Detail Page
 * View run summary, payslips, complete/reverse, download payslips.
 * Route: /payroll/runs/[runId]
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  CalendarDays, Loader2, AlertCircle, ArrowLeft,
  CheckCircle, RotateCcw, FileText, Download,
} from 'lucide-react';
import Link from 'next/link';
import { toast } from 'react-hot-toast';

interface Payslip {
  id: string;
  employee_number?: string;
  first_name?: string;
  last_name?: string;
  department?: string;
  basic_salary: number;
  travel_allowance: number;
  housing_allowance: number;
  cell_allowance: number;
  other_allowances: number;
  gross_pay: number;
  paye: number;
  uif_employee: number;
  uif_employer: number;
  sdl: number;
  medical_aid: number;
  retirement_fund: number;
  other_deductions: number;
  total_deductions: number;
  net_pay: number;
  ytd_gross: number;
  ytd_paye: number;
}

interface PayrollRunDetail {
  id: string;
  period_start: string;
  period_end: string;
  run_date: string;
  status: string;
  total_gross: number;
  total_paye: number;
  total_uif_employee: number;
  total_uif_employer: number;
  total_sdl: number;
  total_net: number;
  total_company_cost: number;
  journal_entry_id: string | null;
  payslips: Payslip[];
}

function formatCurrency(amount: number): string {
  return `R ${amount.toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function formatDate(d: string): string {
  return new Date(d).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' });
}

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    draft: 'bg-yellow-500/10 text-yellow-400',
    processing: 'bg-blue-500/10 text-blue-400',
    completed: 'bg-teal-500/10 text-teal-400',
    reversed: 'bg-red-500/10 text-red-400',
  };
  return (
    <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/10 text-gray-400'}`}>
      {status.charAt(0).toUpperCase() + status.slice(1)}
    </span>
  );
}

export default function PayrollRunDetailPage() {
  const router = useRouter();
  const { runId } = router.query;

  const [run, setRun] = useState<PayrollRunDetail | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [isActioning, setIsActioning] = useState(false);

  const loadRun = useCallback(async () => {
    if (!runId) return;
    setIsLoading(true);
    setError('');
    try {
      const res = await fetch(`/api/payroll/payroll-runs-detail?id=${runId}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = await res.json();
      setRun((json.data ?? json) as PayrollRunDetail);
    } catch {
      setError('Failed to load payroll run');
    } finally {
      setIsLoading(false);
    }
  }, [runId]);

  useEffect(() => {
    loadRun();
  }, [loadRun]);

  async function handleAction(action: 'complete' | 'reverse') {
    if (!run) return;
    const label = action === 'complete' ? 'complete and post to GL' : 'reverse';
    if (!confirm(`Are you sure you want to ${label} this payroll run?`)) return;

    setIsActioning(true);
    try {
      const res = await fetch('/api/payroll/payroll-runs-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ runId: run.id, action }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message ?? json.message ?? `HTTP ${res.status}`);

      toast.success(action === 'complete' ? 'Payroll completed and posted to GL' : 'Payroll run reversed');
      loadRun();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : `Failed to ${action} payroll run`);
    } finally {
      setIsActioning(false);
    }
  }

  if (isLoading) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center py-16">
          <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
        </div>
      </AppLayout>
    );
  }

  if (error || !run) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center gap-2 text-red-400 py-12">
          <AlertCircle className="h-5 w-5" />
          <span>{error || 'Payroll run not found'}</span>
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link
                href="/payroll/runs"
                className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] transition-colors"
              >
                <ArrowLeft className="h-5 w-5" />
              </Link>
              <div className="p-2 rounded-lg bg-teal-500/10">
                <CalendarDays className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-[var(--ff-text-primary)]">
                  Payroll Run: {formatDate(run.period_start)} - {formatDate(run.period_end)}
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)] flex items-center gap-2">
                  Run date: {formatDate(run.run_date)}
                  <StatusBadge status={run.status} />
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              {run.status === 'draft' && (
                <button
                  onClick={() => handleAction('complete')}
                  disabled={isActioning}
                  className="flex items-center gap-2 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white text-sm font-medium transition-colors"
                >
                  {isActioning ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle className="h-4 w-4" />}
                  Complete & Post to GL
                </button>
              )}
              {run.status === 'completed' && (
                <button
                  onClick={() => handleAction('reverse')}
                  disabled={isActioning}
                  className="flex items-center gap-2 px-4 py-2 rounded-lg bg-red-600 hover:bg-red-700 disabled:opacity-50 text-white text-sm font-medium transition-colors"
                >
                  {isActioning ? <Loader2 className="h-4 w-4 animate-spin" /> : <RotateCcw className="h-4 w-4" />}
                  Reverse
                </button>
              )}
            </div>
          </div>
        </div>

        <div className="p-6">
          {/* Summary Stats */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
            <StatCard label="Total Gross" value={formatCurrency(run.total_gross)} />
            <StatCard label="Total PAYE" value={formatCurrency(run.total_paye)} />
            <StatCard label="Total Net Pay" value={formatCurrency(run.total_net)} highlight />
            <StatCard label="Company Cost" value={formatCurrency(run.total_company_cost)} />
            <StatCard label="UIF (Employee)" value={formatCurrency(run.total_uif_employee)} />
            <StatCard label="UIF (Employer)" value={formatCurrency(run.total_uif_employer)} />
            <StatCard label="SDL" value={formatCurrency(run.total_sdl)} />
            <StatCard label="Employees" value={String(run.payslips.length)} />
          </div>

          {run.journal_entry_id && (
            <div className="mb-6 p-3 rounded-lg bg-teal-500/5 border border-teal-500/20 text-sm text-teal-400">
              GL Journal Entry posted: {run.journal_entry_id}
            </div>
          )}

          {/* Payslips Table */}
          <div className="mb-6 flex items-center justify-between">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
              Payslips ({run.payslips.length})
            </h2>
            <div className="flex items-center gap-2">
              <button
                onClick={() => {
                  // Download all payslips by opening each in new tab
                  for (const slip of run.payslips) {
                    window.open(`/api/payroll/payslip-pdf?id=${slip.id}`, '_blank');
