/**
 * Document Capture Detail Page
 * View extracted data, edit fields, take actions on a captured document.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  ScanLine, ArrowLeft, Loader2, AlertCircle, FileText,
  CheckCircle2, XCircle, Link2, Save, ChevronDown, ChevronUp,
} from 'lucide-react';
import { toast } from 'react-hot-toast';
import type { CapturedDocument, ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';
import { formatCurrency, formatDate } from '@/utils/formatters';

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    pending: 'bg-amber-500/20 text-amber-400',
    reviewed: 'bg-blue-500/20 text-blue-400',
    matched: 'bg-teal-500/20 text-teal-400',
    rejected: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

function ConfidenceBadge({ confidence }: { confidence: number }) {
  let color = 'text-red-400';
  let label = 'Low';
  if (confidence >= 0.7) { color = 'text-teal-400'; label = 'High'; }
  else if (confidence >= 0.4) { color = 'text-amber-400'; label = 'Medium'; }
  return (
    <span className={`text-xs font-medium ${color}`}>
      {label} ({Math.round(confidence * 100)}%)
    </span>
  );
}

export default function DocumentCaptureDetailPage() {
  const router = useRouter();
  const { docId } = router.query;

  const [doc, setDoc] = useState<CapturedDocument | null>(null);
  const [extracted, setExtracted] = useState<ExtractedDocument | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showRawText, setShowRawText] = useState(false);

  // Editable fields
  const [vendorName, setVendorName] = useState('');
  const [documentDate, setDocumentDate] = useState('');
  const [referenceNumber, setReferenceNumber] = useState('');
  const [totalAmount, setTotalAmount] = useState('');
  const [vatAmount, setVatAmount] = useState('');
  const [documentType, setDocumentType] = useState('');
  const [notes, setNotes] = useState('');

  // Bank TX match
  const [bankTxId, setBankTxId] = useState('');
  const [isMatching, setIsMatching] = useState(false);

  const loadDocument = useCallback(async () => {
    if (!docId) return;
    setIsLoading(true);
    setError('');

    try {
      const res = await fetch(`/api/accounting/document-capture?status=`);
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Failed to load');

      const found = (json.data || []).find((d: CapturedDocument) => d.id === docId);
      if (!found) throw new Error('Document not found');

      setDoc(found);

      const ext = found.extractedData as ExtractedDocument | null;
      setExtracted(ext);

      // Populate form
      setVendorName(found.vendorName || ext?.vendorName || '');
      setDocumentDate(found.documentDate || ext?.date || '');
      setReferenceNumber(found.referenceNumber || ext?.referenceNumber || '');
      setTotalAmount(found.totalAmount !== null ? String(found.totalAmount) : (ext?.totalAmount !== null ? String(ext?.totalAmount) : ''));
      setVatAmount(found.vatAmount !== null ? String(found.vatAmount) : (ext?.vatAmount !== null ? String(ext?.vatAmount) : ''));
      setDocumentType(found.documentType || ext?.documentType || 'unknown');
      setNotes(found.notes || '');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load document');
    } finally {
      setIsLoading(false);
    }
  }, [docId]);

  useEffect(() => { loadDocument(); }, [loadDocument]);

  async function handleConfirm() {
    if (!doc) return;
    setIsSaving(true);
    try {
      const res = await fetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: doc.id,
          action: 'confirm',
          data: {
            vendorName: vendorName || null,
            documentDate: documentDate || null,
            referenceNumber: referenceNumber || null,
            totalAmount: totalAmount ? parseFloat(totalAmount) : null,
            vatAmount: vatAmount ? parseFloat(vatAmount) : null,
            documentType: documentType || null,
            notes: notes || null,
          },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Confirm failed');
      toast.success('Document confirmed');
      loadDocument();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Confirm failed');
    } finally {
      setIsSaving(false);
    }
  }

  async function handleReject() {
    if (!doc) return;
    setIsSaving(true);
    try {
      const res = await fetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: doc.id,
          action: 'reject',
          data: { notes: notes || 'Rejected' },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Reject failed');
      toast.success('Document rejected');
      loadDocument();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Reject failed');
    } finally {
      setIsSaving(false);
    }
  }

  async function handleMatchBankTx() {
    if (!doc || !bankTxId.trim()) {
      toast.error('Enter a bank transaction ID');
      return;
    }
    setIsMatching(true);
    try {
      const res = await fetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: doc.id,
          action: 'match_bank_tx',
          data: { bankTxId: bankTxId.trim() },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Match failed');
      toast.success('Matched to bank transaction');
      setBankTxId('');
      loadDocument();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Match failed');
    } finally {
      setIsMatching(false);
    }
  }

  if (isLoading) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <Loader2 className="h-8 w-8 text-teal-500 animate-spin" />
        </div>
      </AppLayout>
    );
  }

  if (error || !doc) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex flex-col items-center justify-center gap-4">
          <AlertCircle className="h-8 w-8 text-red-400" />
          <p className="text-red-400 text-sm">{error || 'Document not found'}</p>
          <Link href="/accounting/document-capture" className="text-teal-500 hover:text-teal-400 text-sm">
            Back to Document Capture
          </Link>
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link
                href="/accounting/document-capture"
                className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
              >
                <ArrowLeft className="h-5 w-5 text-[var(--ff-text-secondary)]" />
              </Link>
              <div className="p-2 rounded-lg bg-teal-500/10">
                <ScanLine className="h-5 w-5 text-teal-500" />
              </div>
              <div>
                <div className="flex items-center gap-3">
                  <h1 className="text-xl font-bold text-[var(--ff-text-primary)]">
                    {doc.fileName}
                  </h1>
                  <StatusBadge status={doc.status} />
                </div>
                <p className="text-xs text-[var(--ff-text-tertiary)]">
                  Uploaded {formatDate(doc.createdAt)}
                  {doc.fileSize ? ` - ${(doc.fileSize / 1024).toFixed(1)} KB` : ''}
                </p>
              </div>
            </div>
            {extracted && <ConfidenceBadge confidence={extracted.confidence} />}
          </div>
        </div>

        <div className="p-6 space-y-6 max-w-4xl mx-auto">
          {/* Warnings */}
          {extracted && extracted.warnings.length > 0 && (
            <div className="bg-amber-500/5 border border-amber-500/20 rounded-lg p-4">
              {extracted.warnings.map((w, i) => (
                <div key={i} className="flex items-start gap-2 text-sm text-amber-400">
                  <AlertCircle className="h-4 w-4 mt-0.5 shrink-0" />
                  <span>{w}</span>
                </div>
              ))}
            </div>
          )}

          {/* Edit Form */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)]">
            <div className="px-6 py-4 border-b border-[var(--ff-border-light)]">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Document Details</h2>
              <p className="text-xs text-[var(--ff-text-tertiary)]">Review and correct the extracted fields</p>
            </div>
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Document Type</label>
                <select
                  value={documentType}
                  onChange={(e) => setDocumentType(e.target.value)}
                  className="ff-select w-full text-sm"
                  disabled={doc.status === 'rejected'}
                >
                  <option value="invoice">Invoice</option>
                  <option value="credit_note">Credit Note</option>
                  <option value="receipt">Receipt</option>
                  <option value="statement">Statement</option>
                  <option value="unknown">Unknown</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Vendor Name</label>
                <input
                  type="text"
                  value={vendorName}
                  onChange={(e) => setVendorName(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="Enter vendor name"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Date</label>
                <input
                  type="date"
                  value={documentDate}
                  onChange={(e) => setDocumentDate(e.target.value)}
                  className="ff-input w-full text-sm"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Reference / Invoice No.</label>
                <input
                  type="text"
                  value={referenceNumber}
                  onChange={(e) => setReferenceNumber(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="e.g. INV-001"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Total Amount (ZAR)</label>
                <input
                  type="number"
                  step="0.01"
                  value={totalAmount}
                  onChange={(e) => setTotalAmount(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="0.00"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">VAT Amount (ZAR)</label>
                <input
                  type="number"
                  step="0.01"
                  value={vatAmount}
                  onChange={(e) => setVatAmount(e.target.value)}
                  className="ff-input w-full text-sm"
                  placeholder="0.00"
                  disabled={doc.status === 'rejected'}
                />
              </div>
              {extracted?.vendorVatNumber && (
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Vendor VAT Number</label>
                  <input
                    type="text"
                    value={extracted.vendorVatNumber}
                    className="ff-input w-full text-sm bg-[var(--ff-bg-tertiary)]"
                    readOnly
                  />
                </div>
              )}
              {extracted?.subtotal !== null && extracted?.subtotal !== undefined && (
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Subtotal (extracted)</label>
                  <input
                    type="text"
                    value={formatCurrency(extracted.subtotal)}
                    className="ff-input w-full text-sm bg-[var(--ff-bg-tertiary)]"
                    readOnly
                  />
                </div>
              )}
              <div className="md:col-span-2">
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Notes</label>
                <textarea
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  className="ff-input w-full text-sm"
                  rows={2}
                  placeholder="Optional notes..."
                  disabled={doc.status === 'rejected'}
                />
              </div>
            </div>

            {/* Line Items */}
            {extracted && extracted.lineItems.length > 0 && (
              <div className="px-6 pb-4">
                <h3 className="text-xs font-medium text-[var(--ff-text-secondary)] mb-2">Extracted Line Items</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                        <th className="px-3 py-2 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Description</th>
                        <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Qty</th>
                        <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Unit Price</th>
                        <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Total</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--ff-border-light)]">
                      {extracted.lineItems.map((item, i) => (
                        <tr key={i}>
                          <td className="px-3 py-2 text-[var(--ff-text-primary)]">{item.description}</td>
                          <td className="px-3 py-2 text-right text-[var(--ff-text-secondary)]">{item.quantity ?? '-'}</td>
                          <td className="px-3 py-2 text-right font-mono text-[var(--ff-text-secondary)]">{item.unitPrice !== null ? formatCurrency(item.unitPrice) : '-'}</td>
                          <td className="px-3 py-2 text-right font-mono text-[var(--ff-text-primary)]">{item.total !== null ? formatCurrency(item.total) : '-'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Action Buttons */}
            {doc.status !== 'rejected' && (
              <div className="px-6 py-4 border-t border-[var(--ff-border-light)] flex items-center gap-3 flex-wrap">
                <button
                  onClick={handleConfirm}
                  disabled={isSaving}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium disabled:opacity-50"
                >
                  {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}
                  {doc.status === 'reviewed' ? 'Update' : 'Confirm & Save'}
                </button>
                <button
                  onClick={handleReject}
                  disabled={isSaving}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-red-600/20 text-red-400 rounded-lg hover:bg-red-600/30 transition-colors text-sm font-medium disabled:opacity-50"
                >
                  <XCircle className="h-4 w-4" />
                  Reject
                </button>
              </div>
            )}
          </div>

          {/* Match to Bank Transaction */}
          {doc.status !== 'rejected' && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)]">
              <div className="px-6 py-4 border-b border-[var(--ff-border-light)]">
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Match to Bank Transaction</h2>
                <p className="text-xs text-[var(--ff-text-tertiary)]">Link this document to a bank transaction for reconciliation</p>
              </div>
              <div className="p-6">
                {doc.matchedBankTxId ? (
                  <div className="flex items-center gap-2 text-sm text-teal-400">
                    <Link2 className="h-4 w-4" />
                    Matched to bank transaction: <span className="font-mono text-xs">{doc.matchedBankTxId}</span>
                  </div>
                ) : (
                  <div className="flex items-center gap-3">
                    <input
                      type="text"
                      value={bankTxId}
                      onChange={(e) => setBankTxId(e.target.value)}
                      className="ff-input flex-1 text-sm"
                      placeholder="Enter bank transaction ID..."
                    />
                    <button
                      onClick={handleMatchBankTx}
                      disabled={isMatching || !bankTxId.trim()}
                      className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium disabled:opacity-50"
                    >
                      {isMatching ? <Loader2 className="h-4 w-4 animate-spin" /> : <Link2 className="h-4 w-4" />}
                      Match
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Raw Text Preview */}
          {extracted?.rawText && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)]">
              <button
                onClick={() => setShowRawText(!showRawText)}
                className="w-full px-6 py-4 flex items-center justify-between text-left"
              >
                <div>
                  <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Raw Extracted Text</h2>
                  <p className="text-xs text-[var(--ff-text-tertiary)]">The full text extracted from the PDF</p>
                </div>
                {showRawText ? (
                  <ChevronUp className="h-5 w-5 text-[var(--ff-text-tertiary)]" />
                ) : (
                  <ChevronDown className="h-5 w-5 text-[var(--ff-text-tertiary)]" />
                )}
              </button>
              {showRawText && (
                <div className="px-6 pb-6">
                  <pre className="bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg p-4 text-xs text-[var(--ff-text-secondary)] whitespace-pre-wrap font-mono max-h-96 overflow-y-auto">
                    {extracted.rawText}
                  </pre>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Document Capture Hub
 * Upload PDFs, extract invoice/receipt data via OCR, review and act on results.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  ScanLine, Upload, Loader2, AlertCircle, FileText, CheckCircle2,
  XCircle, Eye, RefreshCw, ChevronRight,
} from 'lucide-react';
import { toast } from 'react-hot-toast';
import type { CapturedDocument, ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';
import { formatCurrency, formatDate } from '@/utils/formatters';

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    pending: 'bg-amber-500/20 text-amber-400',
    reviewed: 'bg-blue-500/20 text-blue-400',
    matched: 'bg-teal-500/20 text-teal-400',
    rejected: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

function ConfidenceBadge({ confidence }: { confidence: number }) {
  let color = 'text-red-400';
  let label = 'Low';
  if (confidence >= 0.7) { color = 'text-teal-400'; label = 'High'; }
  else if (confidence >= 0.4) { color = 'text-amber-400'; label = 'Medium'; }
  return (
    <span className={`text-xs font-medium ${color}`}>
      {label} ({Math.round(confidence * 100)}%)
    </span>
  );
}

export default function DocumentCapturePage() {
  const [documents, setDocuments] = useState<CapturedDocument[]>([]);
  const [total, setTotal] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [statusFilter, setStatusFilter] = useState('');

  // Upload state
  const [isUploading, setIsUploading] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [uploadResult, setUploadResult] = useState<{ document: CapturedDocument; extracted: ExtractedDocument } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Review form state (after upload)
  const [reviewVendor, setReviewVendor] = useState('');
  const [reviewDate, setReviewDate] = useState('');
  const [reviewRef, setReviewRef] = useState('');
  const [reviewTotal, setReviewTotal] = useState('');
  const [reviewVat, setReviewVat] = useState('');
  const [reviewDocType, setReviewDocType] = useState('');
  const [reviewNotes, setReviewNotes] = useState('');

  const loadDocuments = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (statusFilter) params.set('status', statusFilter);
      const res = await fetch(`/api/accounting/document-capture?${params}`);
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Failed to load');
      setDocuments(json.data || []);
      setTotal(json.pagination?.total || 0);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load documents');
    } finally {
      setIsLoading(false);
    }
  }, [statusFilter]);

  useEffect(() => { loadDocuments(); }, [loadDocuments]);

  // Populate review form when upload completes
  useEffect(() => {
    if (uploadResult) {
      const ex = uploadResult.extracted;
      setReviewVendor(ex.vendorName || '');
      setReviewDate(ex.date || '');
      setReviewRef(ex.referenceNumber || '');
      setReviewTotal(ex.totalAmount !== null ? String(ex.totalAmount) : '');
      setReviewVat(ex.vatAmount !== null ? String(ex.vatAmount) : '');
      setReviewDocType(ex.documentType || 'unknown');
      setReviewNotes('');
    }
  }, [uploadResult]);

  async function handleUpload(file: File) {
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      toast.error('Only PDF files are supported');
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      toast.error('File too large. Maximum size is 10MB.');
      return;
    }

    setIsUploading(true);
    setUploadResult(null);
    setError('');

    try {
      const formData = new FormData();
      formData.append('file', file);

      const res = await fetch('/api/accounting/document-capture', {
        method: 'POST',
        body: formData,
      });

      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Upload failed');

      setUploadResult(json.data);
      toast.success('Document uploaded and processed');
      loadDocuments();
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Upload failed';
      toast.error(msg);
      setError(msg);
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  }

  function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    if (file) handleUpload(file);
  }

  function handleDragOver(e: React.DragEvent) {
    e.preventDefault();
    setIsDragging(true);
  }

  function handleDragLeave(e: React.DragEvent) {
    e.preventDefault();
    setIsDragging(false);
  }

  async function handleConfirm() {
    if (!uploadResult) return;
    try {
      const res = await fetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: uploadResult.document.id,
          action: 'confirm',
          data: {
            vendorName: reviewVendor || null,
            documentDate: reviewDate || null,
            referenceNumber: reviewRef || null,
            totalAmount: reviewTotal ? parseFloat(reviewTotal) : null,
            vatAmount: reviewVat ? parseFloat(reviewVat) : null,
            documentType: reviewDocType || null,
            notes: reviewNotes || null,
          },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Confirm failed');
      toast.success('Document confirmed');
      setUploadResult(null);
      loadDocuments();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Confirm failed');
    }
  }

  async function handleReject() {
    if (!uploadResult) return;
    try {
      const res = await fetch('/api/accounting/document-capture-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: uploadResult.document.id,
          action: 'reject',
          data: { notes: reviewNotes || 'Rejected during review' },
        }),
      });
      const json = await res.json();
      if (!json.success) throw new Error(json.error?.message || 'Reject failed');
      toast.success('Document rejected');
      setUploadResult(null);
      loadDocuments();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Reject failed');
    }
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <ScanLine className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Document Capture</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Upload invoices and receipts for automated data extraction
                </p>
              </div>
            </div>
            <button
              onClick={() => loadDocuments()}
              className="inline-flex items-center gap-2 px-3 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              <RefreshCw className="h-4 w-4" />
              Refresh
            </button>
          </div>
        </div>

        <div className="p-6 space-y-6">
          {/* Upload Zone */}
          <div
            onDrop={handleDrop}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            className={`relative border-2 border-dashed rounded-xl p-8 text-center transition-all cursor-pointer ${
              isDragging
                ? 'border-teal-500 bg-teal-500/5'
                : 'border-[var(--ff-border-light)] hover:border-teal-500/50 hover:bg-[var(--ff-bg-secondary)]'
            }`}
            onClick={() => fileInputRef.current?.click()}
          >
            <input
              ref={fileInputRef}
              type="file"
              accept=".pdf,application/pdf"
              className="hidden"
              onChange={(e) => {
                const file = e.target.files?.[0];
                if (file) handleUpload(file);
              }}
            />
            {isUploading ? (
              <div className="flex flex-col items-center gap-3">
                <Loader2 className="h-10 w-10 text-teal-500 animate-spin" />
                <p className="text-sm text-[var(--ff-text-secondary)]">Processing document...</p>
              </div>
            ) : (
              <div className="flex flex-col items-center gap-3">
                <Upload className="h-10 w-10 text-[var(--ff-text-tertiary)]" />
                <div>
                  <p className="text-sm font-medium text-[var(--ff-text-primary)]">
                    Drop a PDF here or click to browse
                  </p>
                  <p className="text-xs text-[var(--ff-text-tertiary)] mt-1">
                    Invoices, receipts, credit notes — PDF up to 10MB
                  </p>
                </div>
              </div>
            )}
          </div>

          {/* Extraction Review Panel */}
          {uploadResult && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)] overflow-hidden">
              <div className="px-6 py-4 border-b border-[var(--ff-border-light)] flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <FileText className="h-5 w-5 text-teal-500" />
                  <div>
                    <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                      Extraction Results
                    </h2>
                    <p className="text-xs text-[var(--ff-text-secondary)]">
                      {uploadResult.document.fileName}
                    </p>
                  </div>
                </div>
                <ConfidenceBadge confidence={uploadResult.extracted.confidence} />
              </div>

              {/* Warnings */}
              {uploadResult.extracted.warnings.length > 0 && (
                <div className="px-6 py-3 bg-amber-500/5 border-b border-[var(--ff-border-light)]">
                  {uploadResult.extracted.warnings.map((w, i) => (
                    <div key={i} className="flex items-start gap-2 text-xs text-amber-400">
                      <AlertCircle className="h-3.5 w-3.5 mt-0.5 shrink-0" />
                      <span>{w}</span>
                    </div>
                  ))}
                </div>
              )}

              <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Document Type</label>
                  <select
                    value={reviewDocType}
                    onChange={(e) => setReviewDocType(e.target.value)}
                    className="ff-select w-full text-sm"
                  >
                    <option value="invoice">Invoice</option>
                    <option value="credit_note">Credit Note</option>
                    <option value="receipt">Receipt</option>
                    <option value="statement">Statement</option>
                    <option value="unknown">Unknown</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Vendor Name</label>
                  <input
                    type="text"
                    value={reviewVendor}
                    onChange={(e) => setReviewVendor(e.target.value)}
                    className="ff-input w-full text-sm"
                    placeholder="Enter vendor name"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Date</label>
                  <input
                    type="date"
                    value={reviewDate}
                    onChange={(e) => setReviewDate(e.target.value)}
                    className="ff-input w-full text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Reference / Invoice No.</label>
                  <input
                    type="text"
                    value={reviewRef}
                    onChange={(e) => setReviewRef(e.target.value)}
                    className="ff-input w-full text-sm"
                    placeholder="e.g. INV-001"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Total Amount (ZAR)</label>
                  <input
                    type="number"
                    step="0.01"
                    value={reviewTotal}
                    onChange={(e) => setReviewTotal(e.target.value)}
                    className="ff-input w-full text-sm"
                    placeholder="0.00"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">VAT Amount (ZAR)</label>
                  <input
                    type="number"
                    step="0.01"
                    value={reviewVat}
                    onChange={(e) => setReviewVat(e.target.value)}
                    className="ff-input w-full text-sm"
                    placeholder="0.00"
                  />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Notes</label>
                  <textarea
                    value={reviewNotes}
                    onChange={(e) => setReviewNotes(e.target.value)}
                    className="ff-input w-full text-sm"
                    rows={2}
                    placeholder="Optional notes..."
                  />
                </div>
              </div>

              {/* Line Items (read-only display) */}
              {uploadResult.extracted.lineItems.length > 0 && (
                <div className="px-6 pb-4">
                  <h3 className="text-xs font-medium text-[var(--ff-text-secondary)] mb-2">Extracted Line Items</h3>
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                          <th className="px-3 py-2 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Description</th>
                          <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Qty</th>
                          <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Unit Price</th>
                          <th className="px-3 py-2 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Total</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-[var(--ff-border-light)]">
                        {uploadResult.extracted.lineItems.map((item, i) => (
                          <tr key={i}>
                            <td className="px-3 py-2 text-[var(--ff-text-primary)]">{item.description}</td>
                            <td className="px-3 py-2 text-right text-[var(--ff-text-secondary)]">{item.quantity ?? '-'}</td>
                            <td className="px-3 py-2 text-right font-mono text-[var(--ff-text-secondary)]">{item.unitPrice !== null ? formatCurrency(item.unitPrice) : '-'}</td>
                            <td className="px-3 py-2 text-right font-mono text-[var(--ff-text-primary)]">{item.total !== null ? formatCurrency(item.total) : '-'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              {/* Action Buttons */}
              <div className="px-6 py-4 border-t border-[var(--ff-border-light)] flex items-center gap-3 flex-wrap">
                <button
                  onClick={handleConfirm}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium"
                >
                  <CheckCircle2 className="h-4 w-4" />
                  Confirm & Save
                </button>
                <button
                  onClick={handleReject}
                  className="inline-flex items-center gap-2 px-4 py-2 bg-red-600/20 text-red-400 rounded-lg hover:bg-red-600/30 transition-colors text-sm font-medium"
                >
                  <XCircle className="h-4 w-4" />
                  Reject
                </button>
                <button
                  onClick={() => setUploadResult(null)}
                  className="inline-flex items-center gap-2 px-4 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors text-sm"
                >
                  Save & Review Later
                </button>
              </div>
            </div>
          )}

          {/* Document List */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-xl border border-[var(--ff-border-light)] overflow-hidden">
            <div className="px-6 py-4 border-b border-[var(--ff-border-light)] flex items-center justify-between">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                Captured Documents
                {total > 0 && <span className="text-sm font-normal text-[var(--ff-text-tertiary)] ml-2">({total})</span>}
              </h2>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="ff-select text-sm"
              >
                <option value="">All Statuses</option>
                <option value="pending">Pending</option>
                <option value="reviewed">Reviewed</option>
                <option value="matched">Matched</option>
                <option value="rejected">Rejected</option>
              </select>
            </div>

            {isLoading ? (
              <div className="flex items-center justify-center py-12">
                <Loader2 className="h-6 w-6 text-teal-500 animate-spin" />
              </div>
            ) : error ? (
              <div className="flex items-center gap-2 justify-center py-12 text-red-400 text-sm">
                <AlertCircle className="h-4 w-4" />
                {error}
              </div>
            ) : documents.length === 0 ? (
              <div className="text-center py-12 text-[var(--ff-text-tertiary)] text-sm">
                No documents captured yet. Upload a PDF above to get started.
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">File</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Type</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Vendor</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Date</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Reference</th>
                      <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)]">Total</th>
                      <th className="px-4 py-3 text-center text-xs font-medium text-[var(--ff-text-secondary)]">Status</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)]">Uploaded</th>
                      <th className="px-4 py-3"></th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--ff-border-light)]">
                    {documents.map((doc) => (
                      <tr key={doc.id} className="hover:bg-[var(--ff-bg-tertiary)] transition-colors">
                        <td className="px-4 py-3">
                          <div className="flex items-center gap-2">
                            <FileText className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                            <span className="text-[var(--ff-text-primary)] font-medium truncate max-w-[200px]">
                              {doc.fileName}
                            </span>
                          </div>
                        </td>
                        <td className="px-4 py-3 text-[var(--ff-text-secondary)] capitalize">{doc.documentType || '-'}</td>
                        <td className="px-4 py-3 text-[var(--ff-text-primary)]">{doc.vendorName || '-'}</td>
                        <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{formatDate(doc.documentDate)}</td>
                        <td className="px-4 py-3 text-[var(--ff-text-secondary)] font-mono text-xs">{doc.referenceNumber || '-'}</td>
                        <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">{formatCurrency(doc.totalAmount)}</td>
                        <td className="px-4 py-3 text-center"><StatusBadge status={doc.status} /></td>
                        <td className="px-4 py-3 text-[var(--ff-text-tertiary)] text-xs">{formatDate(doc.createdAt)}</td>
                        <td className="px-4 py-3">
                          <Link
                            href={`/accounting/document-capture/${doc.id}`}
                            className="inline-flex items-center gap-1 text-teal-500 hover:text-teal-400 text-xs"
                          >
                            <Eye className="h-3.5 w-3.5" />
                            View
                            <ChevronRight className="h-3 w-3" />
                          </Link>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Bank Transactions — Sage "Process Bank" equivalent
 * Type: Account / Supplier / Customer — Selection changes accordingly
 * Full toolbar: Mark Reviewed, Delete, Batch Edit, Import, Export, Search
 */

import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import dynamic from 'next/dynamic';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  BankTxTable, type AllocType, type VatCode, type BankTx, type SelectOption, type RowSelection,
} from '@/components/accounting/BankTxTable';
import { extractPattern } from '@/components/accounting/CreateRuleModal';
import { StatementBalanceWidget } from '@/components/accounting/StatementBalanceWidget';

// Lazy-load modals — only loaded when opened
const SplitTransactionModal = dynamic(() => import('@/components/accounting/SplitTransactionModal').then(m => ({ default: m.SplitTransactionModal })), { ssr: false });
const ExcludeReasonModal = dynamic(() => import('@/components/accounting/ExcludeReasonModal').then(m => ({ default: m.ExcludeReasonModal })), { ssr: false });
const FindMatchModal = dynamic(() => import('@/components/accounting/FindMatchModal').then(m => ({ default: m.FindMatchModal })), { ssr: false });
const BankTxAttachmentsModal = dynamic(() => import('@/components/accounting/BankTxAttachmentsModal').then(m => ({ default: m.BankTxAttachmentsModal })), { ssr: false });
const CreateRuleModal = dynamic(() => import('@/components/accounting/CreateRuleModal').then(m => ({ default: m.CreateRuleModal })), { ssr: false });
const CreateEntityModal = dynamic(() => import('@/components/accounting/CreateEntityModal').then(m => ({ default: m.CreateEntityModal })), { ssr: false });
import {
  Loader2, AlertCircle, RefreshCw, CheckCheck, Upload, Download, Search, Trash2, Layers, Zap, Plus, FileText,
} from 'lucide-react';
import { toast } from 'react-hot-toast';
import Link from 'next/link';
import { formatCurrency as fmtCurrency } from '@/utils/formatters';

interface BankAcct {
  id: string;
  accountCode: string;
  accountName: string;
  bankAccountNumber?: string | null;
  balance: number;
  reconciledBalance: number;
  unreconciledBalance: number;
  unreconciledCount: number;
}
type Tab = 'new' | 'reviewed' | 'excluded';
const PAGE_SIZE = 25;

/** Maps UI tabs to bank_transactions.status values */
function tabToStatus(tab: Tab): string {
  if (tab === 'new') return 'imported';
  if (tab === 'excluded') return 'excluded';
  return 'matched';
}

export default function BankTransactionsPage() {
  const [transactions, setTransactions] = useState<BankTx[]>([]);
  const [glAccounts, setGlAccounts] = useState<SelectOption[]>([]);
  const [suppliers, setSuppliers] = useState<SelectOption[]>([]);
  const [customers, setCustomers] = useState<SelectOption[]>([]);
  const [cc1Options, setCc1Options] = useState<SelectOption[]>([]);
  const [cc2Options, setCc2Options] = useState<SelectOption[]>([]);
  const [buOptions, setBuOptions] = useState<SelectOption[]>([]);
  const [bankAccounts, setBankAccounts] = useState<BankAcct[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  const [selectedBank, setSelectedBank] = useState('');
  const [tab, setTab] = useState<Tab>('new');
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  /** Minimum transaction amount filter (Rand value, empty = no lower bound) */
  const [fromAmount, setFromAmount] = useState('');
  /** Maximum transaction amount filter (Rand value, empty = no upper bound) */
  const [toAmount, setToAmount] = useState('');
  const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const amountDebounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [rowSelections, setRowSelections] = useState<Record<string, RowSelection>>({});
  const [showBatchEdit, setShowBatchEdit] = useState(false);
  const [batchType, setBatchType] = useState<AllocType>('account');
  const [batchSearch, setBatchSearch] = useState('');

  const [splitTxId, setSplitTxId] = useState<string | null>(null);
  /** ID of transaction awaiting an exclusion reason — shows ExcludeReasonModal when set */
  const [excludingTxId, setExcludingTxId] = useState<string | null>(null);
  const [findMatchTxId, setFindMatchTxId] = useState<string | null>(null);
  const [attachmentsTxId, setAttachmentsTxId] = useState<string | null>(null);
  const [createRuleTx, setCreateRuleTx] = useState<BankTx | null>(null);
  const [rulePrompt, setRulePrompt] = useState<{ tx: BankTx; matchCount: number } | null>(null);
  const [createEntityTxId, setCreateEntityTxId] = useState<string | null>(null);
  const [createEntityType, setCreateEntityType] = useState<AllocType | null>(null);

  // Load reference data — all requests fire in parallel via Promise.all
  useEffect(() => {
    Promise.all([
      fetch('/api/accounting/bank-accounts').then(r => r.json()),
      fetch('/api/accounting/chart-of-accounts').then(r => r.json()),
      fetch('/api/suppliers?status=active').then(r => r.json()),
      fetch('/api/clients').then(r => r.json()),
      fetch('/api/accounting/cost-centres?cc_type=cc1&active=true').then(r => r.json()),
      fetch('/api/accounting/cost-centres?cc_type=cc2&active=true').then(r => r.json()),
      fetch('/api/departments?isActive=true').then(r => r.json()),
    ]).then(([bankJson, coaJson, suppJson, clientJson, cc1Json, cc2Json, deptJson]) => {
      const bankList = Array.isArray(bankJson.data || bankJson) ? (bankJson.data || bankJson) : [];
      setBankAccounts(bankList);
      if (bankList.length > 0) setSelectedBank(prev => prev || bankList[0].id);

      const coaList = Array.isArray(coaJson.data || coaJson) ? (coaJson.data || coaJson) : [];
      setGlAccounts(coaList
        .filter((a: SelectOption & { accountSubtype?: string }) => a.accountSubtype !== 'bank')
        .map((a: SelectOption & { accountCode?: string; accountName?: string; defaultVatCode?: string }) => ({
          id: a.id, code: a.accountCode || a.code, name: a.accountName || a.name,
          defaultVatCode: a.defaultVatCode,
        }))
      );

      const suppList = Array.isArray(suppJson.data) ? suppJson.data : [];
      setSuppliers(suppList.map((s: { id: number | string; name: string; code?: string }) => ({
        id: String(s.id), name: s.name, code: s.code,
      })));

      const clientList = Array.isArray(clientJson.data) ? clientJson.data : [];
      setCustomers(clientList.map((c: { id: string; name?: string; company_name?: string; companyName?: string }) => ({
        id: c.id, name: c.company_name || c.companyName || c.name || '',
      })));

      const cc1List = Array.isArray(cc1Json.data?.items) ? cc1Json.data.items : [];
      setCc1Options(cc1List.map((c: { id: string; code: string; name: string }) => ({ id: c.id, code: c.code, name: c.name })));

      const cc2List = Array.isArray(cc2Json.data?.items) ? cc2Json.data.items : [];
      setCc2Options(cc2List.map((c: { id: string; code: string; name: string }) => ({ id: c.id, code: c.code, name: c.name })));

      const deptList = Array.isArray(deptJson.data || deptJson) ? (deptJson.data || deptJson) : [];
      setBuOptions(deptList.filter((d: { is_active?: boolean; isActive?: boolean }) => d.is_active !== false && d.isActive !== false)
        .map((d: { id: string; name: string; code?: string }) => ({ id: d.id, name: d.name, code: d.code })));
    }).catch(() => { /* reference data load failure — non-critical, UI handles empty lists */ });
  }, []);

  // Debounce search input — 500ms delay before firing server request
  useEffect(() => {
    if (debounceTimer.current) clearTimeout(debounceTimer.current);
    debounceTimer.current = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setPage(1);
    }, 500);
    return () => { if (debounceTimer.current) clearTimeout(debounceTimer.current); };
  }, [searchTerm]);

  // Load transactions — server-side filtering for search, dates, amount range, status
  const loadTransactions = useCallback(async () => {
    if (!selectedBank) return;
    setIsLoading(true);
    setError('');
    try {
      const status = tabToStatus(tab);
      const offset = (page - 1) * PAGE_SIZE;
      const params = new URLSearchParams({
        bank_account_id: selectedBank, status, limit: String(PAGE_SIZE), offset: String(offset),
      });
      if (fromDate) params.set('from_date', fromDate);
      if (toDate) params.set('to_date', toDate);
      if (fromAmount) params.set('from_amount', fromAmount);
      if (toAmount) params.set('to_amount', toAmount);
      if (debouncedSearch) params.set('search', debouncedSearch);
      const res = await fetch(`/api/accounting/bank-transactions?${params}`);
      const json = await res.json();
      const data = json.data || json;
      setTransactions(data.transactions || []);
      setTotal(data.total || 0);
    } catch {
      setError('Failed to load transactions');
    } finally {
      setIsLoading(false);
    }
  }, [selectedBank, tab, page, fromDate, toDate, fromAmount, toAmount, debouncedSearch]);

  useEffect(() => { loadTransactions(); }, [loadTransactions]);

  // Seed rowSelections from suggestion fields on newly-loaded transactions
  useEffect(() => {
    if (transactions.length === 0) return;
    const initialSelections: Record<string, RowSelection> = {};
    for (const tx of transactions) {
      // Skip only if user has already picked a specific entity — an empty selection (type set, no entity)
      // should be overridden by fresh DB suggestions (e.g. after Apply Rules runs)
      if (rowSelections[tx.id]?.entityId) continue;
      // VAT only applies to GL account allocations; supplier/customer VAT is handled on their own invoices
      const dimFields = { cc1Id: tx.cc1Id, cc2Id: tx.cc2Id, buId: tx.buId };
      if (tx.suggestedSupplierId) {
        initialSelections[tx.id] = {
          type: 'supplier' as AllocType,
          entityId: tx.suggestedSupplierId,
          label: tx.suggestedSupplierName || tx.suggestedCategory || '',
          vatCode: 'none', ...dimFields,
        };
      } else if (tx.suggestedClientId) {
        initialSelections[tx.id] = {
          type: 'customer' as AllocType,
          entityId: tx.suggestedClientId,
          label: tx.suggestedClientName || tx.suggestedCategory || '',
          vatCode: 'none', ...dimFields,
        };
      } else if (tx.suggestedGlAccountId) {
        initialSelections[tx.id] = {
          type: 'account' as AllocType,
          entityId: tx.suggestedGlAccountId,
          label: tx.suggestedGlAccountCode
            ? `${tx.suggestedGlAccountCode} ${tx.suggestedGlAccountName || ''}`
            : tx.suggestedGlAccountName || tx.suggestedCategory || '',
          vatCode: (tx.suggestedVatCode || 'none') as VatCode, ...dimFields,
        };
      }
    }
    if (Object.keys(initialSelections).length > 0) {
      // Merge: DB suggestions fill in empty slots; existing selections with an entityId win
      setRowSelections(prev => {
        const merged = { ...prev };
        for (const [id, sel] of Object.entries(initialSelections)) {
          if (!merged[id]?.entityId) merged[id] = sel;
        }
        return merged;
      });
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [transactions]);

  useEffect(() => {
    setPage(1);
    setSelectedIds(new Set());
    setRowSelections({});
  }, [selectedBank, tab]);

  // API helpers
  const callAction = async (body: Record<string, string>) => {
    const res = await fetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
      body: JSON.stringify(body),
    });
    const json = await res.json();
    if (!res.ok || json.success === false) {
      const msg = json.error?.message || json.message || (typeof json.error === 'string' ? json.error : 'Action failed');
      throw new Error(msg);
    }
    return json;
  };

  // Fire-and-forget: persist dropdown selection to DB so it survives page refresh
  const saveSelection = (txId: string, type: AllocType, entityId: string) => {
    fetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
      body: JSON.stringify({ action: 'save_selection', bankTransactionId: txId, selectionType: type, selectionEntityId: entityId || null }),
    }).catch(() => { /* fire-and-forget: selection persist failure is non-critical, selection still shown in UI */ });
  };

  // Fire-and-forget: persist CC1/CC2/BU dimension changes
  const saveDimensions = (txId: string, cc1Id: string, cc2Id: string, buId: string) => {
    fetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
      body: JSON.stringify({ action: 'save_dimensions', bankTransactionId: txId, cc1Id: cc1Id || null, cc2Id: cc2Id || null, buId: buId || null }),
    }).catch(() => { /* fire-and-forget: dimension persist failure is non-critical, dimensions still shown in UI */ });
  };

  const handleAccept = async (txId: string) => {
    const sel = rowSelections[txId];
    if (!sel?.entityId) { toast.error('Select an account/supplier/customer first'); return; }
    const tx = transactions.find(t => t.id === txId);
    try {
      const body: Record<string, string> = {
        action: 'allocate', bankTransactionId: txId, allocationType: sel.type,
        vatCode: sel.vatCode || 'none',
      };
      if (sel.type === 'account') body.contraAccountId = sel.entityId;
      else body.entityId = sel.entityId;
      if (sel.cc1Id) body.cc1Id = sel.cc1Id;
      if (sel.cc2Id) body.cc2Id = sel.cc2Id;
      if (sel.buId) body.buId = sel.buId;
      await callAction(body);
      toast.success('Transaction allocated');
      loadTransactions();
      // Learn from this allocation for smart categorization (fire-and-forget)
      if (sel.type === 'account' && sel.entityId) {
        fetch('/api/accounting/smart-categorize', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
          body: JSON.stringify({ action: 'learn', txId, glAccountId: sel.entityId, category: sel.label, vatCode: sel.vatCode }),
        }).catch(() => { /* fire-and-forget: smart-categorize learn failure is non-critical */ });
      }
      // After allocation, check if there are other similar unprocessed transactions
      // to suggest creating a categorisation rule
      if (tx?.description && selectedBank) {
        const pattern = extractPattern(tx.description);
        if (pattern.trim().length >= 3) {
          try {
            const params = new URLSearchParams({ pattern, matchType: 'contains', bankAccountId: selectedBank });
            const res = await fetch(`/api/accounting/bank-rules-preview?${params}`);
            const json = await res.json();
            const matchCount = json.data?.matchCount ?? 0;
            if (matchCount > 0) setRulePrompt({ tx, matchCount });
          } catch { /* non-critical — ignore preview errors */ }
        }
      }
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed'); }
  };

  /** Opens the ExcludeReasonModal — actual API call happens in handleExcludeConfirm */
  const handleExclude = (txId: string) => {
    setExcludingTxId(txId);
  };

  /** Called by ExcludeReasonModal on confirm — posts to API with reason then reloads */
  const handleExcludeConfirm = async (reason: string) => {
    if (!excludingTxId) return;
    const txId = excludingTxId;
    setExcludingTxId(null);
    try {
      await callAction({ action: 'exclude', bankTransactionId: txId, excludeReason: reason });
      toast.success('Transaction excluded');
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed to exclude'); }
  };

  const handleUnmatch = async (txId: string) => {
    try {
      await callAction({ action: 'unmatch', bankTransactionId: txId });
      toast.success('Allocation undone');
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed'); }
  };

  const handleSplit = (txId: string) => {
    setSplitTxId(txId);
  };

  /**
   * Save notes/memo for a single bank transaction.
   * Updates local state optimistically so the cell does not flicker.
   */
  const handleUpdateNotes = async (txId: string, notes: string) => {
    // Optimistic local update — keep UI in sync without a reload
    setTransactions(prev =>
      prev.map(tx => tx.id === txId ? { ...tx, notes: notes || undefined } : tx)
    );
    try {
      const res = await fetch('/api/accounting/bank-transactions-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ action: 'update_notes', bankTransactionId: txId, notes }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) throw new Error(json.message || 'Failed to save note');
    } catch (e) {
      toast.error(e instanceof Error ? e.message : 'Failed to save note');
      // Revert optimistic update on error
      loadTransactions();
    }
  };

  const handleBatchAccept = async () => {
    const toAccept = Array.from(selectedIds).filter(id => rowSelections[id]?.entityId);
    if (toAccept.length === 0) { toast.error('Select transactions with accounts assigned'); return; }
    let ok = 0, fail = 0;
    for (const txId of toAccept) {
      try {
        const sel = rowSelections[txId];
        if (!sel) continue;
        const body: Record<string, string> = {
          action: 'allocate', bankTransactionId: txId, allocationType: sel.type,
          vatCode: sel.vatCode || 'none',
        };
        if (sel.type === 'account') body.contraAccountId = sel.entityId;
        else body.entityId = sel.entityId;
        if (sel.cc1Id) body.cc1Id = sel.cc1Id;
        if (sel.cc2Id) body.cc2Id = sel.cc2Id;
        if (sel.buId) body.buId = sel.buId;
        await callAction(body);
        ok++;
      } catch { fail++; }
    }
    toast.success(`${ok} allocated${fail ? `, ${fail} failed` : ''}`);
    setSelectedIds(new Set());
    loadTransactions();
  };

  const handleBatchDelete = async () => {
    if (selectedIds.size === 0) return;
    if (!window.confirm(`Delete ${selectedIds.size} transaction(s)? This cannot be undone.`)) return;
    try {
      await callAction({ action: 'delete', bankTransactionIds: Array.from(selectedIds) } as unknown as Record<string, string>);
      toast.success(`${selectedIds.size} transaction(s) deleted`);
      setSelectedIds(new Set());
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Delete failed'); }
  };

  const handleBulkAccept = async () => {
    if (selectedIds.size === 0) return;
    try {
      const res = await fetch('/api/accounting/bank-transactions-action', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
        body: JSON.stringify({ action: 'bulk_accept', bankTransactionIds: Array.from(selectedIds) }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) throw new Error(json.message || 'Failed to mark as reviewed');
      toast.success(`${json.data?.accepted ?? selectedIds.size} transaction(s) marked as reviewed`);
      setSelectedIds(new Set());
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed to mark as reviewed'); }
  };

  const handleExport = () => {
    const rows = transactions.map(tx => ({
      Date: tx.transactionDate,
      Description: tx.description || '',
      Reference: tx.reference || '',
      Spent: tx.amount < 0 ? Math.abs(tx.amount) : '',
      Received: tx.amount > 0 ? tx.amount : '',
      Status: tx.status,
    }));
    const header = Object.keys(rows[0] || {}).join(',');
    const csv = [header, ...rows.map(r => Object.values(r).map(v => `"${v}"`).join(','))].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `bank-transactions-${bank?.accountCode || 'export'}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // Apply batch edit selection to all selected rows
  const applyBatchEdit = (entityId: string, label: string) => {
    const updates: Record<string, RowSelection> = { ...rowSelections };
    let autoVat: VatCode | undefined;
    if (batchType === 'account' && entityId) {
      const acct = glAccounts.find(g => g.id === entityId);
      if (acct?.defaultVatCode && acct.defaultVatCode !== 'none') {
        autoVat = acct.defaultVatCode as VatCode;
      }
    }
    selectedIds.forEach(id => {
      const vatCode = autoVat ?? (updates[id]?.vatCode || 'none') as VatCode;
      updates[id] = { type: batchType, entityId, label, vatCode };
    });
    setRowSelections(updates);
    setShowBatchEdit(false);
    toast.success(`Applied ${batchType} "${label}" to ${selectedIds.size} rows`);
  };

  // Quick Win 4: Apply bank categorisation rules + smart categorization to current account
  const handleApplyRules = async () => {
    if (!selectedBank) { toast.error('Select a bank account first'); return; }
    try {
      // Step 1: Apply explicit bank rules first
      const rulesRes = await fetch('/api/accounting/bank-rules-action', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
        body: JSON.stringify({ action: 'apply', bankAccountId: selectedBank }),
      });
      const rulesJson = await rulesRes.json();
      if (!rulesRes.ok || rulesJson.success === false) throw new Error(rulesJson.message || 'Apply rules failed');
      const rulesResult = rulesJson.data || {};

      // Step 2: Run smart categorization on remaining uncategorized transactions
      const smartRes = await fetch('/api/accounting/smart-categorize', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
        body: JSON.stringify({ action: 'categorize', bankAccountId: selectedBank }),
      });
      const smartJson = await smartRes.json();
      const smartResult = smartJson.data || {};

      const rulesApplied = rulesResult.applied ?? 0;
      const smartCategorized = smartResult.categorized ?? 0;
      const totalSkipped = smartResult.skipped ?? 0;

      if (rulesApplied + smartCategorized > 0) {
        toast.success(`${rulesApplied} rules applied, ${smartCategorized} smart-categorised, ${totalSkipped} skipped`);
      } else {
        toast.success('No new categorisations found');
      }
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed to apply rules'); }
  };

  const handleReverse = async (txId: string) => {
    const tx = transactions.find(t => t.id === txId);
    const msg = tx?.status === 'allocated'
      ? 'Undo this allocation? The journal entry will be reversed.'
      : 'Reverse this transaction? The associated journal entry will also be reversed.';
    if (!window.confirm(msg)) return;
    try {
      await callAction({ action: 'reverse', bankTransactionId: txId });
      toast.success(tx?.status === 'allocated' ? 'Allocation undone' : 'Transaction reversed');
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Reverse failed'); }
  };

  const handleDownloadReport = async () => {
    if (!selectedBank) return;
    try {
      const res = await fetch(`/api/accounting/bank-reconciliation-report?bankAccountId=${selectedBank}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      const data = json.data || json;
      const { generateReconReport } = await import('@/modules/accounting/utils/reconReportPdf');
      const blob = await generateReconReport(data);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = `recon-report-${bank?.accountCode || 'bank'}.pdf`;
      a.click(); URL.revokeObjectURL(url);
      toast.success('Report downloaded');
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Report failed'); }
  };

  const bank = bankAccounts.find(b => b.id === selectedBank);
  const totalPages = Math.ceil(total / PAGE_SIZE);
  const allSelected = transactions.length > 0 && transactions.every(t => selectedIds.has(t.id));

  const toggleSelect = (id: string) => {
    setSelectedIds(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });
  };

  // Batch edit options
  const batchOptions = useMemo(() => {
    const opts = batchType === 'supplier' ? suppliers : batchType === 'customer' ? customers : glAccounts;
    if (!batchSearch) return opts.slice(0, 30);
    const q = batchSearch.toLowerCase();
    return opts.filter(o => (o.code || '').toLowerCase().includes(q) || o.name.toLowerCase().includes(q)).slice(0, 30);
  }, [batchType, batchSearch, glAccounts, suppliers, customers]);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header — bank account cards */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <h1 className="text-2xl font-bold text-[var(--ff-text-primary)] mb-3">Banking</h1>
          <div className="flex items-center gap-3 flex-wrap">
            {bankAccounts.map(b => {
              const active = b.id === selectedBank;
              const gap = b.unreconciledBalance;
              const hasGap = Math.abs(gap) >= 0.01;
              return (
                <button key={b.id} onClick={() => setSelectedBank(b.id)}
                  className={`flex items-center gap-3 px-4 py-2.5 rounded-lg border-2 transition-all text-left ${
                    active
                      ? 'border-teal-500 bg-teal-500/10 shadow-lg shadow-teal-500/10'
                      : 'border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] hover:border-[var(--ff-text-tertiary)]'
                  }`}>
                  <div className={`w-2 h-14 rounded-full shrink-0 ${active ? 'bg-teal-500' : 'bg-[var(--ff-border-light)]'}`} />
                  <div>
                    <p className={`text-sm font-semibold ${active ? 'text-teal-400' : 'text-[var(--ff-text-primary)]'}`}>
                      {b.accountName}
                    </p>
                    <p className="text-xs text-[var(--ff-text-tertiary)] font-mono">
                      {b.accountCode}
                      {b.bankAccountNumber && <span className="ml-1.5">| ****{b.bankAccountNumber.slice(-4)}</span>}
                    </p>
                  </div>
                  <div className="ml-3 text-right">
                    {/* Statement balance — sum of all imported transactions */}
                    <p className={`text-sm font-bold font-mono ${b.balance >= 0 ? 'text-teal-400' : 'text-red-400'}`}>
                      {fmtCurrency(b.balance)}
                    </p>
                    {/* Reconciled vs unreconciled breakdown */}
                    <div className="flex items-center gap-2 mt-0.5">
                      <span className="text-[10px] text-teal-500/80 font-mono" title="Allocated to GL entries">
                        ✓ {fmtCurrency(b.reconciledBalance)}
                      </span>
                      {hasGap && (
                        <span className="text-[10px] text-amber-400 font-mono" title={`${b.unreconciledCount} unallocated transaction${b.unreconciledCount !== 1 ? 's' : ''}`}>
                          Δ {fmtCurrency(Math.abs(gap))}
                        </span>
                      )}
                    </div>
                  </div>
                </button>
              );
            })}
            {bank && (
              <div className="ml-auto flex items-center gap-4">
                <StatementBalanceWidget bankAccountId={selectedBank} glBalance={bank.balance} />
                <div className="text-right">
                  <p className="text-2xl font-bold text-[var(--ff-text-primary)]">{total}</p>
                  <p className="text-xs text-[var(--ff-text-tertiary)]">
                    {tab === 'new' ? 'To be Reviewed' : tab === 'excluded' ? 'Excluded' : 'Reviewed'}
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Tabs */}
        <div className="px-6 border-b border-[var(--ff-border-light)]">
          <div className="flex gap-0">
            {(['new', 'reviewed', 'excluded'] as Tab[]).map(t => (
              <button key={t} onClick={() => setTab(t)}
                className={`px-5 py-2.5 text-sm font-medium border-b-2 transition-colors ${
                  tab === t
                    ? t === 'excluded'
                      ? 'border-red-500 text-red-400'
                      : 'border-teal-500 text-teal-400'
                    : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
                }`}>
                {t === 'new' ? 'New Transactions' : t === 'excluded' ? 'Excluded' : 'Reviewed Transactions'}
              </button>
            ))}
          </div>
        </div>

        {/* Toolbar — matches Sage: Actions | Mark Reviewed | Delete | Batch Edit | Import | Export | Search */}
        <div className="px-6 py-2 border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]/30 flex items-center gap-2 flex-wrap">
          <button onClick={() => loadTransactions()} title="Refresh"
            className="flex items-center gap-1 text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
            <RefreshCw className="h-3.5 w-3.5" /> Actions
          </button>
          {tab === 'new' && (
            <>
              <button onClick={handleBulkAccept}
                disabled={selectedIds.size === 0}
                className="flex items-center gap-1 px-2 py-1 rounded text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] disabled:opacity-30">
                <CheckCheck className="h-3.5 w-3.5" /> Mark as Reviewed
              </button>
              {selectedIds.size > 0 && (
                <button onClick={handleBatchAccept}
                  className="flex items-center gap-1 px-2 py-1 rounded text-xs text-teal-400 hover:text-teal-300 bg-teal-500/10 hover:bg-teal-500/20">
                  <CheckCheck className="h-3.5 w-3.5" /> Batch Allocate
                </button>
              )}
              <button onClick={handleBatchDelete}
                disabled={selectedIds.size === 0}
                className="flex items-center gap-1 px-2 py-1 rounded text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] disabled:opacity-30">
                <Trash2 className="h-3.5 w-3.5" /> Delete
              </button>
              <button onClick={() => { setShowBatchEdit(!showBatchEdit); setBatchSearch(''); }}
                disabled={selectedIds.size === 0}
                className="flex items-center gap-1 px-2 py-1 rounded text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] disabled:opacity-30">
                <Layers className="h-3.5 w-3.5" /> Batch Edit
              </button>
            </>
          )}
          <div className="border-l border-[var(--ff-border-light)] h-5 mx-1" />
          <Link href="/accounting/bank-reconciliation/import"
            className="flex items-center gap-1 px-2.5 py-1 rounded border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
            <Upload className="h-3.5 w-3.5" /> Import Bank Statements
          </Link>
          <button onClick={handleExport}
            className="flex items-center gap-1 px-2.5 py-1 rounded border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
            <Download className="h-3.5 w-3.5" /> Export
          </button>
          {/* Quick Win 4: Apply Rules + Smart Categorize */}
          <button onClick={handleApplyRules} disabled={!selectedBank}
            className="flex items-center gap-1 px-2.5 py-1 rounded border border-yellow-500/40 text-xs text-yellow-500 hover:text-yellow-400 hover:border-yellow-400 disabled:opacity-30"
            title="Apply bank rules, then smart-categorize remaining transactions using patterns and historical data">
            <Zap className="h-3.5 w-3.5" /> Smart Categorize
          </button>
          <Link href="/accounting/bank-transactions/new"
            className="flex items-center gap-1 px-2.5 py-1 rounded border border-teal-500/60 text-xs text-teal-400 hover:text-teal-300 hover:border-teal-400 font-medium">
            <Plus className="h-3.5 w-3.5" /> New Transaction
          </Link>
          <button onClick={handleDownloadReport} disabled={!selectedBank}
            className="flex items-center gap-1 px-2.5 py-1 rounded border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] disabled:opacity-30">
            <FileText className="h-3.5 w-3.5" /> Recon Report
          </button>
          {/* Date range filter */}
          <div className="flex items-center gap-1 text-xs text-[var(--ff-text-secondary)]">
            <input type="date" value={fromDate} onChange={e => { setFromDate(e.target.value); setPage(1); }}
              className="px-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)]" />
            <span>to</span>
            <input type="date" value={toDate} onChange={e => { setToDate(e.target.value); setPage(1); }}
              className="px-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)]" />
          </div>
          {/* Amount range filter */}
          <div className="flex items-center gap-1 text-xs text-[var(--ff-text-secondary)]">
            <span className="shrink-0">Min R</span>
            <input
              type="number"
              step="0.01"
              value={fromAmount}
              onChange={e => {
                setFromAmount(e.target.value);
                if (amountDebounceTimer.current) clearTimeout(amountDebounceTimer.current);
                amountDebounceTimer.current = setTimeout(() => setPage(1), 500);
              }}
              placeholder="0"
              className="w-20 px-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)]"
            />
            <span className="shrink-0">Max R</span>
            <input
              type="number"
              step="0.01"
              value={toAmount}
              onChange={e => {
                setToAmount(e.target.value);
                if (amountDebounceTimer.current) clearTimeout(amountDebounceTimer.current);
                amountDebounceTimer.current = setTimeout(() => setPage(1), 500);
              }}
              placeholder="any"
              className="w-20 px-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)]"
            />
          </div>
          {/* Quick Win 2: Server-side search (debounced 500ms) */}
          <div className="ml-auto flex items-center gap-2">
            <div className="relative">
              <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-[var(--ff-text-tertiary)]" />
              <input type="text" placeholder="Search..." value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="pl-7 pr-3 py-1 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)] w-44" />
            </div>
            <span className="text-xs text-[var(--ff-text-tertiary)]">
              {total > 0 ? `${(page - 1) * PAGE_SIZE + 1}–${Math.min(page * PAGE_SIZE, total)}` : '0'} of {total}
            </span>
          </div>
        </div>

        {/* Batch Edit Panel */}
        {showBatchEdit && selectedIds.size > 0 && (
          <div className="px-6 py-3 border-b border-blue-500/30 bg-blue-500/5 flex items-center gap-3 flex-wrap">
            <span className="text-xs text-blue-400 font-medium">Batch Edit ({selectedIds.size} selected):</span>
            <select value={batchType} onChange={e => { setBatchType(e.target.value as AllocType); setBatchSearch(''); }}
              className="text-xs px-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)]">
              <option value="account">Account</option>
              <option value="supplier">Supplier</option>
              <option value="customer">Customer</option>
            </select>
            <div className="relative">
              <input type="text" placeholder={`Search ${batchType}s...`} value={batchSearch}
                onChange={e => setBatchSearch(e.target.value)}
                className="pl-2 pr-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)] w-52"
                autoFocus />
              <div className="absolute z-50 top-full left-0 mt-1 w-72 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg shadow-xl max-h-48 overflow-y-auto">
                {batchOptions.map(o => (
                  <button key={o.id} onClick={() => applyBatchEdit(o.id, o.code ? `${o.code} ${o.name}` : o.name)}
                    className="w-full text-left px-3 py-1.5 hover:bg-[var(--ff-bg-primary)] text-xs flex items-center gap-2">
                    {o.code && <span className="font-mono text-[var(--ff-text-tertiary)]">{o.code}</span>}
                    <span className="text-[var(--ff-text-primary)]">{o.name}</span>
                  </button>
                ))}
                {batchOptions.length === 0 && (
                  <div className="px-3 py-2 text-xs text-[var(--ff-text-tertiary)]">No results found</div>
                )}
              </div>
            </div>
            <button onClick={() => setShowBatchEdit(false)}
              className="text-xs text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]">Cancel</button>
          </div>
        )}

        {/* Rule suggestion banner — appears after allocating a transaction with similar matches */}
        {rulePrompt && (
          <div className="px-6 py-3 border-b border-yellow-500/30 bg-yellow-500/5 flex items-center gap-3 flex-wrap">
            <span className="text-xs text-yellow-400 font-medium">
              {rulePrompt.matchCount} similar transaction{rulePrompt.matchCount !== 1 ? 's' : ''} found matching
              &ldquo;{extractPattern(rulePrompt.tx.description || '')}&rdquo;.
              Create a rule to auto-categorise them?
            </span>
            <button
              onClick={() => { setCreateRuleTx(rulePrompt.tx); setRulePrompt(null); }}
              className="px-3 py-1 rounded bg-yellow-500/20 hover:bg-yellow-500/30 border border-yellow-500/40 text-xs text-yellow-400 font-medium transition-colors"
            >
              Create Rule
            </button>
            <button
              onClick={() => setRulePrompt(null)}
              className="px-3 py-1 rounded text-xs text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-secondary)]"
            >
              Dismiss
            </button>
          </div>
        )}

        {/* Table */}
        <div className="px-4 py-2">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-blue-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" /><span>{error}</span>
            </div>
          ) : transactions.length === 0 ? (
            <div className="text-center py-12 text-[var(--ff-text-secondary)]">
              No {tab === 'new' ? 'new' : tab === 'excluded' ? 'excluded' : 'reviewed'} transactions for this account
            </div>
          ) : (
            <BankTxTable
              transactions={transactions}
              glAccounts={glAccounts}
              suppliers={suppliers}
              customers={customers}
              cc1Options={cc1Options}
              cc2Options={cc2Options}
              buOptions={buOptions}
              selectedIds={selectedIds}
              rowSelections={rowSelections}
              allSelected={allSelected}
              tab={tab}
              onToggleSelect={toggleSelect}
              onSelectAll={() => setSelectedIds(
                allSelected ? new Set() : new Set(transactions.map(t => t.id))
              )}
              onRowTypeChange={(txId, type) => {
                // VAT only applies to GL account allocations; supplier/customer VAT is handled on their invoices
                const vatCode = type === 'account' ? (rowSelections[txId]?.vatCode || 'none') : 'none';
                setRowSelections(prev => ({ ...prev, [txId]: { type, entityId: '', label: '', vatCode } }));
                saveSelection(txId, type, '');
              }}
              onRowEntityChange={(txId, entityId, label) => {
                const type = rowSelections[txId]?.type || 'account';
                let vatCode = (rowSelections[txId]?.vatCode || 'none') as VatCode;
                if (type === 'account' && entityId) {
                  const acct = glAccounts.find(g => g.id === entityId);
                  if (acct?.defaultVatCode && acct.defaultVatCode !== 'none') {
                    vatCode = acct.defaultVatCode as VatCode;
                  }
                }
                setRowSelections(prev => ({
                  ...prev,
                  [txId]: { ...prev[txId], type, entityId, label, vatCode },
                }));
                saveSelection(txId, type as AllocType, entityId);
              }}
              onRowVatChange={(txId, vatCode) =>
                setRowSelections(prev => ({
                  ...prev,
                  [txId]: { ...prev[txId], type: prev[txId]?.type || 'account', entityId: prev[txId]?.entityId || '', label: prev[txId]?.label || '', vatCode },
                }))
              }
              onRowDimensionChange={(txId, cc1Id, cc2Id, buId) => {
                setRowSelections(prev => ({ ...prev, [txId]: { ...prev[txId], type: prev[txId]?.type || 'account', entityId: prev[txId]?.entityId || '', label: prev[txId]?.label || '', vatCode: prev[txId]?.vatCode || 'none', cc1Id: cc1Id || undefined, cc2Id: cc2Id || undefined, buId: buId || undefined } }));
                saveDimensions(txId, cc1Id, cc2Id, buId);
              }}
              onAccept={handleAccept}
              onExclude={handleExclude}
              onUnmatch={handleUnmatch}
              onSplit={handleSplit}
              onUpdateNotes={handleUpdateNotes}
              onFindMatch={(txId) => setFindMatchTxId(txId)}
              onReverse={handleReverse}
              onAttachments={(txId) => setAttachmentsTxId(txId)}
              onCreateRule={(tx) => setCreateRuleTx(tx)}
              onCreateEntity={(txId, type) => { setCreateEntityTxId(txId); setCreateEntityType(type); }}
            />
          )}
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="px-6 py-3 border-t border-[var(--ff-border-light)] flex items-center justify-between">
            <div className="flex items-center gap-1">
              <button disabled={page <= 1} onClick={() => setPage(1)}
                className="px-3 py-2 rounded text-xs text-[var(--ff-text-secondary)] disabled:opacity-30">First</button>
              {Array.from({ length: Math.min(totalPages, 10) }, (_, i) => {
                const p = totalPages <= 10 ? i + 1
                  : page <= 5 ? i + 1
                  : page >= totalPages - 4 ? totalPages - 9 + i
                  : page - 5 + i;
                return (
                  <button key={p} onClick={() => setPage(p)}
                    className={`w-7 h-7 rounded text-xs ${
                      p === page ? 'bg-teal-600 text-white font-bold'
                        : 'text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-secondary)]'
                    }`}>{p}</button>
                );
              })}
              <button disabled={page >= totalPages} onClick={() => setPage(totalPages)}
                className="px-3 py-2 rounded text-xs text-[var(--ff-text-secondary)] disabled:opacity-30">Last</button>
            </div>
            <span className="text-xs text-[var(--ff-text-tertiary)]">
              Displaying {(page - 1) * PAGE_SIZE + 1}–{Math.min(page * PAGE_SIZE, total)} of {total}
            </span>
          </div>
        )}

        {/* Bottom bar — Sage-style: Mark Selected as Reviewed */}
        {tab === 'new' && transactions.length > 0 && (
          <div className="sticky bottom-0 bg-[var(--ff-bg-secondary)] border-t border-[var(--ff-border-light)] px-6 py-3 flex items-center justify-center gap-4">
            <button onClick={handleBulkAccept}
              disabled={selectedIds.size === 0}
              className="px-5 py-2 bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white rounded-lg text-sm font-medium">
              Mark Selected as Reviewed ({selectedIds.size})
            </button>
          </div>
        )}
      </div>
      {/* Split Transaction Modal */}
      {splitTxId && (() => {
        const splitTx = transactions.find(t => t.id === splitTxId);
        if (!splitTx) return null;
        return (
          <SplitTransactionModal
            transaction={splitTx}
            glAccounts={glAccounts}
            onClose={() => setSplitTxId(null)}
            onSplit={() => {
              setSplitTxId(null);
              loadTransactions();
            }}
          />
        );
      })()}
      {/* Exclude Reason Modal */}
      {excludingTxId && (() => {
        const excludeTx = transactions.find(t => t.id === excludingTxId);
        if (!excludeTx) return null;
        return (
          <ExcludeReasonModal
            transaction={excludeTx}
            onClose={() => setExcludingTxId(null)}
            onExclude={(reason) => handleExcludeConfirm(reason)}
          />
        );
      })()}
      {/* Find & Match Modal */}
      {findMatchTxId && (() => {
        const matchTx = transactions.find(t => t.id === findMatchTxId);
        if (!matchTx) return null;
        return (
          <FindMatchModal
            transaction={{ id: matchTx.id, description: matchTx.description || '', amount: matchTx.amount, transactionDate: matchTx.transactionDate }}
            onClose={() => setFindMatchTxId(null)}
            onMatch={() => { setFindMatchTxId(null); loadTransactions(); }}
          />
        );
      })()}
      {/* Attachments Modal */}
      {attachmentsTxId && (
        <BankTxAttachmentsModal
          bankTransactionId={attachmentsTxId}
          transactionDescription={transactions.find(t => t.id === attachmentsTxId)?.description}
          onClose={() => setAttachmentsTxId(null)}
        />
      )}
      {/* Create Rule Modal */}
      {createRuleTx && (
        <CreateRuleModal
          transaction={createRuleTx}
          bankAccountId={selectedBank}
          glAccounts={glAccounts}
          suppliers={suppliers}
          clients={customers}
          onClose={() => setCreateRuleTx(null)}
          onCreated={() => {
            setCreateRuleTx(null);
            toast.success('Rule created — click "Apply Rules" to categorise matching transactions');
            loadTransactions();
          }}
        />
      )}
      {/* Create Entity Modal (GL Account / Supplier / Customer) */}
      {createEntityTxId && createEntityType && (
        <CreateEntityModal
          type={createEntityType}
          onClose={() => { setCreateEntityTxId(null); setCreateEntityType(null); }}
          onCreated={(entity) => {
            const label = entity.code ? `${entity.code} ${entity.name}` : entity.name;
            const option: SelectOption = { id: entity.id, code: entity.code, name: entity.name };
            if (createEntityType === 'account') {
              setGlAccounts(prev => [...prev, option].sort((a, b) => (a.code || '').localeCompare(b.code || '')));
            } else if (createEntityType === 'supplier') {
              setSuppliers(prev => [...prev, option]);
            } else {
              setCustomers(prev => [...prev, option]);
            }
            setRowSelections(prev => ({
              ...prev,
              [createEntityTxId]: {
                type: createEntityType,
                entityId: entity.id,
                label,
                vatCode: prev[createEntityTxId]?.vatCode || 'none',
              },
            }));
            setCreateEntityTxId(null);
            setCreateEntityType(null);
          }}
        />
      )}
    </AppLayout>
  );
}

/**
 * Supplier Returns / Debit Notes
 * Sage equivalent: Suppliers > Returns
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { TrendingDown, Loader2, AlertCircle, Plus, X } from 'lucide-react';
import toast from 'react-hot-toast';
import { formatCurrency } from '@/utils/formatters';

interface SupplierReturn {
  id: string; return_number: string; supplier_name: string;
  original_invoice_number?: string; amount: number;
  status: string; return_date: string; reason: string;
}
interface Supplier { id: number; name: string; }
interface Form { supplierId: string; originalInvoiceNumber: string; amount: string; reason: string; }

const EMPTY: Form = { supplierId: '', originalInvoiceNumber: '', amount: '', reason: '' };

export default function SupplierReturnsPage() {
  const [returns, setReturns] = useState<SupplierReturn[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState<Form>(EMPTY);
  const [submitting, setSubmitting] = useState(false);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);

  const loadReturns = useCallback(async () => {
    setIsLoading(true); setError('');
    try {
      const res = await fetch('/api/accounting/supplier-returns');
      const json = await res.json();
      setReturns((json.data || json).returns || []);
    } catch { setError('Failed to load supplier returns'); }
    finally { setIsLoading(false); }
  }, []);

  useEffect(() => { loadReturns(); }, [loadReturns]);

  useEffect(() => {
    fetch('/api/procurement/suppliers').then(r => r.json()).then(json => {
      const data = json.data || json;
      setSuppliers((data.suppliers || []).map((s: Record<string, unknown>) => ({
        id: s.id as number,
        name: (s.company_name || s.name) as string,
      })));
    }).catch(() => { /* non-critical */ });
  }, []);

  function set(field: keyof Form, value: string) {
    setForm(f => ({ ...f, [field]: value }));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!form.supplierId) { toast.error('Please select a supplier'); return; }
    if (!form.amount || Number(form.amount) <= 0) { toast.error('Please enter a valid amount'); return; }
    setSubmitting(true);
    try {
      const res = await fetch('/api/accounting/supplier-returns', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          supplierId: Number(form.supplierId),
          originalInvoiceNumber: form.originalInvoiceNumber || undefined,
          amount: Number(form.amount),
          reason: form.reason || undefined,
        }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || 'Failed to create return');
      toast.success('Supplier return created');
      setShowForm(false); setForm(EMPTY);
      await loadReturns();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to create return');
    } finally { setSubmitting(false); }
  }

  const inp = 'w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:border-teal-500';
  const lbl = 'block text-xs font-medium text-[var(--ff-text-secondary)] mb-1';

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-red-500/10">
                <TrendingDown className="h-6 w-6 text-red-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Supplier Returns</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Debit notes and returns to suppliers</p>
              </div>
            </div>
            <button onClick={() => { setForm(EMPTY); setShowForm(true); }}
              className="px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg flex items-center gap-2 text-sm">
              <Plus className="h-4 w-4" /> New Return
            </button>
          </div>
        </div>

        {/* Create form panel */}
        {showForm && (
          <div className="px-6 pt-6">
            <div className="rounded-xl border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] p-6 mb-4">
              <div className="flex items-center justify-between mb-5">
                <h2 className="text-base font-semibold text-[var(--ff-text-primary)]">New Supplier Return</h2>
                <button onClick={() => { setShowForm(false); setForm(EMPTY); }}
                  className="text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]">
                  <X className="h-5 w-5" />
                </button>
              </div>
              <form onSubmit={handleSubmit}>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-4">
                  <div>
                    <label className={lbl}>Supplier <span className="text-red-400">*</span></label>
                    <select className={inp} value={form.supplierId}
                      onChange={e => set('supplierId', e.target.value)} required>
                      <option value="">Select supplier…</option>
                      {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className={lbl}>Original Invoice #</label>
                    <input type="text" className={inp} placeholder="e.g. INV-00123"
                      value={form.originalInvoiceNumber}
                      onChange={e => set('originalInvoiceNumber', e.target.value)} />
                  </div>
                  <div>
                    <label className={lbl}>Amount <span className="text-red-400">*</span></label>
                    <div className="relative">
                      <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--ff-text-secondary)] text-sm">R</span>
                      <input type="number" min="0.01" step="0.01" className={`${inp} pl-7`}
                        placeholder="0.00" value={form.amount}
                        onChange={e => set('amount', e.target.value)} required />
                    </div>
                  </div>
                  <div>
                    <label className={lbl}>Reason</label>
                    <textarea className={`${inp} resize-none h-[42px]`} placeholder="Reason for return…"
                      value={form.reason} onChange={e => set('reason', e.target.value)} />
                  </div>
                </div>
                <div className="flex justify-end gap-3">
                  <button type="button"
                    onClick={() => { setShowForm(false); setForm(EMPTY); }}
                    className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)] rounded-lg">
                    Cancel
                  </button>
                  <button type="submit" disabled={submitting}
                    className="px-4 py-2 text-sm bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white rounded-lg flex items-center gap-2">
                    {submitting && <Loader2 className="h-4 w-4 animate-spin" />}
                    Create Return
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* List */}
        <div className="p-6">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-red-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" /><span>{error}</span>
            </div>
          ) : returns.length === 0 ? (
            <div className="text-center py-12">
              <TrendingDown className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)]">No supplier returns found</p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">Create a debit note to process a return to a supplier</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--ff-border-light)]">
                    {['Return #', 'Supplier', 'Original Invoice', 'Date', 'Amount', 'Reason', 'Status'].map(h => (
                      <th key={h} className={`py-3 px-4 text-[var(--ff-text-secondary)] font-medium ${h === 'Amount' ? 'text-right' : 'text-left'}`}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {returns.map(r => (
                    <tr key={r.id} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)]">
                      <td className="py-3 px-4 text-[var(--ff-text-primary)] font-mono">{r.return_number}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-primary)]">{r.supplier_name}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{r.original_invoice_number || '-'}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{r.return_date?.split('T')[0]}</td>
                      <td className="py-3 px-4 text-right text-red-400">{formatCurrency(r.amount)}</td>
                      <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{r.reason}</td>
                      <td className="py-3 px-4">
                        <span className={`px-2 py-1 rounded-full text-xs font-medium ${r.status === 'processed' ? 'bg-teal-500/10 text-teal-400' : 'bg-yellow-500/10 text-yellow-400'}`}>
                          {r.status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Bank Accounts Management
 * Sage equivalent: Banking > Bank Accounts
 * View and manage bank accounts linked to GL
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Landmark, Loader2, AlertCircle, Plus, ArrowUpRight, ArrowDownRight, X, Pencil } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { formatCurrency } from '@/utils/formatters';

/** Mask account number for display: show last 4 digits only */
function maskAccountNumber(num: string): string {
  if (num.length <= 4) return num;
  return '****' + num.slice(-4);
}

interface BankAccount {
  id: string;
  accountCode: string;
  accountName: string;
  description?: string;
  bankAccountNumber?: string | null;
  isActive: boolean;
  txnCount: number;
  totalDebits: number;
  totalCredits: number;
  balance: number;
  firstDate?: string;
  lastDate?: string;
}

interface EditForm {
  accountName: string;
  description: string;
  bankAccountNumber: string;
}

export default function BankAccountsPage() {
  const [accounts, setAccounts] = useState<BankAccount[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [showAddModal, setShowAddModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({ accountCode: '', accountName: '', description: '', bankAccountNumber: '' });

  const [editingAccount, setEditingAccount] = useState<BankAccount | null>(null);
  const [editForm, setEditForm] = useState<EditForm>({ accountName: '', description: '', bankAccountNumber: '' });

  const loadAccounts = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const res = await fetch('/api/accounting/bank-accounts');
      const json = await res.json();
      const data = json.data || json;
      setAccounts(Array.isArray(data) ? data : []);
    } catch {
      setError('Failed to load bank accounts');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => { loadAccounts(); }, [loadAccounts]);

  const handleAdd = async () => {
    if (!form.accountCode || !form.accountName) {
      toast.error('Account code and name are required');
      return;
    }
    setSaving(true);
    try {
      const res = await fetch('/api/accounting/chart-of-accounts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          accountCode: form.accountCode,
          accountName: form.accountName,
          accountType: 'asset',
          accountSubtype: 'bank',
          parentAccountId: 'bf801b3b-de70-4c10-8d8f-689de8b8a9ad',
          description: form.description || form.accountName,
          normalBalance: 'debit',
        }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) {
        toast.error(json.message || json.error || 'Failed to create account');
        return;
      }
      // If bank account number provided, save it separately
      if (form.bankAccountNumber.trim()) {
        const created = json.data || json;
        await fetch('/api/accounting/bank-accounts', {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ id: created.id, bankAccountNumber: form.bankAccountNumber.trim() }),
        });
      }
      toast.success('Bank account created');
      setShowAddModal(false);
      setForm({ accountCode: '', accountName: '', description: '', bankAccountNumber: '' });
      loadAccounts();
    } catch {
      toast.error('Failed to create bank account');
    } finally {
      setSaving(false);
    }
  };

  const handleEdit = (acct: BankAccount) => {
    setEditingAccount(acct);
    setEditForm({
      accountName: acct.accountName,
      description: acct.description || '',
      bankAccountNumber: acct.bankAccountNumber || '',
    });
  };

  const handleSaveEdit = async () => {
    if (!editingAccount) return;
    if (!editForm.accountName.trim()) {
      toast.error('Account name is required');
      return;
    }
    setSaving(true);
    try {
      // Update name & description via chart-of-accounts
      const coaRes = await fetch('/api/accounting/chart-of-accounts', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          id: editingAccount.id,
          accountName: editForm.accountName.trim(),
          description: editForm.description.trim() || null,
        }),
      });
      if (!coaRes.ok) {
        const json = await coaRes.json();
        toast.error(json.message || 'Failed to update account');
        return;
      }
      // Update bank account number
      await fetch('/api/accounting/bank-accounts', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          id: editingAccount.id,
          bankAccountNumber: editForm.bankAccountNumber.trim() || null,
        }),
      });
      toast.success('Bank account updated');
      setEditingAccount(null);
      loadAccounts();
    } catch {
      toast.error('Failed to update bank account');
    } finally {
      setSaving(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-cyan-500/10">
                  <Landmark className="h-6 w-6 text-cyan-500" />
                </div>
                <div>
                  <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Bank Accounts</h1>
                  <p className="text-sm text-[var(--ff-text-secondary)]">
                    Manage bank accounts and view balances
                  </p>
                </div>
              </div>
              <button
                onClick={() => setShowAddModal(true)}
                className="px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg flex items-center gap-2 text-sm"
              >
                <Plus className="h-4 w-4" />
                Add Bank Account
              </button>
            </div>
          </div>
        </div>

        <div className="p-6">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-cyan-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" />
              <span>{error}</span>
            </div>
          ) : accounts.length === 0 ? (
            <div className="text-center py-12">
              <Landmark className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)]">No bank accounts configured</p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">
                Bank accounts are GL accounts with subtype &quot;bank&quot;
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {accounts.map((acct) => (
                <div key={acct.id} className="p-5 rounded-xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] hover:border-cyan-500/30 transition-colors relative group">
                  <button
                    onClick={() => handleEdit(acct)}
                    className="absolute top-3 right-12 p-1.5 rounded-lg opacity-0 group-hover:opacity-100 hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)] hover:text-cyan-400 transition-all"
                    title="Edit account"
