              </button>
              {showRawText && (
                <div className="px-6 pb-6">
                  <pre className="bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg p-4 text-xs text-[var(--ff-text-secondary)] whitespace-pre-wrap font-mono max-h-96 overflow-y-auto">
                    {extracted.rawText}
                  </pre>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

