      setError(message);
      toast.error(message);
    } finally {
      setIsProcessing(false);
    }
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center gap-3">
            <Link
              href="/payroll/runs"
              className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] transition-colors"
            >
              <ArrowLeft className="h-5 w-5" />
            </Link>
            <div className="p-2 rounded-lg bg-teal-500/10">
              <CalendarDays className="h-6 w-6 text-teal-500" />
            </div>
            <div>
              <h1 className="text-xl font-semibold text-[var(--ff-text-primary)]">New Payroll Run</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">Process payroll for a period</p>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-5xl">
          {!result ? (
            <>
              {/* Period Selection */}
              <div className="mb-8 p-6 rounded-lg border border-[var(--ff-border-primary)] bg-[var(--ff-surface-primary)]">
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Pay Period</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Period Start</label>
                    <input
                      type="date"
                      value={periodStart}
                      onChange={(e) => setPeriodStart(e.target.value)}
                      className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-primary)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:ring-1 focus:ring-teal-500"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Period End</label>
                    <input
                      type="date"
                      value={periodEnd}
                      onChange={(e) => setPeriodEnd(e.target.value)}
                      className="w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-primary)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:ring-1 focus:ring-teal-500"
                    />
                  </div>
                </div>
              </div>

              {/* Employee Preview */}
              <div className="mb-8">
                <div className="flex items-center gap-2 mb-4">
                  <Users className="h-5 w-5 text-teal-500" />
                  <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                    Employees to Process ({employees.length})
                  </h2>
                </div>

                {isLoadingEmps ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader2 className="h-6 w-6 animate-spin text-teal-500" />
                  </div>
                ) : employees.length === 0 ? (
                  <div className="text-center py-8 text-[var(--ff-text-tertiary)]">
                    <p>No active employees found. Add employees first.</p>
                    <Link
                      href="/payroll/employees/new"
                      className="inline-flex items-center gap-2 mt-3 text-teal-400 hover:text-teal-300 text-sm font-medium"
                    >
                      Add Employee
                    </Link>
                  </div>
                ) : (
                  <div className="rounded-lg border border-[var(--ff-border-primary)] overflow-hidden bg-[var(--ff-surface-primary)]">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                          <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Emp #</th>
                          <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Name</th>
                          <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Department</th>
                          <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Basic Salary</th>
                          <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Total Package</th>
                        </tr>
                      </thead>
                      <tbody>
                        {employees.map((emp) => {
                          const ps = emp.pay_structure;
                          const total = ps
                            ? ps.basic_salary + ps.travel_allowance + ps.housing_allowance + ps.cell_allowance + ps.other_allowances
                            : 0;
                          return (
                            <tr key={emp.id} className="border-b border-[var(--ff-border-primary)] last:border-0">
                              <td className="py-2 px-4 text-[var(--ff-text-secondary)] font-mono text-xs">{emp.employee_number}</td>
                              <td className="py-2 px-4 text-[var(--ff-text-primary)]">{emp.first_name} {emp.last_name}</td>
                              <td className="py-2 px-4 text-[var(--ff-text-secondary)]">{emp.department || '-'}</td>
                              <td className="py-2 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{ps ? formatCurrency(ps.basic_salary) : '-'}</td>
                              <td className="py-2 px-4 text-right font-mono text-[var(--ff-text-primary)]">{ps ? formatCurrency(total) : '-'}</td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>

              {error && (
                <div className="mb-6 flex items-center gap-2 text-red-400 text-sm">
                  <AlertCircle className="h-4 w-4" />
                  <span>{error}</span>
                </div>
              )}

              {/* Run Button */}
              <button
                onClick={handleRunPayroll}
                disabled={isProcessing || employees.length === 0}
                className="flex items-center gap-2 px-6 py-3 rounded-lg bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white text-sm font-medium transition-colors"
              >
                {isProcessing ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Play className="h-4 w-4" />
                )}
                Run Payroll
              </button>
            </>
          ) : (
            <>
              {/* Results */}
              <div className="mb-8">
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Payroll Run Results</h2>

                {/* Summary Stats */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                  <StatCard label="Total Gross" value={formatCurrency(result.total_gross)} />
                  <StatCard label="Total PAYE" value={formatCurrency(result.total_paye)} />
                  <StatCard label="Total Net" value={formatCurrency(result.total_net)} highlight />
                  <StatCard label="Company Cost" value={formatCurrency(result.total_company_cost)} />
                  <StatCard label="UIF (Employee)" value={formatCurrency(result.total_uif_employee)} />
                  <StatCard label="UIF (Employer)" value={formatCurrency(result.total_uif_employer)} />
                  <StatCard label="SDL" value={formatCurrency(result.total_sdl)} />
                  <StatCard label="Employees" value={String(result.payslips.length)} />
                </div>

                {/* Payslips Table */}
                <div className="rounded-lg border border-[var(--ff-border-primary)] overflow-hidden bg-[var(--ff-surface-primary)]">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                        <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Employee</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Gross</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">PAYE</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">UIF</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Medical</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Retirement</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Deductions</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Net Pay</th>
                      </tr>
                    </thead>
                    <tbody>
                      {result.payslips.map((slip, i) => (
                        <tr key={i} className="border-b border-[var(--ff-border-primary)] last:border-0">
                          <td className="py-2 px-4 text-[var(--ff-text-primary)]">
                            <span className="text-xs text-[var(--ff-text-tertiary)] mr-2">{slip.employee_number}</span>
                            {slip.first_name} {slip.last_name}
                          </td>
                          <td className="py-2 px-4 text-right font-mono text-[var(--ff-text-primary)]">{formatCurrency(slip.gross_pay)}</td>
                          <td className="py-2 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(slip.paye)}</td>
                          <td className="py-2 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(slip.uif_employee)}</td>
                          <td className="py-2 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(slip.medical_aid)}</td>
                          <td className="py-2 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(slip.retirement_fund)}</td>
                          <td className="py-2 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(slip.total_deductions)}</td>
                          <td className="py-2 px-4 text-right font-mono text-[var(--ff-text-primary)] font-medium">{formatCurrency(slip.net_pay)}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Navigation buttons */}
              <div className="flex items-center gap-3">
                <Link
                  href={`/payroll/runs/${result.id}`}
                  className="px-6 py-2.5 rounded-lg bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium transition-colors"
                >
                  View Run Details
                </Link>
                <Link
                  href="/payroll/runs"
                  className="px-6 py-2.5 rounded-lg border border-[var(--ff-border-primary)] text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-tertiary)] text-sm font-medium transition-colors"
                >
                  Back to Runs
                </Link>
              </div>
            </>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

function StatCard({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
  return (
    <div className={`p-4 rounded-lg border ${
      highlight
        ? 'border-teal-500/30 bg-teal-500/5'
        : 'border-[var(--ff-border-primary)] bg-[var(--ff-surface-primary)]'
    }`}>
      <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">{label}</p>
      <p className={`text-lg font-semibold font-mono ${
        highlight ? 'text-teal-400' : 'text-[var(--ff-text-primary)]'
      }`}>{value}</p>
    </div>
  );
}

/**
 * Employee Detail Page
 * View/edit employee details, pay history, payslip history.
 * Route: /payroll/employees/[employeeId]
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { Users, Loader2, AlertCircle, ArrowLeft, Save, FileText } from 'lucide-react';
import Link from 'next/link';
import { notify } from '@/utils/toast';

interface PayStructure {
  id: string;
  basic_salary: number;
  travel_allowance: number;
  housing_allowance: number;
  cell_allowance: number;
  other_allowances: number;
  medical_aid_contribution: number;
  retirement_fund_contribution_pct: number;
  effective_from: string;
  effective_to: string | null;
}

interface PayslipSummary {
  id: string;
  payroll_run_id: string;
  gross_pay: number;
  paye: number;
  uif_employee: number;
  net_pay: number;
  created_at: string;
  period_start?: string;
  period_end?: string;
}

interface EmployeeDetail {
  id: string;
  employee_number: string;
  first_name: string;
  last_name: string;
  id_number: string | null;
  tax_number: string | null;
  start_date: string;
  termination_date: string | null;
  bank_name: string | null;
  bank_account_number: string | null;
  bank_branch_code: string | null;
  department: string | null;
  position: string | null;
  employment_type: string;
  pay_frequency: string;
  status: string;
  pay_structure: PayStructure | null;
  pay_history: PayStructure[];
  payslip_history: PayslipSummary[];
}

function formatCurrency(amount: number): string {
  return `R ${amount.toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function formatDate(d: string): string {
  return new Date(d).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' });
}

export default function EmployeeDetailPage() {
  const router = useRouter();
  const { employeeId } = router.query;

  const [employee, setEmployee] = useState<EmployeeDetail | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editForm, setEditForm] = useState<Record<string, string>>({});
  const [activeTab, setActiveTab] = useState<'details' | 'pay_history' | 'payslips'>('details');

  const loadEmployee = useCallback(async () => {
    if (!employeeId) return;
    setIsLoading(true);
    setError('');
    try {
      const res = await fetch(`/api/payroll/employees-detail?id=${employeeId}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = await res.json();
      const data = json.data ?? json;
      setEmployee(data as EmployeeDetail);
    } catch {
      setError('Failed to load employee');
    } finally {
      setIsLoading(false);
    }
  }, [employeeId]);

  useEffect(() => {
    loadEmployee();
  }, [loadEmployee]);

  function startEditing() {
    if (!employee) return;
    setEditForm({
      first_name: employee.first_name,
      last_name: employee.last_name,
      id_number: employee.id_number || '',
      tax_number: employee.tax_number || '',
      department: employee.department || '',
      position: employee.position || '',
      employment_type: employee.employment_type,
      status: employee.status,
      bank_name: employee.bank_name || '',
      bank_account_number: employee.bank_account_number || '',
      bank_branch_code: employee.bank_branch_code || '',
      basic_salary: String(employee.pay_structure?.basic_salary || 0),
      travel_allowance: String(employee.pay_structure?.travel_allowance || 0),
      housing_allowance: String(employee.pay_structure?.housing_allowance || 0),
      cell_allowance: String(employee.pay_structure?.cell_allowance || 0),
      other_allowances: String(employee.pay_structure?.other_allowances || 0),
      medical_aid_contribution: String(employee.pay_structure?.medical_aid_contribution || 0),
      retirement_fund_contribution_pct: String(employee.pay_structure?.retirement_fund_contribution_pct || 0),
    });
    setIsEditing(true);
  }

  async function handleSave() {
    if (!employee) return;
    setIsSaving(true);
    try {
      const res = await fetch(`/api/payroll/employees-detail?id=${employee.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...editForm,
          basic_salary: Number(editForm.basic_salary),
          travel_allowance: Number(editForm.travel_allowance || 0),
          housing_allowance: Number(editForm.housing_allowance || 0),
          cell_allowance: Number(editForm.cell_allowance || 0),
          other_allowances: Number(editForm.other_allowances || 0),
          medical_aid_contribution: Number(editForm.medical_aid_contribution || 0),
          retirement_fund_contribution_pct: Number(editForm.retirement_fund_contribution_pct || 0),
        }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message ?? json.message ?? `HTTP ${res.status}`);
      toast.success('Employee updated successfully');
      setIsEditing(false);
      loadEmployee();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Failed to update employee');
    } finally {
      setIsSaving(false);
    }
  }

  const inputClass = 'w-full px-3 py-1.5 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-primary)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:ring-1 focus:ring-teal-500';

  if (isLoading) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center py-16">
          <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
        </div>
      </AppLayout>
    );
  }

  if (error || !employee) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center gap-2 text-red-400 py-12">
          <AlertCircle className="h-5 w-5" />
          <span>{error || 'Employee not found'}</span>
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link
                href="/payroll/employees"
                className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] transition-colors"
              >
                <ArrowLeft className="h-5 w-5" />
              </Link>
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Users className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-[var(--ff-text-primary)]">
                  {employee.first_name} {employee.last_name}
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  {employee.employee_number} | {employee.department || 'No department'}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              {isEditing ? (
                <>
                  <button
                    onClick={handleSave}
                    disabled={isSaving}
                    className="flex items-center gap-2 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white text-sm font-medium transition-colors"
                  >
                    {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
                    Save
                  </button>
                  <button
                    onClick={() => setIsEditing(false)}
                    className="px-4 py-2 rounded-lg border border-[var(--ff-border-primary)] text-[var(--ff-text-secondary)] text-sm font-medium transition-colors hover:bg-[var(--ff-bg-tertiary)]"
                  >
                    Cancel
                  </button>
                </>
              ) : (
                <button
                  onClick={startEditing}
                  className="px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium transition-colors"
                >
                  Edit
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 flex gap-1">
            {(['details', 'pay_history', 'payslips'] as const).map(tab => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors ${
                  activeTab === tab
                    ? 'border-teal-500 text-teal-400'
                    : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
                }`}
              >
                {tab === 'details' ? 'Details' : tab === 'pay_history' ? 'Pay History' : 'Payslips'}
              </button>
            ))}
          </div>
        </div>

        <div className="p-6 max-w-4xl">
          {/* Details Tab */}
          {activeTab === 'details' && (
            <div className="space-y-8">
              {/* Personal */}
              <section>
                <h3 className="text-sm font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider mb-3">Personal Information</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {isEditing ? (
                    <>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">First Name</label><input className={inputClass} value={editForm.first_name} onChange={e => setEditForm(p => ({ ...p, first_name: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Last Name</label><input className={inputClass} value={editForm.last_name} onChange={e => setEditForm(p => ({ ...p, last_name: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">ID Number</label><input className={inputClass} value={editForm.id_number} onChange={e => setEditForm(p => ({ ...p, id_number: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Tax Number</label><input className={inputClass} value={editForm.tax_number} onChange={e => setEditForm(p => ({ ...p, tax_number: e.target.value }))} /></div>
                    </>
                  ) : (
                    <>
                      <DetailField label="First Name" value={employee.first_name} />
                      <DetailField label="Last Name" value={employee.last_name} />
                      <DetailField label="ID Number" value={employee.id_number || '-'} />
                      <DetailField label="Tax Number" value={employee.tax_number || '-'} />
                      <DetailField label="Start Date" value={formatDate(employee.start_date)} />
                      <DetailField label="Status" value={employee.status} />
                    </>
                  )}
                </div>
              </section>

              {/* Employment */}
              <section>
                <h3 className="text-sm font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider mb-3">Employment</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {isEditing ? (
                    <>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Department</label><input className={inputClass} value={editForm.department} onChange={e => setEditForm(p => ({ ...p, department: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Position</label><input className={inputClass} value={editForm.position} onChange={e => setEditForm(p => ({ ...p, position: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Employment Type</label>
                        <select className={inputClass} value={editForm.employment_type} onChange={e => setEditForm(p => ({ ...p, employment_type: e.target.value }))}>
                          <option value="permanent">Permanent</option><option value="contract">Contract</option><option value="temporary">Temporary</option>
                        </select>
                      </div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Status</label>
                        <select className={inputClass} value={editForm.status} onChange={e => setEditForm(p => ({ ...p, status: e.target.value }))}>
                          <option value="active">Active</option><option value="inactive">Inactive</option>
                        </select>
                      </div>
                    </>
                  ) : (
                    <>
                      <DetailField label="Department" value={employee.department || '-'} />
                      <DetailField label="Position" value={employee.position || '-'} />
                      <DetailField label="Employment Type" value={employee.employment_type} />
                      <DetailField label="Pay Frequency" value={employee.pay_frequency} />
                    </>
                  )}
                </div>
              </section>

              {/* Banking */}
              <section>
                <h3 className="text-sm font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider mb-3">Banking Details</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {isEditing ? (
                    <>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Bank Name</label><input className={inputClass} value={editForm.bank_name} onChange={e => setEditForm(p => ({ ...p, bank_name: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Account Number</label><input className={inputClass} value={editForm.bank_account_number} onChange={e => setEditForm(p => ({ ...p, bank_account_number: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Branch Code</label><input className={inputClass} value={editForm.bank_branch_code} onChange={e => setEditForm(p => ({ ...p, bank_branch_code: e.target.value }))} /></div>
                    </>
                  ) : (
                    <>
                      <DetailField label="Bank" value={employee.bank_name || '-'} />
                      <DetailField label="Account Number" value={employee.bank_account_number || '-'} />
                      <DetailField label="Branch Code" value={employee.bank_branch_code || '-'} />
                    </>
                  )}
                </div>
              </section>

              {/* Current Pay Structure */}
              <section>
                <h3 className="text-sm font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider mb-3">Current Pay Structure</h3>
                {employee.pay_structure ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {isEditing ? (
                      <>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Basic Salary</label><input type="number" step="0.01" className={inputClass} value={editForm.basic_salary} onChange={e => setEditForm(p => ({ ...p, basic_salary: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Travel Allowance</label><input type="number" step="0.01" className={inputClass} value={editForm.travel_allowance} onChange={e => setEditForm(p => ({ ...p, travel_allowance: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Housing Allowance</label><input type="number" step="0.01" className={inputClass} value={editForm.housing_allowance} onChange={e => setEditForm(p => ({ ...p, housing_allowance: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Cell Allowance</label><input type="number" step="0.01" className={inputClass} value={editForm.cell_allowance} onChange={e => setEditForm(p => ({ ...p, cell_allowance: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Other Allowances</label><input type="number" step="0.01" className={inputClass} value={editForm.other_allowances} onChange={e => setEditForm(p => ({ ...p, other_allowances: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Medical Aid (Employer)</label><input type="number" step="0.01" className={inputClass} value={editForm.medical_aid_contribution} onChange={e => setEditForm(p => ({ ...p, medical_aid_contribution: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Retirement Fund (%)</label><input type="number" step="0.01" className={inputClass} value={editForm.retirement_fund_contribution_pct} onChange={e => setEditForm(p => ({ ...p, retirement_fund_contribution_pct: e.target.value }))} /></div>
                      </>
                    ) : (
                      <>
                        <DetailField label="Basic Salary" value={formatCurrency(employee.pay_structure.basic_salary)} />
                        <DetailField label="Travel Allowance" value={formatCurrency(employee.pay_structure.travel_allowance)} />
                        <DetailField label="Housing Allowance" value={formatCurrency(employee.pay_structure.housing_allowance)} />
                        <DetailField label="Cell Allowance" value={formatCurrency(employee.pay_structure.cell_allowance)} />
                        <DetailField label="Other Allowances" value={formatCurrency(employee.pay_structure.other_allowances)} />
                        <DetailField label="Medical Aid (Employer)" value={formatCurrency(employee.pay_structure.medical_aid_contribution)} />
                        <DetailField label="Retirement Fund (%)" value={`${employee.pay_structure.retirement_fund_contribution_pct}%`} />
                        <DetailField label="Effective From" value={formatDate(employee.pay_structure.effective_from)} />
                      </>
                    )}
                  </div>
                ) : (
                  <p className="text-sm text-[var(--ff-text-tertiary)]">No pay structure defined</p>
                )}
              </section>
            </div>
          )}

          {/* Pay History Tab */}
          {activeTab === 'pay_history' && (
            <div>
              {employee.pay_history && employee.pay_history.length > 0 ? (
                <div className="rounded-lg border border-[var(--ff-border-primary)] overflow-hidden bg-[var(--ff-surface-primary)]">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                        <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Effective From</th>
                        <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Effective To</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Basic Salary</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Travel</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Housing</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Total Package</th>
                      </tr>
                    </thead>
                    <tbody>
                      {employee.pay_history.map((ph) => (
                        <tr key={ph.id} className="border-b border-[var(--ff-border-primary)] last:border-0">
                          <td className="py-3 px-4 text-[var(--ff-text-primary)]">{formatDate(ph.effective_from)}</td>
                          <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{ph.effective_to ? formatDate(ph.effective_to) : 'Current'}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-primary)]">{formatCurrency(ph.basic_salary)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(ph.travel_allowance)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(ph.housing_allowance)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-primary)]">
                            {formatCurrency(ph.basic_salary + ph.travel_allowance + ph.housing_allowance + ph.cell_allowance + ph.other_allowances)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <p className="text-sm text-[var(--ff-text-tertiary)] text-center py-12">No pay history available</p>
              )}
            </div>
          )}

          {/* Payslips Tab */}
          {activeTab === 'payslips' && (
            <div>
              {employee.payslip_history && employee.payslip_history.length > 0 ? (
                <div className="rounded-lg border border-[var(--ff-border-primary)] overflow-hidden bg-[var(--ff-surface-primary)]">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                        <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Period</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Gross</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">PAYE</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">UIF</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Net Pay</th>
                        <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {employee.payslip_history.map((ps) => (
                        <tr key={ps.id} className="border-b border-[var(--ff-border-primary)] last:border-0">
                          <td className="py-3 px-4 text-[var(--ff-text-primary)]">{formatDate(ps.created_at)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-primary)]">{formatCurrency(ps.gross_pay)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(ps.paye)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(ps.uif_employee)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-primary)] font-medium">{formatCurrency(ps.net_pay)}</td>
                          <td className="py-3 px-4">
                            <a
                              href={`/api/payroll/payslip-pdf?id=${ps.id}`}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-flex items-center gap-1 text-teal-400 hover:text-teal-300 text-xs font-medium transition-colors"
                            >
                              <FileText className="h-3 w-3" />
                              PDF
                            </a>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <p className="text-sm text-[var(--ff-text-tertiary)] text-center py-12">No payslips generated yet</p>
              )}
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

function DetailField({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <dt className="text-xs text-[var(--ff-text-tertiary)]">{label}</dt>
      <dd className="text-sm text-[var(--ff-text-primary)] mt-0.5">{value}</dd>
    </div>
  );
}

/**
 * Employee Detail Page
 * View/edit employee details, pay history, payslip history.
 * Route: /payroll/employees/[employeeId]
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { Users, Loader2, AlertCircle, ArrowLeft, Save, FileText } from 'lucide-react';
import Link from 'next/link';
import { notify } from '@/utils/toast';

interface PayStructure {
  id: string;
  basic_salary: number;
  travel_allowance: number;
  housing_allowance: number;
  cell_allowance: number;
  other_allowances: number;
  medical_aid_contribution: number;
  retirement_fund_contribution_pct: number;
  effective_from: string;
  effective_to: string | null;
}

interface PayslipSummary {
  id: string;
  payroll_run_id: string;
  gross_pay: number;
  paye: number;
  uif_employee: number;
  net_pay: number;
  created_at: string;
  period_start?: string;
  period_end?: string;
}

interface EmployeeDetail {
  id: string;
  employee_number: string;
  first_name: string;
  last_name: string;
  id_number: string | null;
  tax_number: string | null;
  start_date: string;
  termination_date: string | null;
  bank_name: string | null;
  bank_account_number: string | null;
  bank_branch_code: string | null;
  department: string | null;
  position: string | null;
  employment_type: string;
  pay_frequency: string;
  status: string;
  pay_structure: PayStructure | null;
  pay_history: PayStructure[];
  payslip_history: PayslipSummary[];
}

function formatCurrency(amount: number): string {
  return `R ${amount.toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function formatDate(d: string): string {
  return new Date(d).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' });
}

export default function EmployeeDetailPage() {
  const router = useRouter();
  const { employeeId } = router.query;

  const [employee, setEmployee] = useState<EmployeeDetail | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editForm, setEditForm] = useState<Record<string, string>>({});
  const [activeTab, setActiveTab] = useState<'details' | 'pay_history' | 'payslips'>('details');

  const loadEmployee = useCallback(async () => {
    if (!employeeId) return;
    setIsLoading(true);
    setError('');
    try {
      const res = await fetch(`/api/payroll/employees-detail?id=${employeeId}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = await res.json();
      const data = json.data ?? json;
      setEmployee(data as EmployeeDetail);
    } catch {
      setError('Failed to load employee');
    } finally {
      setIsLoading(false);
    }
  }, [employeeId]);

  useEffect(() => {
    loadEmployee();
  }, [loadEmployee]);

  function startEditing() {
    if (!employee) return;
    setEditForm({
      first_name: employee.first_name,
      last_name: employee.last_name,
      id_number: employee.id_number || '',
      tax_number: employee.tax_number || '',
      department: employee.department || '',
      position: employee.position || '',
      employment_type: employee.employment_type,
      status: employee.status,
      bank_name: employee.bank_name || '',
      bank_account_number: employee.bank_account_number || '',
      bank_branch_code: employee.bank_branch_code || '',
      basic_salary: String(employee.pay_structure?.basic_salary || 0),
      travel_allowance: String(employee.pay_structure?.travel_allowance || 0),
      housing_allowance: String(employee.pay_structure?.housing_allowance || 0),
      cell_allowance: String(employee.pay_structure?.cell_allowance || 0),
      other_allowances: String(employee.pay_structure?.other_allowances || 0),
      medical_aid_contribution: String(employee.pay_structure?.medical_aid_contribution || 0),
      retirement_fund_contribution_pct: String(employee.pay_structure?.retirement_fund_contribution_pct || 0),
    });
    setIsEditing(true);
  }

  async function handleSave() {
    if (!employee) return;
    setIsSaving(true);
    try {
      const res = await fetch(`/api/payroll/employees-detail?id=${employee.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...editForm,
          basic_salary: Number(editForm.basic_salary),
          travel_allowance: Number(editForm.travel_allowance || 0),
          housing_allowance: Number(editForm.housing_allowance || 0),
          cell_allowance: Number(editForm.cell_allowance || 0),
          other_allowances: Number(editForm.other_allowances || 0),
          medical_aid_contribution: Number(editForm.medical_aid_contribution || 0),
          retirement_fund_contribution_pct: Number(editForm.retirement_fund_contribution_pct || 0),
        }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message ?? json.message ?? `HTTP ${res.status}`);
      notify.success('Employee updated successfully');
      setIsEditing(false);
      loadEmployee();
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Failed to update employee');
    } finally {
      setIsSaving(false);
    }
  }

  const inputClass = 'w-full px-3 py-1.5 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-primary)] text-[var(--ff-text-primary)] text-sm focus:outline-none focus:ring-1 focus:ring-teal-500';

  if (isLoading) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center py-16">
          <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
        </div>
      </AppLayout>
    );
  }

  if (error || !employee) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center gap-2 text-red-400 py-12">
          <AlertCircle className="h-5 w-5" />
          <span>{error || 'Employee not found'}</span>
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link
                href="/payroll/employees"
                className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] transition-colors"
              >
                <ArrowLeft className="h-5 w-5" />
              </Link>
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Users className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-[var(--ff-text-primary)]">
                  {employee.first_name} {employee.last_name}
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  {employee.employee_number} | {employee.department || 'No department'}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              {isEditing ? (
                <>
                  <button
                    onClick={handleSave}
                    disabled={isSaving}
                    className="flex items-center gap-2 px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white text-sm font-medium transition-colors"
                  >
                    {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
                    Save
                  </button>
                  <button
                    onClick={() => setIsEditing(false)}
                    className="px-4 py-2 rounded-lg border border-[var(--ff-border-primary)] text-[var(--ff-text-secondary)] text-sm font-medium transition-colors hover:bg-[var(--ff-bg-tertiary)]"
                  >
                    Cancel
                  </button>
                </>
              ) : (
                <button
                  onClick={startEditing}
                  className="px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium transition-colors"
                >
                  Edit
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 flex gap-1">
            {(['details', 'pay_history', 'payslips'] as const).map(tab => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors ${
                  activeTab === tab
                    ? 'border-teal-500 text-teal-400'
                    : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
                }`}
              >
                {tab === 'details' ? 'Details' : tab === 'pay_history' ? 'Pay History' : 'Payslips'}
              </button>
            ))}
          </div>
        </div>

        <div className="p-6 max-w-4xl">
          {/* Details Tab */}
          {activeTab === 'details' && (
            <div className="space-y-8">
              {/* Personal */}
              <section>
                <h3 className="text-sm font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider mb-3">Personal Information</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {isEditing ? (
                    <>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">First Name</label><input className={inputClass} value={editForm.first_name} onChange={e => setEditForm(p => ({ ...p, first_name: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Last Name</label><input className={inputClass} value={editForm.last_name} onChange={e => setEditForm(p => ({ ...p, last_name: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">ID Number</label><input className={inputClass} value={editForm.id_number} onChange={e => setEditForm(p => ({ ...p, id_number: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Tax Number</label><input className={inputClass} value={editForm.tax_number} onChange={e => setEditForm(p => ({ ...p, tax_number: e.target.value }))} /></div>
                    </>
                  ) : (
                    <>
                      <DetailField label="First Name" value={employee.first_name} />
                      <DetailField label="Last Name" value={employee.last_name} />
                      <DetailField label="ID Number" value={employee.id_number || '-'} />
                      <DetailField label="Tax Number" value={employee.tax_number || '-'} />
                      <DetailField label="Start Date" value={formatDate(employee.start_date)} />
                      <DetailField label="Status" value={employee.status} />
                    </>
                  )}
                </div>
              </section>

              {/* Employment */}
              <section>
                <h3 className="text-sm font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider mb-3">Employment</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {isEditing ? (
                    <>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Department</label><input className={inputClass} value={editForm.department} onChange={e => setEditForm(p => ({ ...p, department: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Position</label><input className={inputClass} value={editForm.position} onChange={e => setEditForm(p => ({ ...p, position: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Employment Type</label>
                        <select className={inputClass} value={editForm.employment_type} onChange={e => setEditForm(p => ({ ...p, employment_type: e.target.value }))}>
                          <option value="permanent">Permanent</option><option value="contract">Contract</option><option value="temporary">Temporary</option>
                        </select>
                      </div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Status</label>
                        <select className={inputClass} value={editForm.status} onChange={e => setEditForm(p => ({ ...p, status: e.target.value }))}>
                          <option value="active">Active</option><option value="inactive">Inactive</option>
                        </select>
                      </div>
                    </>
                  ) : (
                    <>
                      <DetailField label="Department" value={employee.department || '-'} />
                      <DetailField label="Position" value={employee.position || '-'} />
                      <DetailField label="Employment Type" value={employee.employment_type} />
                      <DetailField label="Pay Frequency" value={employee.pay_frequency} />
                    </>
                  )}
                </div>
              </section>

              {/* Banking */}
              <section>
                <h3 className="text-sm font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider mb-3">Banking Details</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {isEditing ? (
                    <>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Bank Name</label><input className={inputClass} value={editForm.bank_name} onChange={e => setEditForm(p => ({ ...p, bank_name: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Account Number</label><input className={inputClass} value={editForm.bank_account_number} onChange={e => setEditForm(p => ({ ...p, bank_account_number: e.target.value }))} /></div>
                      <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Branch Code</label><input className={inputClass} value={editForm.bank_branch_code} onChange={e => setEditForm(p => ({ ...p, bank_branch_code: e.target.value }))} /></div>
                    </>
                  ) : (
                    <>
                      <DetailField label="Bank" value={employee.bank_name || '-'} />
                      <DetailField label="Account Number" value={employee.bank_account_number || '-'} />
                      <DetailField label="Branch Code" value={employee.bank_branch_code || '-'} />
                    </>
                  )}
                </div>
              </section>

              {/* Current Pay Structure */}
              <section>
                <h3 className="text-sm font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider mb-3">Current Pay Structure</h3>
                {employee.pay_structure ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {isEditing ? (
                      <>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Basic Salary</label><input type="number" step="0.01" className={inputClass} value={editForm.basic_salary} onChange={e => setEditForm(p => ({ ...p, basic_salary: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Travel Allowance</label><input type="number" step="0.01" className={inputClass} value={editForm.travel_allowance} onChange={e => setEditForm(p => ({ ...p, travel_allowance: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Housing Allowance</label><input type="number" step="0.01" className={inputClass} value={editForm.housing_allowance} onChange={e => setEditForm(p => ({ ...p, housing_allowance: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Cell Allowance</label><input type="number" step="0.01" className={inputClass} value={editForm.cell_allowance} onChange={e => setEditForm(p => ({ ...p, cell_allowance: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Other Allowances</label><input type="number" step="0.01" className={inputClass} value={editForm.other_allowances} onChange={e => setEditForm(p => ({ ...p, other_allowances: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Medical Aid (Employer)</label><input type="number" step="0.01" className={inputClass} value={editForm.medical_aid_contribution} onChange={e => setEditForm(p => ({ ...p, medical_aid_contribution: e.target.value }))} /></div>
                        <div><label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Retirement Fund (%)</label><input type="number" step="0.01" className={inputClass} value={editForm.retirement_fund_contribution_pct} onChange={e => setEditForm(p => ({ ...p, retirement_fund_contribution_pct: e.target.value }))} /></div>
                      </>
                    ) : (
                      <>
                        <DetailField label="Basic Salary" value={formatCurrency(employee.pay_structure.basic_salary)} />
                        <DetailField label="Travel Allowance" value={formatCurrency(employee.pay_structure.travel_allowance)} />
                        <DetailField label="Housing Allowance" value={formatCurrency(employee.pay_structure.housing_allowance)} />
                        <DetailField label="Cell Allowance" value={formatCurrency(employee.pay_structure.cell_allowance)} />
                        <DetailField label="Other Allowances" value={formatCurrency(employee.pay_structure.other_allowances)} />
                        <DetailField label="Medical Aid (Employer)" value={formatCurrency(employee.pay_structure.medical_aid_contribution)} />
                        <DetailField label="Retirement Fund (%)" value={`${employee.pay_structure.retirement_fund_contribution_pct}%`} />
                        <DetailField label="Effective From" value={formatDate(employee.pay_structure.effective_from)} />
                      </>
                    )}
                  </div>
                ) : (
                  <p className="text-sm text-[var(--ff-text-tertiary)]">No pay structure defined</p>
                )}
              </section>
            </div>
          )}

          {/* Pay History Tab */}
          {activeTab === 'pay_history' && (
            <div>
              {employee.pay_history && employee.pay_history.length > 0 ? (
                <div className="rounded-lg border border-[var(--ff-border-primary)] overflow-hidden bg-[var(--ff-surface-primary)]">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                        <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Effective From</th>
                        <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Effective To</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Basic Salary</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Travel</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Housing</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Total Package</th>
                      </tr>
                    </thead>
                    <tbody>
                      {employee.pay_history.map((ph) => (
                        <tr key={ph.id} className="border-b border-[var(--ff-border-primary)] last:border-0">
                          <td className="py-3 px-4 text-[var(--ff-text-primary)]">{formatDate(ph.effective_from)}</td>
                          <td className="py-3 px-4 text-[var(--ff-text-secondary)]">{ph.effective_to ? formatDate(ph.effective_to) : 'Current'}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-primary)]">{formatCurrency(ph.basic_salary)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(ph.travel_allowance)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(ph.housing_allowance)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-primary)]">
                            {formatCurrency(ph.basic_salary + ph.travel_allowance + ph.housing_allowance + ph.cell_allowance + ph.other_allowances)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <p className="text-sm text-[var(--ff-text-tertiary)] text-center py-12">No pay history available</p>
              )}
            </div>
          )}

          {/* Payslips Tab */}
          {activeTab === 'payslips' && (
            <div>
              {employee.payslip_history && employee.payslip_history.length > 0 ? (
                <div className="rounded-lg border border-[var(--ff-border-primary)] overflow-hidden bg-[var(--ff-surface-primary)]">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
                        <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Period</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Gross</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">PAYE</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">UIF</th>
                        <th className="text-right py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Net Pay</th>
                        <th className="text-left py-3 px-4 text-[var(--ff-text-secondary)] font-medium">Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {employee.payslip_history.map((ps) => (
                        <tr key={ps.id} className="border-b border-[var(--ff-border-primary)] last:border-0">
                          <td className="py-3 px-4 text-[var(--ff-text-primary)]">{formatDate(ps.created_at)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-primary)]">{formatCurrency(ps.gross_pay)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(ps.paye)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-secondary)]">{formatCurrency(ps.uif_employee)}</td>
                          <td className="py-3 px-4 text-right font-mono text-[var(--ff-text-primary)] font-medium">{formatCurrency(ps.net_pay)}</td>
                          <td className="py-3 px-4">
                            <a
                              href={`/api/payroll/payslip-pdf?id=${ps.id}`}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-flex items-center gap-1 text-teal-400 hover:text-teal-300 text-xs font-medium transition-colors"
                            >
                              <FileText className="h-3 w-3" />
                              PDF
                            </a>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <p className="text-sm text-[var(--ff-text-tertiary)] text-center py-12">No payslips generated yet</p>
              )}
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

function DetailField({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <dt className="text-xs text-[var(--ff-text-tertiary)]">{label}</dt>
      <dd className="text-sm text-[var(--ff-text-primary)] mt-0.5">{value}</dd>
    </div>
  );
}

/**
 * New Employee Form Page
 * Creates a new employee with personal, employment, banking, and pay details.
 * Route: /payroll/employees/new
 */

import { useState } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { Users, Loader2, ArrowLeft, Save } from 'lucide-react';
import Link from 'next/link';
import { notify } from '@/utils/toast';

interface EmployeeFormData {
  employee_number: string;
  first_name: string;
  last_name: string;
  id_number: string;
  tax_number: string;
  start_date: string;
  department: string;
  position: string;
  employment_type: string;
  pay_frequency: string;
  bank_name: string;
  bank_account_number: string;
  bank_branch_code: string;
  basic_salary: string;
  travel_allowance: string;
  housing_allowance: string;
  cell_allowance: string;
  other_allowances: string;
  medical_aid_contribution: string;
  retirement_fund_contribution_pct: string;
}

const INITIAL_FORM: EmployeeFormData = {
  employee_number: '',
  first_name: '',
  last_name: '',
  id_number: '',
  tax_number: '',
  start_date: new Date().toISOString().split('T')[0] || '',
  department: '',
  position: '',
  employment_type: 'permanent',
  pay_frequency: 'monthly',
  bank_name: '',
  bank_account_number: '',
  bank_branch_code: '',
  basic_salary: '',
  travel_allowance: '0',
  housing_allowance: '0',
  cell_allowance: '0',
  other_allowances: '0',
  medical_aid_contribution: '0',
  retirement_fund_contribution_pct: '0',
};

const SA_BANKS = [
  'ABSA Bank',
  'Capitec Bank',
  'First National Bank (FNB)',
  'Investec',
  'Nedbank',
  'Standard Bank',
  'TymeBank',
  'African Bank',
  'Discovery Bank',
  'Other',
];

export default function NewEmployeePage() {
  const router = useRouter();
  const [form, setForm] = useState<EmployeeFormData>(INITIAL_FORM);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [fieldErrors, setFieldErrors] = useState<Partial<Record<keyof EmployeeFormData, string>>>({});

  function updateField(field: keyof EmployeeFormData, value: string) {
    setForm(prev => ({ ...prev, [field]: value }));
    if (fieldErrors[field]) {
      setFieldErrors(prev => ({ ...prev, [field]: undefined }));
    }
  }

  function validate(): boolean {
    const errors: Partial<Record<keyof EmployeeFormData, string>> = {};
    if (!form.employee_number.trim()) errors.employee_number = 'Employee number is required';
    if (!form.first_name.trim()) errors.first_name = 'First name is required';
    if (!form.last_name.trim()) errors.last_name = 'Last name is required';
    if (!form.start_date) errors.start_date = 'Start date is required';
    if (!form.basic_salary || isNaN(Number(form.basic_salary)) || Number(form.basic_salary) <= 0) {
      errors.basic_salary = 'Valid basic salary is required';
    }
    if (form.id_number && form.id_number.length !== 13) {
      errors.id_number = 'SA ID number must be 13 digits';
    }
    setFieldErrors(errors);
    return Object.keys(errors).length === 0;
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!validate()) return;

    setIsSubmitting(true);
    try {
      const res = await fetch('/api/payroll/employees', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...form,
          basic_salary: Number(form.basic_salary),
          travel_allowance: Number(form.travel_allowance || 0),
          housing_allowance: Number(form.housing_allowance || 0),
          cell_allowance: Number(form.cell_allowance || 0),
          other_allowances: Number(form.other_allowances || 0),
          medical_aid_contribution: Number(form.medical_aid_contribution || 0),
          retirement_fund_contribution_pct: Number(form.retirement_fund_contribution_pct || 0),
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message ?? json.message ?? `HTTP ${res.status}`);

      toast.success('Employee created successfully');
      await router.push('/payroll/employees');
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Failed to create employee');
    } finally {
      setIsSubmitting(false);
    }
  }

  const inputClass = (field: keyof EmployeeFormData) =>
    `w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border ${
      fieldErrors[field] ? 'border-red-500' : 'border-[var(--ff-border-primary)]'
    } text-[var(--ff-text-primary)] text-sm focus:outline-none focus:ring-1 focus:ring-teal-500`;

  const labelClass = 'block text-sm font-medium text-[var(--ff-text-secondary)] mb-1';

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-primary)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link
                href="/payroll/employees"
                className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-secondary)] transition-colors"
              >
                <ArrowLeft className="h-5 w-5" />
              </Link>
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Users className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-xl font-semibold text-[var(--ff-text-primary)]">New Employee</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Add a new payroll employee</p>
              </div>
            </div>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 max-w-4xl">
          {/* Personal Details */}
          <div className="mb-8">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Personal Details</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className={labelClass}>Employee Number *</label>
                <input type="text" value={form.employee_number} onChange={(e) => updateField('employee_number', e.target.value)} className={inputClass('employee_number')} placeholder="EMP001" />
                {fieldErrors.employee_number && <p className="text-xs text-red-400 mt-1">{fieldErrors.employee_number}</p>}
              </div>
              <div />
              <div>
                <label className={labelClass}>First Name *</label>
                <input type="text" value={form.first_name} onChange={(e) => updateField('first_name', e.target.value)} className={inputClass('first_name')} />
                {fieldErrors.first_name && <p className="text-xs text-red-400 mt-1">{fieldErrors.first_name}</p>}
              </div>
              <div>
                <label className={labelClass}>Last Name *</label>
                <input type="text" value={form.last_name} onChange={(e) => updateField('last_name', e.target.value)} className={inputClass('last_name')} />
                {fieldErrors.last_name && <p className="text-xs text-red-400 mt-1">{fieldErrors.last_name}</p>}
              </div>
              <div>
                <label className={labelClass}>SA ID Number</label>
                <input type="text" value={form.id_number} onChange={(e) => updateField('id_number', e.target.value)} className={inputClass('id_number')} placeholder="13 digits" maxLength={13} />
                {fieldErrors.id_number && <p className="text-xs text-red-400 mt-1">{fieldErrors.id_number}</p>}
              </div>
              <div>
                <label className={labelClass}>Tax Number</label>
                <input type="text" value={form.tax_number} onChange={(e) => updateField('tax_number', e.target.value)} className={inputClass('tax_number')} />
              </div>
            </div>
          </div>

          {/* Employment Details */}
          <div className="mb-8">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Employment Details</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className={labelClass}>Start Date *</label>
                <input type="date" value={form.start_date} onChange={(e) => updateField('start_date', e.target.value)} className={inputClass('start_date')} />
                {fieldErrors.start_date && <p className="text-xs text-red-400 mt-1">{fieldErrors.start_date}</p>}
              </div>
              <div>
                <label className={labelClass}>Department</label>
                <input type="text" value={form.department} onChange={(e) => updateField('department', e.target.value)} className={inputClass('department')} />
              </div>
              <div>
                <label className={labelClass}>Position</label>
                <input type="text" value={form.position} onChange={(e) => updateField('position', e.target.value)} className={inputClass('position')} />
              </div>
              <div>
                <label className={labelClass}>Employment Type</label>
                <select value={form.employment_type} onChange={(e) => updateField('employment_type', e.target.value)} className={inputClass('employment_type')}>
                  <option value="permanent">Permanent</option>
                  <option value="contract">Contract</option>
                  <option value="temporary">Temporary</option>
                </select>
              </div>
              <div>
                <label className={labelClass}>Pay Frequency</label>
                <select value={form.pay_frequency} onChange={(e) => updateField('pay_frequency', e.target.value)} className={inputClass('pay_frequency')}>
                  <option value="monthly">Monthly</option>
                  <option value="weekly">Weekly</option>
                </select>
              </div>
            </div>
          </div>

          {/* Banking Details */}
          <div className="mb-8">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Banking Details</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className={labelClass}>Bank Name</label>
                <select value={form.bank_name} onChange={(e) => updateField('bank_name', e.target.value)} className={inputClass('bank_name')}>
                  <option value="">Select bank...</option>
                  {SA_BANKS.map(bank => (
                    <option key={bank} value={bank}>{bank}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className={labelClass}>Account Number</label>
                <input type="text" value={form.bank_account_number} onChange={(e) => updateField('bank_account_number', e.target.value)} className={inputClass('bank_account_number')} />
              </div>
              <div>
                <label className={labelClass}>Branch Code</label>
                <input type="text" value={form.bank_branch_code} onChange={(e) => updateField('bank_branch_code', e.target.value)} className={inputClass('bank_branch_code')} />
              </div>
            </div>
          </div>

          {/* Pay Structure */}
          <div className="mb-8">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Pay Structure</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className={labelClass}>Basic Salary (Monthly) *</label>
                <input type="number" step="0.01" min="0" value={form.basic_salary} onChange={(e) => updateField('basic_salary', e.target.value)} className={inputClass('basic_salary')} placeholder="0.00" />
                {fieldErrors.basic_salary && <p className="text-xs text-red-400 mt-1">{fieldErrors.basic_salary}</p>}
              </div>
              <div>
                <label className={labelClass}>Travel Allowance</label>
                <input type="number" step="0.01" min="0" value={form.travel_allowance} onChange={(e) => updateField('travel_allowance', e.target.value)} className={inputClass('travel_allowance')} />
              </div>
              <div>
                <label className={labelClass}>Housing Allowance</label>
                <input type="number" step="0.01" min="0" value={form.housing_allowance} onChange={(e) => updateField('housing_allowance', e.target.value)} className={inputClass('housing_allowance')} />
              </div>
              <div>
                <label className={labelClass}>Cell Allowance</label>
                <input type="number" step="0.01" min="0" value={form.cell_allowance} onChange={(e) => updateField('cell_allowance', e.target.value)} className={inputClass('cell_allowance')} />
              </div>
              <div>
                <label className={labelClass}>Other Allowances</label>
                <input type="number" step="0.01" min="0" value={form.other_allowances} onChange={(e) => updateField('other_allowances', e.target.value)} className={inputClass('other_allowances')} />
              </div>
              <div>
                <label className={labelClass}>Medical Aid (Employer Contribution)</label>
                <input type="number" step="0.01" min="0" value={form.medical_aid_contribution} onChange={(e) => updateField('medical_aid_contribution', e.target.value)} className={inputClass('medical_aid_contribution')} />
              </div>
              <div>
                <label className={labelClass}>Retirement Fund Contribution (%)</label>
                <input type="number" step="0.01" min="0" max="27.5" value={form.retirement_fund_contribution_pct} onChange={(e) => updateField('retirement_fund_contribution_pct', e.target.value)} className={inputClass('retirement_fund_contribution_pct')} />
              </div>
            </div>
          </div>

          {/* Submit */}
          <div className="flex items-center gap-3 pt-4 border-t border-[var(--ff-border-primary)]">
            <button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center gap-2 px-6 py-2.5 rounded-lg bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white text-sm font-medium transition-colors"
            >
              {isSubmitting ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Save className="h-4 w-4" />
              )}
              Create Employee
            </button>
            <Link
              href="/payroll/employees"
              className="px-6 py-2.5 rounded-lg border border-[var(--ff-border-primary)] text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-tertiary)] text-sm font-medium transition-colors"
            >
              Cancel
            </Link>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

