/**
 * Bank Rules Seed API
 * POST /api/accounting/bank-rules-seed
 *   Seed categorisation rules from a Category Map (JSON array).
 *
 * Body: { entries: [{ originalCategory, standardCategory, glCode }] }
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

interface CategoryMapEntry {
  originalCategory: string;
  standardCategory: string;
  glCode: number | string;
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const userId = req.user.id;
    const { entries } = req.body as { entries: CategoryMapEntry[] };

    if (!Array.isArray(entries) || entries.length === 0) {
      return apiResponse.badRequest(res, 'entries array is required');
    }

    let created = 0;
    let skipped = 0;
    const missingGlCodes: (number | string)[] = [];

    for (const entry of entries) {
      const pattern = String(entry.originalCategory || '').toLowerCase().trim();
      if (!pattern) { skipped++; continue; }

      const glCode = String(entry.glCode).trim();
      if (!glCode) { skipped++; continue; }

      // Look up GL account by account_code
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const glRows = (await sql`
        SELECT id FROM gl_accounts WHERE account_code = ${glCode} LIMIT 1
      `) as any[];

      if (glRows.length === 0) {
        missingGlCodes.push(entry.glCode);
        skipped++;
        continue;
      }

      const glAccountId = String(glRows[0].id);
      const ruleName = String(entry.standardCategory || entry.originalCategory).trim();

      // UPSERT — skip if match_pattern already exists
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const existing = (await sql`
        SELECT id FROM bank_categorisation_rules
        WHERE LOWER(match_pattern) = ${pattern} LIMIT 1
      `) as any[];

      if (existing.length > 0) {
        skipped++;
        continue;
      }

      await sql`
        INSERT INTO bank_categorisation_rules (
          rule_name, match_field, match_type, match_pattern,
          gl_account_id, auto_create_entry, priority, created_by
        ) VALUES (
          ${ruleName}, 'description', 'contains', ${pattern},
          ${glAccountId}::UUID, false, 100, ${userId}
        )
      `;
      created++;
    }

    log.info('Seeded bank categorisation rules', { created, skipped, missingGlCodes: missingGlCodes.length }, 'accounting');

    return apiResponse.success(res, {
      created,
      skipped,
      missingGlCodes: missingGlCodes.length > 0 ? missingGlCodes : undefined,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to seed bank rules';
    log.error('Failed to seed bank rules', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * Cross-Module GL Integration Hooks
 * - Asset depreciation → DR Depreciation Expense, CR Accumulated Depreciation
 *
 * NOTE: postPurchaseOrderToGL is stubbed — purchase_orders table is not available
 * in the standalone Accounting app.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const ACCOUNTS = {
  ACCUM_DEPRECIATION: '1230',
  DEPRECIATION_EXPENSE: '5800',
} as const;

async function getAccountId(code: string): Promise<string> {
  const rows = (await sql`SELECT id FROM gl_accounts WHERE account_code = ${code} LIMIT 1`) as Row[];
  if (!rows[0]) throw new Error(`GL account ${code} not found`);
  return String(rows[0].id);
}

/**
 * Stub: purchase_orders table not available in standalone Accounting app.
 * Returns null without performing any GL posting.
 */
export async function postPurchaseOrderToGL(
  _poId: string,
  _userId: string
): Promise<string | null> {
  log.warn(
    'postPurchaseOrderToGL: purchase_orders table is not available in standalone accounting app',
    undefined,
    'accounting'
  );
  return null;
}

// ── Asset Depreciation → GL ────────────────────────────────────────────────

export async function postAssetDepreciationToGL(
  assetId: string,
  depreciationAmount: number,
  userId: string
): Promise<string | null> {
  try {
    if (depreciationAmount <= 0) return null;

    const asset = (await sql`
      SELECT id, asset_number, name FROM assets WHERE id = ${assetId}
    `) as Row[];

    if (!asset[0]) {
      log.warn('Asset not found for depreciation GL', { assetId }, 'accounting');
      return null;
    }

    const depExpenseId = await getAccountId(ACCOUNTS.DEPRECIATION_EXPENSE);
    const accumDepId = await getAccountId(ACCOUNTS.ACCUM_DEPRECIATION);

    const entry = (await sql`
      INSERT INTO gl_journal_entries (
        entry_number, entry_date, description, source, status, created_by
      ) VALUES (
        ${`DEP-${asset[0].asset_number}-${new Date().toISOString().slice(0, 7)}`}, CURRENT_DATE,
        ${`Depreciation: ${asset[0].name} (${asset[0].asset_number})`},
        'auto_depreciation', 'posted', ${userId}
      ) RETURNING id
    `) as Row[];

    const entryId = String(entry[0].id);

    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${entryId}::UUID, ${depExpenseId}::UUID, ${depreciationAmount}, 0,
        ${`Depreciation: ${asset[0].asset_number}`})
    `;
    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${entryId}::UUID, ${accumDepId}::UUID, 0, ${depreciationAmount},
        ${`Depreciation: ${asset[0].asset_number}`})
    `;

    await sql`
      UPDATE assets SET
        accumulated_depreciation = COALESCE(accumulated_depreciation, 0) + ${depreciationAmount},
        current_book_value = COALESCE(purchase_price, 0) - (COALESCE(accumulated_depreciation, 0) + ${depreciationAmount}),
        updated_at = NOW()
      WHERE id = ${assetId}
    `;

    log.info('Asset depreciation GL posted', { assetId, entryId, depreciationAmount }, 'accounting');
    return entryId;
  } catch (err) {
    log.error('Failed to post asset depreciation to GL', { assetId, error: err }, 'accounting');
    return null;
  }
}

