 * // 🟢 WORKING: Optimized single-query auth
 */
export function withAuth(handler: AuthenticatedHandler): NextApiHandler {
  return async (req: NextApiRequest, res: NextApiResponse) => {
    try {
      // Extract token
      const token = extractToken(req);
      if (!token) {
        return res.status(401).json({
          success: false,
          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
        });
      }

      // Verify JWT (in-memory operation, fast)
      const payload = await verifyToken(token);
      if (!payload) {
        return res.status(401).json({
          success: false,
          error: { code: 'INVALID_TOKEN', message: 'Invalid or expired token' },
        });
      }

      // Hash token for session lookup
      const crypto = await import('crypto');
      const tokenHash = crypto.createHash('sha256').update(token).digest('hex');

      // Single optimized query: validate session + get user (replaces 2 queries)
      const user = await getUserAndValidateSession(
        payload.sub,
        payload.sessionId,
        tokenHash
      );

      if (!user) {
        // Could be: invalid session, expired session, inactive user, or user deleted
        return res.status(401).json({
          success: false,
          error: { code: 'SESSION_INVALID', message: 'Session expired or invalid' },
        });
      }

      // Attach user and session to request
      (req as AuthenticatedNextApiRequest).user = user;
      (req as AuthenticatedNextApiRequest).sessionId = payload.sessionId;

      // Call the actual handler
      return handler(req as AuthenticatedNextApiRequest, res);
    } catch (error) {
      log.error('Auth middleware error', error instanceof Error ? { message: error.message, stack: error.stack } : { error }, 'AuthMiddleware');
      return res.status(500).json({
        success: false,
        error: { code: 'AUTH_ERROR', message: 'Authentication error' },
      });
    }
  };
}

/**
 * Role-based access control middleware
 * Must be used after withAuth
 */
export function withRole(requiredRole: AuthRole) {
  return (handler: AuthenticatedHandler): AuthenticatedHandler => {
    return async (req: NextApiRequest, res: NextApiResponse) => {
      const authReq = req as AuthenticatedNextApiRequest;
      const userRoleLevel = ROLE_HIERARCHY[authReq.user.role] || 0;
      const requiredRoleLevel = ROLE_HIERARCHY[requiredRole] || 0;

      if (userRoleLevel < requiredRoleLevel) {
        return res.status(403).json({
          success: false,
          error: {
            code: 'FORBIDDEN',
            message: `This action requires ${requiredRole} role or higher`,
          },
        });
      }

      return handler(req, res);
    };
  };
}

/**
 * Permission-based access control middleware
 * Must be used after withAuth
 */
export function withPermission(requiredPermission: string) {
  return (handler: AuthenticatedHandler): AuthenticatedHandler => {
    return async (req: NextApiRequest, res: NextApiResponse) => {
      const authReq = req as AuthenticatedNextApiRequest;
      const hasPermission =
        authReq.user.permissions.includes('all') ||
        authReq.user.permissions.includes(requiredPermission);

      if (!hasPermission) {
        return res.status(403).json({
          success: false,
          error: {
            code: 'FORBIDDEN',
            message: `Missing required permission: ${requiredPermission}`,
          },
        });
      }

      return handler(req, res);
    };
  };
}

/**
 * Combined role and permission check
 */
export function withRoleAndPermission(
  requiredRole: AuthRole,
  requiredPermission: string
) {
  return (handler: AuthenticatedHandler): AuthenticatedHandler => {
    return withRole(requiredRole)(withPermission(requiredPermission)(handler));
  };
}

/**
 * Optional auth - attaches user if authenticated, but doesn't require it
 * // 🟢 WORKING: Same optimization applied to optional auth
 */
export function withOptionalAuth(
  handler: (
    req: NextApiRequest & { user?: AuthUser; sessionId?: string },
    res: NextApiResponse
  ) => Promise<void> | void
): NextApiHandler {
  return async (req: NextApiRequest, res: NextApiResponse) => {
    try {
      const token = extractToken(req);
      if (token) {
        const payload = await verifyToken(token);
        if (payload) {
          const crypto = await import('crypto');
          const tokenHash = crypto.createHash('sha256').update(token).digest('hex');

          const user = await getUserAndValidateSession(
            payload.sub,
            payload.sessionId,
            tokenHash
          );

          if (user) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (req as any).user = user;
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (req as any).sessionId = payload.sessionId;
          }
        }
      }

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      return handler(req as any, res);
    } catch (error) {
      // On error, just proceed without user
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      return handler(req as any, res);
    }
  };
}

/**
 * Helper to check if user has a specific role or higher
 */
export function hasRole(user: AuthUser, requiredRole: AuthRole): boolean {
  const userLevel = ROLE_HIERARCHY[user.role] || 0;
  const requiredLevel = ROLE_HIERARCHY[requiredRole] || 0;
  return userLevel >= requiredLevel;
}

/**
 * Helper to check if user has a specific permission
 */
export function hasPermission(user: AuthUser, permission: string): boolean {
  return user.permissions.includes('all') || user.permissions.includes(permission);
}

/**
 * GET /api/auth/me
 * Returns the currently authenticated user from the JWT cookie.
 * Uses a single JOIN query for performance (session + user in one round-trip).
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { verifyToken } from '@/lib/auth/jwt';
import { getUserAndValidateSession, AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import { createHash } from 'crypto';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET']);
  }

  // Extract token from cookie or Authorization header
  const cookieToken = req.cookies[AUTH_COOKIE_NAME];
  const authHeader = req.headers.authorization;
  const bearerToken = authHeader?.startsWith('Bearer ') ? authHeader.substring(7) : null;
  const token = cookieToken ?? bearerToken;

  if (!token) {
    return res.status(401).json({
      success: false,
      error: { code: 'UNAUTHORIZED', message: 'Not authenticated' },
    });
  }

  try {
    const payload = await verifyToken(token);
    if (!payload) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Invalid or expired token' },
      });
    }

    const tokenHash = createHash('sha256').update(token).digest('hex');
    const user = await getUserAndValidateSession(payload.sub, payload.sessionId, tokenHash);

    if (!user) {
      return res.status(401).json({
        success: false,
        error: { code: 'SESSION_INVALID', message: 'Session expired or invalid' },
      });
    }

    return apiResponse.success(res, { user });
  } catch (err) {
    log.error('Failed to get current user', err instanceof Error ? { message: err.message } : { err }, 'auth/me');
    return apiResponse.internalError(res, err);
  }
}

/**
 * Bank Transaction Attachments API
 *
 * GET  /api/accounting/bank-tx-attachments?bankTransactionId=<uuid>
 *   → List all attachments for a bank transaction, newest first.
 *
 * POST /api/accounting/bank-tx-attachments
 *   Body: { bankTransactionId, fileName, fileData (base64 data URL), fileSize? }
 *   → Store an attachment. Small receipts (≤ 2 MB) are kept as data URLs in file_url.
 *
 * DELETE /api/accounting/bank-tx-attachments?id=<uuid>
 *   → Remove a single attachment record.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// ── Local Types ───────────────────────────────────────────────────────────────

// Neon's sql tagged template returns a union type. Casting through unknown[]
// is the project-standard pattern (see bankReconciliationService.ts Row = any).
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type SqlRow = Record<string, any>;

interface PostBody {
  bankTransactionId?: string;
  fileName?: string;
  fileData?: string; // base64 data URL: "data:<mime>;base64,<data>"
  fileSize?: number;
}

// ── Constants ─────────────────────────────────────────────────────────────────

/** 2 MB limit — data URLs expand ~33 % in transit, so clamp at 2 MB of raw bytes */
const MAX_FILE_SIZE_BYTES = 2 * 1024 * 1024;

/** Allowed MIME types derived from the data URL header */
const ALLOWED_MIME_TYPES = ['image/jpeg', 'image/png', 'application/pdf'];

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Extract the MIME type from a base64 data URL string */
function extractMime(dataUrl: string): string | null {
  const match = dataUrl.match(/^data:([a-zA-Z0-9]+\/[a-zA-Z0-9.+-]+);base64,/);
  return match ? match[1] ?? null : null;
}

/** Rough byte size estimate for a base64-encoded data URL */
function estimateDataUrlBytes(dataUrl: string): number {
  const base64Part = dataUrl.split(',')[1] ?? '';
  return Math.ceil((base64Part.length * 3) / 4);
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  // @ts-expect-error — auth middleware attaches user
  const userId: string | null = req.user?.id ?? req.user?.userId ?? null;

  // ── GET ────────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    const { bankTransactionId } = req.query;

    if (!bankTransactionId || typeof bankTransactionId !== 'string') {
      return apiResponse.badRequest(res, 'bankTransactionId query param is required');
    }

    const rows = (await sql`
      SELECT
        id,
        bank_transaction_id,
        file_url,
        file_name,
        file_size,
        uploaded_by,
        created_at
      FROM bank_transaction_attachments
      WHERE bank_transaction_id = ${bankTransactionId}::UUID
      ORDER BY created_at DESC
    `) as SqlRow[];

    log.info('Listed bank tx attachments', { bankTransactionId, count: rows.length }, 'bank-tx-attachments');
    return apiResponse.success(res, rows);
  }

  // ── POST ───────────────────────────────────────────────────────────────────
  if (req.method === 'POST') {
    const { bankTransactionId, fileName, fileData, fileSize } = req.body as PostBody;

    if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
    if (!fileName) return apiResponse.badRequest(res, 'fileName is required');
    if (!fileData || typeof fileData !== 'string') {
      return apiResponse.badRequest(res, 'fileData (base64 data URL) is required');
    }

    // Validate MIME type
    const mime = extractMime(fileData);
    if (!mime || !ALLOWED_MIME_TYPES.includes(mime)) {
      return apiResponse.badRequest(res, `File type not allowed. Accepted: ${ALLOWED_MIME_TYPES.join(', ')}`);
    }

    // Validate file size
    const byteSize = fileSize ?? estimateDataUrlBytes(fileData);
    if (byteSize > MAX_FILE_SIZE_BYTES) {
      return apiResponse.badRequest(res, 'File exceeds the 2 MB size limit');
    }

    const insertRows = (await sql`
      INSERT INTO bank_transaction_attachments
        (bank_transaction_id, file_url, file_name, file_size, uploaded_by)
      VALUES
        (
          ${bankTransactionId}::UUID,
          ${fileData},
          ${fileName},
          ${byteSize},
          ${userId}::UUID
        )
      RETURNING
        id, bank_transaction_id, file_url, file_name, file_size, uploaded_by, created_at
    `) as SqlRow[];

    const attachment = insertRows[0];
    log.info('Uploaded bank tx attachment', { bankTransactionId, fileName, byteSize }, 'bank-tx-attachments');
    return apiResponse.created(res, attachment, 'Attachment uploaded');
  }

  // ── DELETE ─────────────────────────────────────────────────────────────────
  if (req.method === 'DELETE') {
    const { id } = req.query;

    if (!id || typeof id !== 'string') {
      return apiResponse.badRequest(res, 'id query param is required');
    }

    const deleteRows = (await sql`
      DELETE FROM bank_transaction_attachments
      WHERE id = ${id}::UUID
      RETURNING id
    `) as SqlRow[];

    if (!deleteRows || deleteRows.length === 0) {
      return apiResponse.notFound(res, 'Attachment', id);
    }

    log.info('Deleted bank tx attachment', { id }, 'bank-tx-attachments');
    return apiResponse.success(res, { deleted: id });
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * Accounting Documents API
 * GET  /api/accounting/documents?entity_type=...&entity_id=...  — List documents (direct + cross-linked)
 * POST /api/accounting/documents  (multipart form-data)          — Upload document
 * DELETE /api/accounting/documents?id=...                        — Soft-delete document
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import formidable from 'formidable';
import fs from 'fs';
import { vfStorage } from '@/services/vfStorageAdapter';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import type {
  ProcurementDocument,
  LinkedDocument,
  AccountingEntityType,
  AccountingDocumentType,
} from '@/types/procurement/document.types';

export const config = {
  api: { bodyParser: false },
};

const VALID_ENTITY_TYPES: AccountingEntityType[] = [
  'supplier_invoice',
  'supplier_payment',
  'customer_invoice',
  'customer_payment',
  'credit_note',
];

const VALID_DOCUMENT_TYPES: AccountingDocumentType[] = [
  'proof_of_payment',
  'bank_statement',
  'remittance_advice',
  'credit_note_doc',
  'invoice',
  'receipt',
  'other',
];

const ALLOWED_MIME_TYPES = [
  'application/pdf',
  'image/jpeg',
  'image/png',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
];

const MAX_FILE_SIZE = 20 * 1024 * 1024; // 20MB

function validateMagicBytes(buffer: Buffer): boolean {
  if (buffer.length < 4) return false;
  const hex = buffer.subarray(0, 8).toString('hex').toUpperCase();
  if (hex.startsWith('FFD8FF')) return true;   // JPEG
  if (hex.startsWith('89504E47')) return true;  // PNG
  if (hex.startsWith('25504446')) return true;  // PDF
  if (hex.startsWith('504B0304')) return true;  // ZIP (docx/xlsx)
  return false;
}

function parseForm(req: NextApiRequest): Promise<{ fields: formidable.Fields; files: formidable.Files }> {
  return new Promise((resolve, reject) => {
    const form = formidable({ maxFileSize: MAX_FILE_SIZE, keepExtensions: true });
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

function mapRow(row: Record<string, unknown>, source: 'direct' | 'linked' = 'direct', linkReason?: string): LinkedDocument {
  return {
    id: row.id as string,
    entityType: row.entity_type as string,
    entityId: row.entity_id as string,
    documentType: row.document_type as AccountingDocumentType,
    documentName: row.document_name as string,
    fileUrl: row.file_url as string,
    filePath: (row.file_path as string) || undefined,
    fileSize: (row.file_size as number) || undefined,
    mimeType: (row.mime_type as string) || undefined,
    uploadedBy: row.uploaded_by as string,
    uploadedByName: (row.uploaded_by_name as string) || undefined,
    uploadedAt: new Date(row.uploaded_at as string).toISOString(),
    notes: (row.notes as string) || undefined,
    isActive: row.is_active as boolean,
    source,
    linkReason,
  };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const user = (req as NextApiRequest & { user: { id: string; name: string; email: string } }).user;

  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res, user);
  if (req.method === 'DELETE') return handleDelete(req, res);

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

/** GET — List direct + cross-linked documents for an accounting entity */
async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const entityType = req.query.entity_type as string;
  const entityId = req.query.entity_id as string;

  if (!entityType || !entityId) {
    return apiResponse.badRequest(res, 'Missing required query params: entity_type, entity_id');
  }

  if (!VALID_ENTITY_TYPES.includes(entityType as AccountingEntityType)) {
    return apiResponse.badRequest(res, `Invalid entity_type. Allowed: ${VALID_ENTITY_TYPES.join(', ')}`);
  }

  // Direct documents
  const directRows = await sql`
    SELECT * FROM procurement_documents
    WHERE entity_type = ${entityType}
      AND entity_id = ${entityId}::uuid
      AND is_active = true
    ORDER BY uploaded_at DESC
  `;

  // Cross-linked documents (via document_links)
  const linkedRows = await sql`
    SELECT pd.*, dl.link_reason
    FROM document_links dl
    JOIN procurement_documents pd ON pd.id = dl.document_id
    WHERE dl.linked_entity_type = ${entityType}
      AND dl.linked_entity_id = ${entityId}::uuid
      AND pd.is_active = true
    ORDER BY pd.uploaded_at DESC
  `;

  const results: LinkedDocument[] = [
    ...directRows.map(r => mapRow(r as Record<string, unknown>, 'direct')),
    ...linkedRows.map(r => mapRow(r as Record<string, unknown>, 'linked', (r as Record<string, unknown>).link_reason as string)),
  ];

  return apiResponse.success(res, results);
}

/** POST — Upload a document to an accounting entity */
async function handlePost(
  req: NextApiRequest,
  res: NextApiResponse,
  user: { id: string; name: string; email: string }
) {
  let tempFilePath: string | null = null;

  try {
    const { fields, files } = await parseForm(req);

    const entityType = (Array.isArray(fields.entity_type) ? fields.entity_type[0] : fields.entity_type) as string;
    const entityId = (Array.isArray(fields.entity_id) ? fields.entity_id[0] : fields.entity_id) as string;
    const documentType = ((Array.isArray(fields.document_type) ? fields.document_type[0] : fields.document_type) || 'other') as string;
    const notes = (Array.isArray(fields.notes) ? fields.notes[0] : fields.notes) as string | undefined;

    if (!entityType || !entityId) {
      return apiResponse.badRequest(res, 'Missing required fields: entity_type, entity_id');
    }
    if (!VALID_ENTITY_TYPES.includes(entityType as AccountingEntityType)) {
      return apiResponse.badRequest(res, `Invalid entity_type. Allowed: ${VALID_ENTITY_TYPES.join(', ')}`);
    }
    if (!VALID_DOCUMENT_TYPES.includes(documentType as AccountingDocumentType)) {
      return apiResponse.badRequest(res, `Invalid document_type. Allowed: ${VALID_DOCUMENT_TYPES.join(', ')}`);
    }

    const fileField = files.file;
    const file = Array.isArray(fileField) ? fileField[0] : fileField;
    if (!file) {
      return apiResponse.badRequest(res, 'No file uploaded');
    }

    tempFilePath = file.filepath;

    if (!ALLOWED_MIME_TYPES.includes(file.mimetype || '')) {
      return apiResponse.badRequest(res, `File type not allowed: ${file.mimetype}. Allowed: PDF, JPEG, PNG, DOCX, XLSX`);
    }
    if (file.size > MAX_FILE_SIZE) {
      return apiResponse.badRequest(res, 'File too large. Maximum size: 20MB');
    }

    const buffer = await fs.promises.readFile(file.filepath);
    if (!validateMagicBytes(buffer)) {
      return apiResponse.badRequest(res, 'File content does not match declared type');
    }

    // Upload to VF Storage: accounting/{entity_type}/{entityId}_{filename}
    const fileName = file.originalFilename || `document_${Date.now()}`;
    const storageName = `${entityId}_${fileName}`;
    const result = await vfStorage.uploadFile(buffer, 'accounting', entityType, storageName);

    // Insert DB record
    const [row] = await sql`
      INSERT INTO procurement_documents (
        entity_type, entity_id, document_type, document_name,
        file_url, file_path, file_size, mime_type,
        uploaded_by, uploaded_by_name, notes
      ) VALUES (
        ${entityType}, ${entityId}::uuid, ${documentType}, ${fileName},
        ${result.url}, ${result.path}, ${file.size}, ${file.mimetype || ''},
        ${user.email}, ${user.name}, ${notes || null}
      )
      RETURNING *
    `;

    const docId = (row as Record<string, unknown>).id as string;

    // Auto-link: if supplier_invoice, create cross-links to PO/GRN
    if (entityType === 'supplier_invoice') {
      await autoLinkSupplierInvoice(docId, entityId);
    }

    log.info('Accounting document uploaded', {
      data: { entityType, entityId, documentType, fileName },
    }, 'accounting-docs');

    return apiResponse.created(res, mapRow(row as Record<string, unknown>, 'direct'));
  } catch (error) {
    const errMsg = error instanceof Error ? error.message : String(error);
    log.error('Accounting document upload error', { error }, 'accounting-docs');
    return apiResponse.internalError(res, error, `Failed to upload document: ${errMsg}`);
  } finally {
    if (tempFilePath) {
      await fs.promises.unlink(tempFilePath).catch((e) =>
        log.debug('Temp file cleanup failed', { error: e instanceof Error ? e.message : 'unknown' }, 'accounting')
      );
    }
  }
}

/**
 * Auto-link a newly uploaded supplier_invoice doc to related PO/GRN,
 * and create reverse links so existing PO/GRN docs appear on the invoice.
 */
async function autoLinkSupplierInvoice(docId: string, invoiceId: string) {
  try {
    // Look up FK references on the invoice
    const [invoice] = await sql`
      SELECT purchase_order_id, grn_id
      FROM sage_supplier_invoices
      WHERE id = ${invoiceId}::uuid
    `;

    if (!invoice) return;

    const poId = invoice.purchase_order_id as string | null;
    const grnId = invoice.grn_id as string | null;

    // Forward links: this doc -> PO/GRN
    if (poId) {
      await sql`
        INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
        VALUES (${docId}::uuid, 'purchase_order', ${poId}::uuid, 'po_invoice_link')
        ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
      `;
    }
    if (grnId) {
      await sql`
        INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
        VALUES (${docId}::uuid, 'goods_receipt_note', ${grnId}::uuid, 'grn_invoice_link')
        ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
      `;
    }

    // Reverse links: existing PO/GRN docs -> this invoice
    if (poId) {
      const poDocs = await sql`
        SELECT id FROM procurement_documents
        WHERE entity_type = 'purchase_order' AND entity_id = ${poId}::uuid AND is_active = true
      `;
      for (const doc of poDocs) {
        await sql`
          INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
          VALUES (${(doc as Record<string, unknown>).id as string}::uuid, 'supplier_invoice', ${invoiceId}::uuid, 'po_invoice_link')
          ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
        `;
      }
    }
    if (grnId) {
      const grnDocs = await sql`
        SELECT id FROM procurement_documents
        WHERE entity_type = 'goods_receipt_note' AND entity_id = ${grnId}::uuid AND is_active = true
      `;
      for (const doc of grnDocs) {
        await sql`
          INSERT INTO document_links (document_id, linked_entity_type, linked_entity_id, link_reason)
          VALUES (${(doc as Record<string, unknown>).id as string}::uuid, 'supplier_invoice', ${invoiceId}::uuid, 'grn_invoice_link')
          ON CONFLICT (document_id, linked_entity_type, linked_entity_id) DO NOTHING
        `;
      }
    }
  } catch (err) {
    log.warn('Auto-link supplier invoice docs failed (non-fatal)', { error: err }, 'accounting-docs');
  }
}

/** DELETE — Soft-delete a document */
async function handleDelete(req: NextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;
  if (!id) {
    return apiResponse.badRequest(res, 'Missing required query param: id');
  }

  const [row] = await sql`
    UPDATE procurement_documents
    SET is_active = false
    WHERE id = ${id}::uuid AND is_active = true
    RETURNING id
  `;

  if (!row) {
    return apiResponse.notFound(res, 'Document', id);
  }

  log.info('Accounting document soft-deleted', { data: { id } }, 'accounting-docs');
  return apiResponse.success(res, { id: row.id, deleted: true });
}

