### 9. QUERY BUILDING BEST PRACTICES FOR THIS CODEBASE

The codebase uses **raw SQL with Neon parameterization** (no ORM). Best practices:

**1. Always scope to company in WHERE clause:**
```typescript
const rows = await sql`
  SELECT * FROM customers
  WHERE company_id = ${companyId}
    AND is_active = true
  ORDER BY name ASC
`;
```

**2. For complex filters, build WHERE dynamically:**
```typescript
export async function getCustomers(
  companyId: string,
  filters?: CustomerFilters
): Promise<Customer[]> {
  let whereConditions = [`company_id = ${'company_id'}`];  // Always include
  let params = [companyId];
  let paramIndex = 1;

  if (filters?.status) {
    whereConditions.push(`status = $${++paramIndex}`);
    params.push(filters.status);
  }

  if (filters?.searchTerm) {
    whereConditions.push(`(name ILIKE $${++paramIndex} OR email ILIKE $${paramIndex})`);
    params.push(`%${filters.searchTerm}%`);
  }

  const whereClause = whereConditions.join(' AND ');
  const rows = await sql(`
    SELECT * FROM customers
    WHERE ${whereClause}
    ORDER BY name ASC
  `, params);

  return rows.map(mapCustomer);
}
```

**3. Use transactions for multi-step operations:**
```typescript
export async function createInvoice(
  companyId: string,
  invoiceData: InvoiceCreateInput,
  userId: string
): Promise<Invoice> {
  const [invoice, lines] = await transaction((txSql) => [
    txSql`
      INSERT INTO customer_invoices 
        (company_id, customer_id, invoice_number, invoice_date, total, created_by)
      VALUES (${companyId}, ${invoiceData.customerId}, ${invoiceData.invoiceNumber}, 
              ${invoiceData.date}, ${invoiceData.total}, ${userId})
      RETURNING *
    `,
    txSql`
      INSERT INTO invoice_lines 
        (invoice_id, company_id, gl_account_id, quantity, unit_price, ...)
      VALUES (${invoiceData.lines.map(l => `
        (${invoiceId}, ${companyId}, ${l.accountId}, ${l.quantity}, ...)
      `).join(',')})
      RETURNING *
    `
  ]);

  return mapInvoice(invoice[0], lines);
}
```

