    // Get user's default company or specified company
    const companies = await getUserCompanies(user.id);
    const selected = companies.find(c => !companyId || c.companyId === companyId)
                   || companies.find(c => c.isDefault);

    if (!selected) {
      return res.status(403).json({
        error: 'USER_HAS_NO_COMPANIES',
        message: 'User must be assigned to a company'
      });
    }

    (req as any).company = {
      id: selected.companyId,
      name: selected.companyName,
      role: selected.role
    };

    return handler(req, res);
  });
}
```

