/**
 * Accounting Module - Main Page
 * Tabbed interface: Overview, Chart of Accounts, Journal Entries, Fiscal Periods, Reports
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { log } from '@/lib/logger';
import Link from 'next/link';
import {
  Calculator,
  BookOpen,
  FileSpreadsheet,
  Calendar,
  BarChart3,
  Plus,
  ChevronRight,
  Loader2,
  AlertCircle,
  CheckCircle2,
  Clock,
  Lock,
  ArrowRight,
  TrendingUp,
  DollarSign,
  FileText,
  CreditCard,
  Landmark,
  Pencil,
  Trash2,
  Save,
  X,
} from 'lucide-react';
import {
  LineChart, Line, BarChart, Bar, PieChart, Pie, Cell,
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
} from 'recharts';
import type { GLAccount, GLAccountType, FiscalPeriod, JournalEntry, TrialBalanceRow } from '@/modules/accounting/types/gl.types';

type AccountingTab = 'overview' | 'chart-of-accounts' | 'journal-entries' | 'fiscal-periods' | 'reports';

const TABS: { id: AccountingTab; label: string; icon: React.ElementType }[] = [
  { id: 'overview', label: 'Overview', icon: Calculator },
  { id: 'chart-of-accounts', label: 'Chart of Accounts', icon: BookOpen },
  { id: 'journal-entries', label: 'Journal Entries', icon: FileSpreadsheet },
  { id: 'fiscal-periods', label: 'Fiscal Periods', icon: Calendar },
  { id: 'reports', label: 'Reports', icon: BarChart3 },
];

export default function AccountingPage() {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<AccountingTab>('overview');
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  // Sync tab from URL
  useEffect(() => {
    if (!isMounted) return;
    const tab = router.query.tab as AccountingTab;
    if (tab && TABS.some(t => t.id === tab)) {
      setActiveTab(tab);
    }
  }, [router.query.tab, isMounted]);

  const handleTabChange = useCallback((tab: AccountingTab) => {
    setActiveTab(tab);
    router.push({ pathname: '/accounting', query: { tab } }, undefined, { shallow: true });
  }, [router]);

  if (!isMounted) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <div className="text-center">
            <Loader2 className="h-8 w-8 animate-spin text-teal-500 mx-auto mb-2" />
            <p className="text-[var(--ff-text-secondary)]">Loading accounting module...</p>

/**
 * Next.js Edge Middleware
 * - app.isaflow.co.za: redirect / to /accounting (app domain — no landing page)
 * - isaflow.co.za: show landing page at /
 * - Redirects unauthenticated /accounting/* requests to /login
 */

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

const AUTH_COOKIE_NAME = 'ff_auth_token';

const PUBLIC_PATHS = ['/login', '/api/auth/login', '/api/auth/logout'];

/** Hostnames that should skip the landing page and go straight to the app */
const APP_HOSTS = ['app.isaflow.co.za'];

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const host = request.headers.get('host')?.split(':')[0] ?? '';

  // Allow public paths, static files, and API routes
  if (
    PUBLIC_PATHS.some(p => pathname.startsWith(p)) ||
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api/') ||
    pathname.startsWith('/icons') ||
    pathname.startsWith('/landing') ||
    pathname === '/manifest.json' ||
    pathname === '/sw.js' ||
    pathname === '/favicon.ico'
  ) {
    return NextResponse.next();
  }

  // app.isaflow.co.za: redirect root to /accounting
  if (pathname === '/' && APP_HOSTS.includes(host)) {
    return NextResponse.redirect(new URL('/accounting', request.url));
  }

  // Check for auth cookie on protected routes
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;

  if (!token && pathname.startsWith('/accounting')) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('returnTo', pathname);
    return NextResponse.redirect(loginUrl);
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/', '/accounting/:path*'],
};

server {
    listen 80;
    server_name fin.fibreflow.app;
    return 301 https://$server_name$request_uri;
}

server {
    listen 443 ssl http2;
    server_name fin.fibreflow.app;

    # SSL - use existing wildcard or generate with certbot
    ssl_certificate /etc/letsencrypt/live/fibreflow.app/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/fibreflow.app/privkey.pem;

    # Security headers
    add_header X-Frame-Options DENY;
    add_header X-Content-Type-Options nosniff;
    add_header X-XSS-Protection "1; mode=block";
    add_header Referrer-Policy "strict-origin-when-cross-origin";

    # Proxy to Next.js
    location / {
        proxy_pass http://127.0.0.1:3101;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_cache_bypass $http_upgrade;
        proxy_read_timeout 86400;
    }

    # Static assets caching
    location /_next/static {
        proxy_pass http://127.0.0.1:3101;
        proxy_cache_valid 200 365d;
        add_header Cache-Control "public, max-age=31536000, immutable";
    }

    # Maintenance page on 502/503
    error_page 502 503 /maintenance.html;
    location = /maintenance.html {
        root /var/www/html;
        internal;
    }
}

/**
 * JWT Utilities
 * Token signing and verification using jose library
 */

import { SignJWT, jwtVerify, JWTPayload as JosePayload } from 'jose';
import type { JWTPayload, AuthUser, AuthRole } from './types';

// Secret key for JWT signing - must be set in environment
const getJWTSecret = (): Uint8Array => {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    throw new Error('JWT_SECRET environment variable is not set');
  }
  return new TextEncoder().encode(secret);
};

// Token expiration times
const ACCESS_TOKEN_EXPIRY = '24h'; // 24 hours
const REFRESH_TOKEN_EXPIRY = '30d'; // 30 days

/**
 * Sign a JWT token for a user
 */
export async function signToken(
  user: AuthUser,
  sessionId: string,
  expiresIn: string = ACCESS_TOKEN_EXPIRY
): Promise<string> {
  const secret = getJWTSecret();

  const token = await new SignJWT({
    email: user.email,
    role: user.role,
    sessionId,
  })
    .setProtectedHeader({ alg: 'HS256' })
    .setSubject(user.id)
    .setIssuedAt()
    .setExpirationTime(expiresIn)
    .sign(secret);

  return token;
}

/**
 * Verify and decode a JWT token
 */
export async function verifyToken(token: string): Promise<JWTPayload | null> {
  try {
    const secret = getJWTSecret();
    const { payload } = await jwtVerify(token, secret);

    // Type assertion with validation
    if (!payload.sub || !payload.email || !payload.role || !payload.sessionId) {
      return null;
    }

    return {
      sub: payload.sub as string,
      email: payload.email as string,
      role: payload.role as AuthRole,
      permissions: [], // Permissions fetched from DB via getUserAndValidateSession()
      sessionId: payload.sessionId as string,
      iat: payload.iat || 0,
      exp: payload.exp || 0,
    };
  } catch (error) {
    // Token invalid or expired
    return null;
  }
}

/**
 * Decode token without verification (for debugging)
 */
export function decodeToken(token: string): JosePayload | null {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;

    const part = parts[1];
    if (!part) return null;
    const payload = JSON.parse(
      Buffer.from(part, 'base64url' as BufferEncoding).toString('utf-8')
    );
    return payload;
  } catch {
    return null;
  }
}

/**
 * Check if token is expired
 */
export function isTokenExpired(token: string): boolean {
  const decoded = decodeToken(token);
  if (!decoded || !decoded.exp) return true;

  return Date.now() >= decoded.exp * 1000;
}

/**
 * Get time until token expires (in seconds)
 */
export function getTokenExpiryTime(token: string): number {
  const decoded = decodeToken(token);
  if (!decoded || !decoded.exp) return 0;

  const expiresAt = decoded.exp * 1000;
  const now = Date.now();

  return Math.max(0, Math.floor((expiresAt - now) / 1000));
}

