/**
 * Run SQL migration using Neon serverless driver
 * Usage: bun run scripts/run-migration.ts scripts/migrations/sql/220_multi_company_scoping.sql
 */
import { neon } from '@neondatabase/serverless';
import * as fs from 'node:fs';

const DATABASE_URL = process.env.DATABASE_URL || 'postgresql://neondb_owner:npg_TDuKN9ao1sZB@ep-shiny-flower-aldyej0o-pooler.c-3.eu-central-1.aws.neon.tech/neondb?sslmode=require';

const sqlFile = process.argv[2];
if (!sqlFile) {
  console.error('Usage: bun run scripts/run-migration.ts <path-to-sql-file>');
  process.exit(1);
}

const sqlContent = fs.readFileSync(sqlFile, 'utf-8');
const sql = neon(DATABASE_URL);

async function run() {
  console.log(`Running migration: ${sqlFile}`);
  console.log('Connecting to database...');

  // Split on semicolons but handle dollar-quoted functions
  // Instead of splitting, run as a single transaction
  try {
    await sql.query(sqlContent, []);
    console.log('Migration completed successfully!');
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    console.error('Migration failed:', message);
    process.exit(1);
  }
}

run();

