            title={title}
            message={message}
            accent="text-red-400"
          />
        </div>
      ),
      { duration: 5000 }
    );
  },

  warning(title: string, message?: string) {
    return toast.custom(
      (t) => (
        <div
          className={`${t.visible ? 'animate-slide-up' : 'opacity-0 translate-y-2'}
            pointer-events-auto flex w-full max-w-sm rounded-xl
