/**
 * Bank Transaction Actions API
 * POST /api/accounting/bank-transactions-action
 *   action: match | unmatch | exclude | auto_match | allocate | delete | update_notes
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  matchTransaction,
  unmatchTransaction,
  excludeTransaction,
  autoMatchTransactions,
  allocateTransaction,
  splitAllocateTransaction,
  deleteTransactions,
  bulkAcceptTransactions,
  reverseReconciledTransaction,
  type AllocationType,
  type SplitLine,
} from '@/modules/accounting/services/bankReconciliationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { action, bankTransactionId, journalLineId, bankAccountId, reconciliationId, contraAccountId, description, allocationType, entityId, vatCode, excludeReason, cc1Id, cc2Id, buId } = req.body;
    // @ts-expect-error — auth middleware attaches user
    const userId: string = req.user?.id || req.user?.userId || 'system';

    if (!action) return apiResponse.badRequest(res, 'action is required');

    switch (action) {
      case 'match': {
        if (!bankTransactionId || !journalLineId) {
          return apiResponse.badRequest(res, 'bankTransactionId and journalLineId are required');
        }
        const tx = await matchTransaction(bankTransactionId, journalLineId, reconciliationId);
        return apiResponse.success(res, tx);
      }
      case 'unmatch': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
        const tx = await unmatchTransaction(bankTransactionId);
        return apiResponse.success(res, tx);
      }
      case 'exclude': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
        const tx = await excludeTransaction(
          bankTransactionId,
          typeof excludeReason === 'string' ? excludeReason : undefined,
        );
        return apiResponse.success(res, tx);
      }
      case 'auto_match': {
        if (!bankAccountId) return apiResponse.badRequest(res, 'bankAccountId is required');
        const result = await autoMatchTransactions(bankAccountId, reconciliationId);
        return apiResponse.success(res, result);
      }
      case 'allocate': {
        const aType: AllocationType = allocationType || 'account';
        if (aType === 'account' && !contraAccountId) {
          return apiResponse.badRequest(res, 'contraAccountId is required for account allocation');
        }
        if ((aType === 'supplier' || aType === 'customer') && !entityId) {
          return apiResponse.badRequest(res, 'entityId is required for supplier/customer allocation');
        }
        if (!bankTransactionId) {
          return apiResponse.badRequest(res, 'bankTransactionId is required');
        }
        const result = await allocateTransaction(
          bankTransactionId, contraAccountId || '', userId, description, aType, entityId, vatCode,
          cc1Id, cc2Id, buId,
        );
        return apiResponse.success(res, result);
      }
      case 'split_allocate': {
        const { bankTransactionId: splitTxId, lines: splitLines } = req.body as {
          bankTransactionId?: string;
          lines?: SplitLine[];
        };
        if (!splitTxId || !splitLines || !Array.isArray(splitLines) || splitLines.length === 0) {
          return apiResponse.badRequest(res, 'bankTransactionId and lines[] (non-empty) are required');
        }
        const splitResult = await splitAllocateTransaction(splitTxId, splitLines, userId);
        return apiResponse.success(res, splitResult);
      }
      case 'delete': {
        const { bankTransactionIds } = req.body;
        const ids: string[] = bankTransactionIds || (bankTransactionId ? [bankTransactionId] : []);
        if (ids.length === 0) return apiResponse.badRequest(res, 'bankTransactionId or bankTransactionIds required');
        const deleted = await deleteTransactions(ids);
        return apiResponse.success(res, { deleted });
      }
      case 'bulk_accept': {
        const { bankTransactionIds: bulkIds } = req.body;
        const ids: string[] = Array.isArray(bulkIds) ? bulkIds : [];
        if (ids.length === 0) return apiResponse.badRequest(res, 'bankTransactionIds (array) required');
        const accepted = await bulkAcceptTransactions(ids);
        return apiResponse.success(res, { accepted });
      }
      case 'update_notes': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        const { notes } = req.body as { notes?: string };
        await sql`
          UPDATE bank_transactions
          SET notes = ${notes || null}, updated_at = NOW()
          WHERE id = ${bankTransactionId}::UUID
        `;
        log.info('Updated bank transaction notes', { bankTransactionId }, 'accounting-api');
        return apiResponse.success(res, { updated: true });
      }
      case 'save_selection': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        const selType: string = req.body.selectionType || 'account';
        const selEntityId: string | null = req.body.selectionEntityId || null;
        await sql`
          UPDATE bank_transactions
          SET suggested_gl_account_id = ${selType === 'account' && selEntityId ? selEntityId : null}::UUID,
              suggested_supplier_id = ${selType === 'supplier' && selEntityId ? Number(selEntityId) : null},
              suggested_client_id = ${selType === 'customer' && selEntityId ? selEntityId : null}::UUID,
              updated_at = NOW()
          WHERE id = ${bankTransactionId}::UUID AND status = 'imported'
        `;
        return apiResponse.success(res, { saved: true });
      }
      case 'save_dimensions': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        await sql`
          UPDATE bank_transactions
          SET cc1_id = ${cc1Id || null}::UUID,
              cc2_id = ${cc2Id || null}::UUID,
              bu_id = ${buId || null}::UUID,
              updated_at = NOW()
          WHERE id = ${bankTransactionId}::UUID
        `;
        return apiResponse.success(res, { saved: true });
      }
      case 'reverse': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        await reverseReconciledTransaction(bankTransactionId, userId);
        return apiResponse.success(res, { reversed: true });
      }
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Action failed';
    log.error('Bank transaction action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * Manual Bank Transaction API — Spend Money / Receive Money
 * POST /api/accounting/bank-transactions-manual
 * Equivalent to Sage "Create Transaction" in Process Bank.
 *
 * Inserts a bank_transaction record and immediately allocates it
 * via the existing allocateTransaction service.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  allocateTransaction,
  type AllocationType,
} from '@/modules/accounting/services/bankReconciliationService';

// ── Types ─────────────────────────────────────────────────────────────────────

interface ManualTxBody {
  type: 'spend' | 'receive';
  bankAccountId: string;
  date: string;
  amount: number | string;
  reference?: string;
  description?: string;
  allocationType: AllocationType;
  /** GL account ID (when allocationType === 'account') */
  contraAccountId?: string;
  /** Supplier or Customer ID (when allocationType is supplier/customer) */
  entityId?: string;
  vatCode?: string;
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  // @ts-expect-error — auth middleware attaches user
  const userId: string = req.user?.id ?? req.user?.userId ?? 'system';

  const body = req.body as ManualTxBody;
  const {
    type,
    bankAccountId,
    date,
    amount: rawAmount,
    reference,
    description,
    allocationType,
    contraAccountId,
    entityId,
    vatCode,
  } = body;

  // ── Validation ─────────────────────────────────────────────────────────────

  if (!type || (type !== 'spend' && type !== 'receive')) {
    return apiResponse.badRequest(res, "type must be 'spend' or 'receive'");
  }
  if (!bankAccountId) {
    return apiResponse.badRequest(res, 'bankAccountId is required');
  }
  if (!date) {
    return apiResponse.badRequest(res, 'date is required');
  }
  const numericAmount = Number(rawAmount);
  if (!rawAmount || isNaN(numericAmount) || numericAmount <= 0) {
    return apiResponse.badRequest(res, 'amount must be a positive number');
  }
  if (!allocationType) {
    return apiResponse.badRequest(res, 'allocationType is required');
  }
  if (allocationType === 'account' && !contraAccountId) {
    return apiResponse.badRequest(res, 'contraAccountId is required when allocationType is account');
  }
  if ((allocationType === 'supplier' || allocationType === 'customer') && !entityId) {
    return apiResponse.badRequest(res, 'entityId is required when allocationType is supplier or customer');
  }

  // ── Amount sign — negative for spend, positive for receive ─────────────────

  const signedAmount = type === 'spend' ? -Math.abs(numericAmount) : Math.abs(numericAmount);

  try {
    // ── Step 1: Insert bank_transactions row ─────────────────────────────────

    const txRows = await sql`
      INSERT INTO bank_transactions (
        bank_account_id,
        transaction_date,
        amount,
        description,
        reference,
        status
      ) VALUES (
        ${bankAccountId}::UUID,
        ${date}::DATE,
        ${signedAmount},
        ${description ?? null},
        ${reference ?? null},
        'imported'
      )
      RETURNING id
    `;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const txId = String((txRows as any[])[0]!.id);

    log.info('Manual bank transaction created', {
      txId, type, bankAccountId, amount: signedAmount, date,
    }, 'accounting-api');

    // ── Step 2: Immediately allocate the transaction ──────────────────────────

    const result = await allocateTransaction(
      txId,
      contraAccountId ?? '',
      userId,
      description,
      allocationType,
      entityId,
      vatCode,
    );

    log.info('Manual bank transaction allocated', {
      txId, journalEntryId: result.journalEntryId,
    }, 'accounting-api');

    return apiResponse.created(res, {
      bankTransactionId: txId,
      journalEntryId: result.journalEntryId,
      bankTransaction: result.bankTransaction,
    }, 'Transaction recorded and allocated successfully');
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to record transaction';
    log.error('Manual bank transaction failed', { error: err }, 'accounting-api');
    return apiResponse.internalError(res, err, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * Bank Statement Import API
 * POST /api/accounting/bank-transactions-import
 *   Import CSV or PDF bank statement
 *
 * Body (CSV):
 *   { csvContent, bankAccountId, statementDate, bankFormat?, fileType?: 'csv' }
 *
 * Body (PDF):
 *   { pdfBase64, bankAccountId, statementDate, bankFormat?, fileType: 'pdf' }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { importBankStatement, importParsedTransactions } from '@/modules/accounting/services/bankReconciliationService';
import { parseBankPdf } from '@/modules/accounting/utils/bankPdfParser';
import type { BankFormat } from '@/modules/accounting/types/bank.types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const {
      csvContent,
      pdfBase64,
      fileType,
      bankAccountId,
      statementDate,
      bankFormat,
    } = req.body as {
      csvContent?: string;
      pdfBase64?: string;
      fileType?: 'csv' | 'pdf';
      bankAccountId: string;
      statementDate: string;
      bankFormat?: string;
    };

    if (!bankAccountId || !statementDate) {
      return apiResponse.badRequest(res, 'bankAccountId and statementDate are required');
    }

    const resolvedFileType: 'csv' | 'pdf' = fileType || (pdfBase64 ? 'pdf' : 'csv');

    if (resolvedFileType === 'pdf') {
      if (!pdfBase64) {
        return apiResponse.badRequest(res, 'pdfBase64 is required for PDF imports');
      }

      // Strip data-URL prefix if present: "data:application/pdf;base64,<data>"
      const base64Data = pdfBase64.includes(',') ? pdfBase64.split(',')[1]! : pdfBase64;
      const pdfBuffer = Buffer.from(base64Data, 'base64');

      log.info('Starting PDF bank statement import', {
        bankAccountId, statementDate, bankFormat, bufferSize: pdfBuffer.length,
      }, 'accounting-api');

      const parseResult = await parseBankPdf(pdfBuffer, bankFormat);

      if (parseResult.errors.length > 0 && parseResult.transactions.length === 0) {
        return apiResponse.badRequest(res, parseResult.errors[0]!.error);
      }

      const result = await importParsedTransactions(
        parseResult,
        String(bankAccountId),
        String(statementDate),
      );

      return apiResponse.created(res, result);
    }

    // Default: CSV import
    if (!csvContent) {
      return apiResponse.badRequest(res, 'csvContent is required for CSV imports');
    }

    const result = await importBankStatement(
      csvContent,
      String(bankAccountId),
      String(statementDate),
      (bankFormat || undefined) as BankFormat | undefined,
    );

    return apiResponse.created(res, result);
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to import bank statement';
    log.error('Failed to import bank statement', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * Classified Bank Transactions Import API
 * POST /api/accounting/bank-transactions-import-classified
 *   Import pre-classified bank transactions from worksheets.
 *
 * Body: { bankAccountId, transactions: ClassifiedBankTx[] }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

interface ClassifiedBankTx {
  transactionDate: string;
  description: string;
  debit?: number;
  credit?: number;
  category?: string;
  costCentreT1?: string;
  costCentreT2?: string;
  businessUnit?: string;
  statementRef?: string;
  source?: string;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { bankAccountId, transactions } = req.body as {
      bankAccountId: string;
      transactions: ClassifiedBankTx[];
    };

    if (!bankAccountId) {
      return apiResponse.badRequest(res, 'bankAccountId is required');
    }
    if (!Array.isArray(transactions) || transactions.length === 0) {
      return apiResponse.badRequest(res, 'transactions array is required');
    }

    // Verify bank account exists
    const bankCheck = (await sql`
      SELECT id FROM gl_accounts WHERE id = ${bankAccountId}::UUID LIMIT 1
    `) as Row[];
    if (bankCheck.length === 0) {
      return apiResponse.notFound(res, 'Bank account', bankAccountId);
    }

    // Pre-load category → GL account mapping from existing rules
    const ruleRows = (await sql`
      SELECT LOWER(rule_name) AS rule_name, gl_account_id, supplier_id
      FROM bank_categorisation_rules
      WHERE is_active = true
    `) as Row[];
    const categoryMap = new Map<string, { glAccountId: string; supplierId: number | null }>();
    for (const r of ruleRows) {
      categoryMap.set(String(r.rule_name).toLowerCase(), {
        glAccountId: String(r.gl_account_id),
        supplierId: r.supplier_id ? Number(r.supplier_id) : null,
      });
    }

    const batchId = crypto.randomUUID();
    let inserted = 0;
    let skippedDuplicates = 0;
    const unresolvedCategories: string[] = [];

    for (const tx of transactions) {
      const debit = Number(tx.debit || 0);
      const credit = Number(tx.credit || 0);
      // positive = deposit (credit), negative = withdrawal (debit)
      const amount = credit > 0 ? credit : -debit;
      if (amount === 0) continue;

      const txDate = String(tx.transactionDate).trim();
      const desc = String(tx.description || '').trim();
      if (!txDate || !desc) continue;

      // Deduplicate: check for existing transaction with same date + amount + description
      const dupeCheck = (await sql`
        SELECT id FROM bank_transactions
        WHERE bank_account_id = ${bankAccountId}::UUID
          AND transaction_date = ${txDate}
          AND amount = ${amount}
          AND description = ${desc}
        LIMIT 1
      `) as Row[];

      if (dupeCheck.length > 0) {
        skippedDuplicates++;
        continue;
      }

      // Resolve category → GL account
      const category = String(tx.category || '').trim();
      const categoryLower = category.toLowerCase();
      const mapping = categoryMap.get(categoryLower);
      const suggestedGlAccountId = mapping?.glAccountId || null;
      const suggestedSupplierId = mapping?.supplierId || null;

      if (category && !mapping && !unresolvedCategories.includes(category)) {
        unresolvedCategories.push(category);
      }

      const costCentre = [tx.costCentreT1, tx.costCentreT2]
        .filter(Boolean)
        .join(' > ')
        .trim() || null;

      await sql`
        INSERT INTO bank_transactions (
          bank_account_id, transaction_date, amount, description,
          reference, import_batch_id, status,
          suggested_gl_account_id, suggested_supplier_id,
          suggested_category, suggested_cost_centre
        ) VALUES (
          ${bankAccountId}::UUID, ${txDate}, ${amount}, ${desc},
          ${tx.statementRef || null}, ${batchId}::UUID, 'imported',
          ${suggestedGlAccountId}::UUID, ${suggestedSupplierId},
          ${category || null}, ${costCentre}
        )
      `;
      inserted++;
    }

    log.info('Imported classified bank transactions', {
      batchId, bankAccountId, inserted, skippedDuplicates,
      unresolvedCategories: unresolvedCategories.length,
    }, 'accounting');

    return apiResponse.created(res, {
      batchId,
      inserted,
      skippedDuplicates,
      unresolvedCategories: unresolvedCategories.length > 0 ? unresolvedCategories : undefined,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to import classified transactions';
    log.error('Failed to import classified bank transactions', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

