/**
 * Opening Balances Export API
 * GET — export GL opening balances as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    const rows = await sql`
      SELECT a.account_code, a.account_name, a.account_type, a.normal_balance,
        COALESCE(ob.debit, 0) AS opening_debit, COALESCE(ob.credit, 0) AS opening_credit
      FROM gl_accounts a
      LEFT JOIN (
        SELECT gl_account_id,
          SUM(CASE WHEN debit > 0 THEN debit ELSE 0 END) AS debit,
          SUM(CASE WHEN credit > 0 THEN credit ELSE 0 END) AS credit
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        WHERE je.source = 'opening_balance'
        GROUP BY gl_account_id
      ) ob ON ob.gl_account_id = a.id
      ORDER BY a.account_code
    `;

    const csvLines = [
      'Account Code,Account Name,Type,Normal Balance,Opening Debit,Opening Credit',
      ...rows.map((r: Record<string, unknown>) => [
        csvCell(String(r.account_code)),
        csvCell(String(r.account_name)),
        csvCell(String(r.account_type)),
        csvCell(String(r.normal_balance)),
        Number(r.opening_debit || 0).toFixed(2),
        Number(r.opening_credit || 0).toFixed(2),
      ].join(',')),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="opening-balances-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('Opening balances export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export opening balances');
  }
}

export default withAuth(handler);

/**
 * Recurring Journals API
 * GET  — list recurring journals
 * POST — create recurring journal
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  getRecurringJournals,
  createRecurringJournal,
} from '@/modules/accounting/services/recurringJournalService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { status, limit, offset } = req.query;
    const result = await getRecurringJournals({
      status: status as string,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
    return apiResponse.success(res, result);
  }

  if (req.method === 'POST') {
    const userId = req.user.id;
    try {
      const item = await createRecurringJournal(req.body, userId);
      return apiResponse.success(res, item);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Create failed';
      log.error('Recurring journal create failed', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, msg);
    }
  }

  if (req.method === 'PUT') {
    const { id, templateName, frequency, nextRunDate, description } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    try {
      await sql`
        UPDATE recurring_journals SET
          template_name = COALESCE(${templateName || null}, template_name),
          frequency = COALESCE(${frequency || null}, frequency),
          next_run_date = COALESCE(${nextRunDate || null}, next_run_date),
          description = COALESCE(${description || null}, description),
          updated_at = NOW()
        WHERE id = ${id}::UUID AND status IN ('active', 'paused')
      `;
      log.info('Recurring journal updated', { id });
      return apiResponse.success(res, { updated: true });
    } catch (err) {
      log.error('Recurring journal update failed', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Update failed');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * Recurring Journal Actions API
 * POST — pause, resume, cancel, generate
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  updateRecurringJournalStatus,
  generateJournalFromRecurring,
} from '@/modules/accounting/services/recurringJournalService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { action, id } = req.body;
    const userId = req.user.id;
    if (!action || !id) return apiResponse.badRequest(res, 'action and id are required');

    switch (action) {
      case 'pause':
        await updateRecurringJournalStatus(id, 'paused');
        return apiResponse.success(res, { status: 'paused' });
      case 'resume':
        await updateRecurringJournalStatus(id, 'active');
        return apiResponse.success(res, { status: 'active' });
      case 'cancel':
        await updateRecurringJournalStatus(id, 'cancelled');
        return apiResponse.success(res, { status: 'cancelled' });
      case 'generate': {
        const journalId = await generateJournalFromRecurring(id, userId);
        return apiResponse.success(res, { journalId });
      }
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Action failed';
    log.error('Recurring journal action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, msg);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

/**
 * Bank Rules Seed API
 * POST /api/accounting/bank-rules-seed
 *   Seed categorisation rules from a Category Map (JSON array).
 *
 * Body: { entries: [{ originalCategory, standardCategory, glCode }] }
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

interface CategoryMapEntry {
  originalCategory: string;
  standardCategory: string;
  glCode: number | string;
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const userId = req.user.id;
    const { entries } = req.body as { entries: CategoryMapEntry[] };

    if (!Array.isArray(entries) || entries.length === 0) {
      return apiResponse.badRequest(res, 'entries array is required');
    }

    let created = 0;
    let skipped = 0;
    const missingGlCodes: (number | string)[] = [];

    for (const entry of entries) {
      const pattern = String(entry.originalCategory || '').toLowerCase().trim();
      if (!pattern) { skipped++; continue; }

      const glCode = String(entry.glCode).trim();
      if (!glCode) { skipped++; continue; }

      // Look up GL account by account_code
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const glRows = (await sql`
        SELECT id FROM gl_accounts WHERE account_code = ${glCode} LIMIT 1
      `) as any[];

      if (glRows.length === 0) {
        missingGlCodes.push(entry.glCode);
        skipped++;
        continue;
      }

      const glAccountId = String(glRows[0].id);
      const ruleName = String(entry.standardCategory || entry.originalCategory).trim();

      // UPSERT — skip if match_pattern already exists
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const existing = (await sql`
        SELECT id FROM bank_categorisation_rules
        WHERE LOWER(match_pattern) = ${pattern} LIMIT 1
      `) as any[];

      if (existing.length > 0) {
        skipped++;
        continue;
      }

      await sql`
        INSERT INTO bank_categorisation_rules (
          rule_name, match_field, match_type, match_pattern,
          gl_account_id, auto_create_entry, priority, created_by
        ) VALUES (
          ${ruleName}, 'description', 'contains', ${pattern},
          ${glAccountId}::UUID, false, 100, ${userId}
        )
      `;
      created++;
    }

    log.info('Seeded bank categorisation rules', { created, skipped, missingGlCodes: missingGlCodes.length }, 'accounting');

    return apiResponse.success(res, {
      created,
      skipped,
      missingGlCodes: missingGlCodes.length > 0 ? missingGlCodes : undefined,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to seed bank rules';
    log.error('Failed to seed bank rules', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withRole('admin')(withErrorHandler(handler as any)));

/**
 * Smart Categorization API
 * GET  — get suggestions for a single transaction
 * POST — bulk categorize transactions or learn from allocation
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  categorizeBankTransaction,
  bulkCategorize,
  smartCategorizeForAccount,
  learnFromAllocation,
} from '@/modules/accounting/services/smartCategorizationService';
import { sql } from '@/lib/neon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  // ── GET: Single transaction suggestion ─────────────────────────────────────
  if (req.method === 'GET') {
    const { txId } = req.query;
    if (!txId || typeof txId !== 'string') {
      return apiResponse.badRequest(res, 'txId query parameter required');
    }

    try {
      const txRows = (await sql`
        SELECT id, description, amount, reference
        FROM bank_transactions WHERE id = ${txId}::UUID
      `) as Row[];

      if (txRows.length === 0) {
        return apiResponse.notFound(res, 'Transaction', txId);
      }

      const tx = txRows[0];
      const result = await categorizeBankTransaction({
        description: String(tx.description || ''),
        amount: Number(tx.amount),
        reference: tx.reference ? String(tx.reference) : undefined,
      });

      return apiResponse.success(res, {
        transactionId: txId,
        suggestion: result,
      });
    } catch (err) {
      log.error('Smart categorize GET failed', { txId, error: err }, 'accounting-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed');
    }
  }

  // ── POST: Bulk categorize or learn ─────────────────────────────────────────
  if (req.method === 'POST') {
    const { action, transactionIds, bankAccountId, txId, glAccountId, category, vatCode } = req.body;

    try {
      switch (action || 'categorize') {
        case 'categorize': {
          // If bankAccountId provided, categorize all uncategorized for that account
          if (bankAccountId) {
            const result = await smartCategorizeForAccount(bankAccountId);
            return apiResponse.success(res, result);
          }
          // Otherwise, categorize specific transaction IDs
          if (!Array.isArray(transactionIds) || transactionIds.length === 0) {
            return apiResponse.badRequest(res, 'transactionIds array or bankAccountId required');
          }
          const result = await bulkCategorize(transactionIds);
          return apiResponse.success(res, result);
        }

        case 'learn': {
