/**
 * Company-scoped authentication middleware.
 * Wraps withAuth and adds company context from X-Company-Id header
 * or the user's default company.
 */

import type { NextApiRequest, NextApiResponse, NextApiHandler } from 'next';
import { sql } from '@/lib/neon';
import { withAuth, type AuthenticatedNextApiRequest } from './middleware';
import { log } from '@/lib/logger';

export interface CompanyApiRequest extends AuthenticatedNextApiRequest {
  companyId: string;
  companyRole: string;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type CompanyHandler = (req: NextApiRequest, res: NextApiResponse<any>) => any;

/**
 * Middleware that requires authentication AND resolves the active company.
 *
 * Company resolution order:
 * 1. X-Company-Id request header (set by frontend CompanyContext)
 * 2. User's default company (is_default = true in company_users)
 * 3. First company the user belongs to
 *
 * Attaches companyId and companyRole to the request object.
 */
export function withCompany(handler: CompanyHandler): NextApiHandler {
  return withAuth(async (req: NextApiRequest, res: NextApiResponse) => {
    try {
      const authReq = req as AuthenticatedNextApiRequest;
      const userId = authReq.user.id;

      // 1. Try X-Company-Id header
      let companyId = req.headers['x-company-id'] as string | undefined;

      if (companyId) {
        // Validate user has access to this specific company
        const access = await sql`
          SELECT role FROM company_users
          WHERE user_id = ${userId} AND company_id = ${companyId}::UUID
          LIMIT 1
        `;

        if (access.length === 0) {
          return res.status(403).json({
            success: false,
            error: { code: 'FORBIDDEN', message: 'You do not have access to this company' },
          });
        }

        (req as CompanyApiRequest).companyId = companyId;
        (req as CompanyApiRequest).companyRole = access[0].role as string;
        return handler(req, res);
      }

      // 2. Fall back to user's default or first company
      const companies = await sql`
        SELECT company_id, role, is_default
        FROM company_users
        WHERE user_id = ${userId}
        ORDER BY is_default DESC, created_at ASC
        LIMIT 1
      `;

      if (companies.length === 0) {
        return res.status(400).json({
          success: false,
          error: { code: 'NO_COMPANY', message: 'No company assigned. Please contact an administrator.' },
        });
      }

      (req as CompanyApiRequest).companyId = companies[0].company_id as string;
      (req as CompanyApiRequest).companyRole = companies[0].role as string;
      return handler(req, res);
    } catch (error) {
      log.error('Company middleware error', error instanceof Error ? { message: error.message } : { error }, 'CompanyMiddleware');
      return res.status(500).json({
        success: false,
        error: { code: 'COMPANY_ERROR', message: 'Failed to resolve company context' },
      });
    }
  });
}

/**
 * Bank Reconciliation Report Data API
 * GET /api/accounting/bank-reconciliation-report?bankAccountId=<uuid>
 *
 * Returns matched and unmatched transaction data alongside statement balances
 * for rendering the PDF reconciliation report on the client.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// ─── Row types returned from DB ───────────────────────────────────────────────

type TxRow = {
  id: string;
  transaction_date: string | Date;
  description: string | null;
  reference: string | null;
  amount: string | number;
  journal_entry_number: string | null;
};

type BatchRow = {
  opening_balance: string | null;
  closing_balance: string | null;
  statement_date: string | Date;
};

type AccountRow = {
  account_name: string;
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

function toDateStr(d: string | Date): string {
  if (d instanceof Date) return d.toISOString().split('T')[0] ?? '';
  return String(d).split('T')[0] ?? '';
}

async function fetchBankAccountName(bankAccountId: string): Promise<string> {
  const rows = (await sql`
    SELECT account_name
    FROM gl_accounts
    WHERE id = ${bankAccountId}::UUID
    LIMIT 1
  `) as AccountRow[];
  return rows[0]?.account_name ?? 'Unknown Account';
}

async function fetchLatestBatch(bankAccountId: string): Promise<BatchRow | null> {
  const rows = (await sql`
    SELECT opening_balance, closing_balance, statement_date
    FROM bank_import_batches
    WHERE bank_account_id = ${bankAccountId}::UUID
    ORDER BY created_at DESC
    LIMIT 1
  `) as BatchRow[];
  return rows[0] ?? null;
}

async function fetchMatchedTransactions(bankAccountId: string): Promise<TxRow[]> {
  return (await sql`
    SELECT
      bt.id,
      bt.transaction_date,
      bt.description,
      bt.reference,
      bt.amount,
      je.entry_number AS journal_entry_number
    FROM bank_transactions bt
    LEFT JOIN gl_journal_lines jl ON jl.id = bt.matched_journal_line_id
    LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    WHERE bt.bank_account_id = ${bankAccountId}::UUID
      AND bt.status = 'matched'
    ORDER BY bt.transaction_date
  `) as TxRow[];
}

async function fetchUnmatchedTransactions(bankAccountId: string): Promise<TxRow[]> {
  return (await sql`
    SELECT
      bt.id,
      bt.transaction_date,
      bt.description,
      bt.reference,
      bt.amount,
      NULL::TEXT AS journal_entry_number
    FROM bank_transactions bt
    WHERE bt.bank_account_id = ${bankAccountId}::UUID
      AND bt.status = 'imported'
    ORDER BY bt.transaction_date
  `) as TxRow[];
}

// ─── Handler ──────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { bankAccountId } = req.query;

  if (!bankAccountId || typeof bankAccountId !== 'string' || bankAccountId.trim() === '') {
    return apiResponse.badRequest(res, 'bankAccountId query parameter is required');
  }

  try {
    // Parallel fetch: account name, latest batch, matched and unmatched transactions
    const [bankAccountName, latestBatch, matchedRows, unmatchedRows] = await Promise.all([
      fetchBankAccountName(bankAccountId),
      fetchLatestBatch(bankAccountId),
      fetchMatchedTransactions(bankAccountId),
      fetchUnmatchedTransactions(bankAccountId),
    ]);

    const mapTx = (row: TxRow) => ({
      date: toDateStr(row.transaction_date),
      description: row.description ?? '',
      amount: Number(row.amount),
      reference: row.reference ?? undefined,
      journalRef: row.journal_entry_number ?? undefined,
    });

    return apiResponse.success(res, {
      bankAccountName,
      statementDate: latestBatch ? toDateStr(latestBatch.statement_date) : '',
      openingBalance:
        latestBatch?.opening_balance !== null && latestBatch?.opening_balance !== undefined
          ? Number(latestBatch.opening_balance)
          : null,
      closingBalance:
        latestBatch?.closing_balance !== null && latestBatch?.closing_balance !== undefined
          ? Number(latestBatch.closing_balance)
          : null,
      matchedTransactions: matchedRows.map(mapTx),
      unmatchedTransactions: unmatchedRows.map(mapTx),
    });
  } catch (err) {
    log.error('Failed to get bank reconciliation report data', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to get bank reconciliation report data');
  }
}

