            AND je.entry_date >= ${periodStart}
            AND je.entry_date <= ${periodEnd}
        `;
        investingChange = Number(row?.change || 0);
      } else {
        const [row] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric AS change
